# [2] ENGINE
# ══════════════════════════════════════════════════════════════════════

DB_PATH = os.getenv("LIFE_DB", "life.db")
DAY = 3600              # 1 game day = 1 real hour
YEAR = 24 * DAY         # 1 game year = 1 real day
CAP = 6 * DAY           # max offline time that can hurt you (hp/mood/risk)
ICAP = 12 * DAY         # max time interest/bills accrue
ENERGY_REGEN = 180      # sec per +1 energy (x home comfort)
HUNGER_RATE = 300
HEAT_DECAY = 120
EVENT_CD = 600
KID_COST = 20

db = sqlite3.connect(DB_PATH, check_same_thread=False)
db.execute("CREATE TABLE IF NOT EXISTS players(uid INTEGER PRIMARY KEY, data TEXT)")
db.execute("CREATE TABLE IF NOT EXISTS kv(k TEXT PRIMARY KEY, v TEXT)")
db.commit()

ADD_INFO = {"nic": ("Никотин", 5, 0.2), "alc": ("Алкоголь", 4, 0.35), "caf": ("Кофеин", 8, 0.1), "gam": ("Азарт", 4, 0.2)}
for _k, _v in DRUGS.items():
    ADD_INFO[_k] = (_v[0], 3, 0.3)


# ───────────────────────── helpers ─────────────────────────
def fmt(n):
    return f"{int(n):,}".replace(",", " ")


def bar(v):
    v = max(0, min(100, int(v)))
    return "▰" * (v // 10) + "▱" * (10 - v // 10)


def logp(p, t):
    p["log"] = (p["log"] + [t])[-5:]


def cdleft(p, k):
    return max(0.0, p["cd"].get(k, 0) - time.time())


def debt_total(p, kind=None):
    return sum(d["amt"] for d in p["debts"] if kind is None or d["kind"] == kind)


def networth(p):
    v = p["cash"] + p["bank"] - debt_total(p)
    if p["home_own"]:
        v += HOUSING[p["home"]][1] * cm(p, 1) * 0.85
    if p["car"]:
        v += CARS[p["car"]][1] * 0.7
    for k, b in p["biz"].items():
        v += BIZ[k][1] * 0.6
    return v


def age(p):
    return p.get("age0", 18) + int((time.time() - p["born"]) / YEAR)


def motor(p):
    return p["car"] is not None and p["car"] not in ("bike", "scoot")


def comfort(p):
    return HOUSING[p["home"]][3]


def daily_cost(p):
    h = HOUSING[p["home"]]
    rent = 0 if p["home_own"] else h[2] * cm(p, 1)
    if any(g.get("live") for g in p["girls"]):
        rent *= 0.6
    c = h[4] * cm(p, 3) + rent
    c += sum(KID_COST * (3 if k.get("sick") else 1) for k in p["kids"])
    c += sum(PETS[x][2] for x in p["pets"])
    if p["car"]:
        c += CARS[p["car"]][5]
    return c


def tolerance(p, k):
    return max(0.25, 1 - p["add"].get(k, 0) / 150)


def new_player(uid, name):
    now = time.time()
    return dict(
        uid=uid, name=name, born=now, last=now, cash=500.0, bank=0.0, hp=100.0, energy=100.0, mood=60.0, hunger=0.0,
        drunk=0.0, hang=0.0, job=None, xp=0, edu=0, lic=False, study=None,
        skill=dict(str=0.0, int=0.0, cha=0.0, stealth=0.0, drive=0.0, hack=0.0, cook=0.0, crime=0.0),
        heat=0.0, jail=0.0, jailed=0, cd={}, inv={}, add={}, lastuse={}, debts=[], credit=50, dis={}, rx=0.0,
        home="hostel", home_own=False, car=None, fuel=0.0, cond=100.0, biz={}, port={}, pets=[],
        girls=[], kids=[], pending=[], pref="f", spouse=None, smoked=0, drank=0, earned=0.0, deaths=0,
        log=["новая жизнь началась"], ach=[], cod="", lastdaily=0.0, streak=0,
        city=random.choice(list(CITIES)), age0=random.randint(18, 30), vaped=0, snused=0, hooked=0, ui_alc="",
    )


def save(p):
    db.execute("INSERT OR REPLACE INTO players(uid,data) VALUES(?,?)", (p["uid"], json.dumps(p, ensure_ascii=False)))
    db.commit()


def load_raw(uid):
    row = db.execute("SELECT data FROM players WHERE uid=?", (uid,)).fetchone()
    return json.loads(row[0]) if row else None


def get_player(user):
    name = user.first_name or "Аноним"
    p = load_raw(user.id)
    base = new_player(user.id, name)
    if p:
        p.setdefault("age0", 18)
        p.setdefault("city", "samara")
        for k, v in base.items():
            p.setdefault(k, v)
        for k, v in base["skill"].items():
            p["skill"].setdefault(k, v)
        p["name"] = name
    else:
        p = base
    tick(p)
    return p


def clamp(p):
    for k in ("hp", "energy", "mood", "hunger"):
        p[k] = max(0.0, min(100.0, p[k]))
    p["drunk"] = max(0.0, min(120.0, p["drunk"]))
    p["heat"] = max(0.0, p["heat"])
    p["cash"] = max(0.0, p["cash"])
    p["bank"] = max(0.0, p["bank"])
    for k in list(p["add"]):
        p["add"][k] = max(0.0, min(100.0, p["add"][k]))
        if p["add"][k] <= 0:
            del p["add"][k]


# ───────────────────────── diseases ─────────────────────────
def catch(p, k):
    if k in p["dis"]:
        return
    hidden = DIS[k][7]
    p["dis"][k] = {"since": time.time(), "dx": not hidden}
    logp(p, "заболел: " + DIS[k][0] if not hidden else "самочувствие странное, надо бы провериться")


def risk_tick(p, days):
    if days <= 0:
        return

    def roll(x):
        return random.random() < 1 - (1 - min(x, 0.95)) ** days

    vuln = 1 + (100 - p["hp"]) / 100 + (0.5 if p["hunger"] > 60 else 0) + (1 if p["home"] == "street" else 0) + (0.5 if p["energy"] < 20 else 0)
    vuln += cm(p, 4) * 0.15
    if roll(0.05 * vuln):
        catch(p, random.choice(["cold", "cold", "cold", "flu", "flu", "covid", "allerg", "migr", "tooth"]))
    if p["mood"] < 20 and roll(0.08):
        catch(p, random.choice(["depr", "anx", "insom"]))
    a = age(p)
    if a > 40 and roll(0.01 * (a - 40) / 10 * vuln):
        catch(p, random.choice(["htn", "diab", "heart", "stroke"]))
    if p["smoked"] > 100 and roll(min(0.1, p["smoked"] / 6000)):
        catch(p, "bronch")
    if p["smoked"] > 500 and roll(min(0.08, p["smoked"] / 20000)):
        catch(p, "cancer")
    if p["drank"] > 40 and roll(min(0.1, p["drank"] / 1500)):
        catch(p, "gastr")
    if p["drank"] > 250 and roll(min(0.06, p["drank"] / 9000)):
        catch(p, "cirr")
    if p["drank"] > 80 and roll(min(0.06, p["drank"] / 4000)):
        catch(p, "steat")
    if p["drank"] > 150 and roll(min(0.05, p["drank"] / 7000)):
        catch(p, random.choice(["pancr", "gout"]))
    if p.get("snused", 0) > 100 and roll(min(0.08, p["snused"] / 8000)):
        catch(p, "gingiv")
    if p.get("snused", 0) > 600 and roll(min(0.05, p["snused"] / 40000)):
        catch(p, "oralca")
    if p.get("vaped", 0) > 100 and roll(min(0.06, p["vaped"] / 12000)):
        catch(p, "bronch")
    if p.get("vaped", 0) > 150 and roll(min(0.05, p["vaped"] / 30000)):
        catch(p, "evali")
    if p.get("hooked", 0) > 15 and roll(min(0.06, p["hooked"] / 3000)):
        catch(p, "bronch")


def disease_tick(p, days, now):
    for k, d in list(p["dis"].items()):
        name, chronic, hp, mood, en, heal, lethal, hidden, cost = DIS[k]
        if d.get("managed", 0) > now:
            continue
        p["hp"] -= hp * days
        p["mood"] -= mood * days
        p["energy"] -= en * days
        if heal > 0 and random.random() < 1 - (1 - heal) ** days:
            del p["dis"][k]
            logp(p, f"выздоровел: {name}")
            continue
        if lethal > 0 and random.random() < 1 - (1 - lethal * (2 if p["hp"] < 30 else 1)) ** days:
            p["hp"] = 0
            p["cod"] = name


# ───────────────────────── tick ─────────────────────────
def tick(p):
    now = time.time()
    dt = max(0.0, now - p["last"])
    p["last"] = now
    days = min(dt, CAP) / DAY
    p["energy"] += dt / ENERGY_REGEN * comfort(p) * (0.6 if p["drunk"] > 60 else 1)
    p["hunger"] += min(dt, CAP) / HUNGER_RATE
    p["heat"] -= dt / HEAT_DECAY
    p["drunk"] -= days * 60
    if p["hunger"] > 80:
        p["hp"] -= days * 30
        p["cod"] = "голод"
    if now < p["hang"] and p["drunk"] < 20:
        p["mood"] -= 15 * days
        p["energy"] -= 10 * days

    idays = min(dt, ICAP) / DAY
    for d in p["debts"]:
        d["amt"] *= (1 + d["rate"]) ** idays
        if now > d["due"]:
            if d["kind"] == "shark" and now > d.get("hit", 0):
                d["hit"] = now + DAY / 2
                loss = min(p["cash"], d["amt"] * 0.2)
                p["cash"] -= loss
                p["hp"] -= 15
                p["cod"] = "коллекторы"
                logp(p, f"коллекторы нашли тебя: -{fmt(loss)}$ и рёбра")
            elif d["kind"] == "bank" and not d.get("flag"):
                d["flag"] = 1
                p["credit"] = max(0, p["credit"] - 20)
                logp(p, "просрочка по кредиту: рейтинг упал")
            elif d["kind"] == "mortgage" and not d.get("flag"):
                d["flag"] = 1
                p["debts"] = [x for x in p["debts"] if x is not d]
                p["home"], p["home_own"] = "street", False
                logp(p, "банк забрал жильё за долги по ипотеке")
                break

    cost = daily_cost(p) * idays
    pay = min(p["cash"], cost)
    p["cash"] -= pay
    short = cost - pay
    if short > 0.5:
        for d in p["debts"]:
            if d["kind"] == "bills":
                d["amt"] += short
                break
        else:
            p["debts"].append(dict(kind="bills", amt=short, rate=0.05, due=now + DAY))
    if not p["home_own"] and p["home"] != "street" and debt_total(p, "bills") > max(50, daily_cost(p) * 8):
        p["home"] = "street"
        p["debts"] = [d for d in p["debts"] if d["kind"] != "bills"]
        logp(p, "тебя выселили за неуплату")

    for k, v in list(p["add"].items()):
        label, decay, wd = ADD_INFO.get(k, ("?", 3, 0.3))
        if v > 20 and now - p["lastuse"].get(k, 0) > DAY / 3:
            p["mood"] -= days * v * wd
            p["hp"] -= days * v * 0.04 * (2.5 if k in ("alc", "her") and v > 60 else 1)
            if k == "alc" and v > 70 and random.random() < min(0.5, days * 0.3):
                catch(p, "delir")
        p["add"][k] = max(0.0, v - days * decay)

    disease_tick(p, days, now)
    risk_tick(p, days)

    if p["pets"]:
        p["mood"] += sum(PETS[x][3] for x in p["pets"]) * days * 0.5
    for g in list(p["girls"]):
        g["rel"] -= days * (0.5 if p["spouse"] == g["name"] else 2)
        if g["rel"] <= 0:
            p["girls"].remove(g)
            logp(p, f"{g['name']} ушла(ёл) из твоей жизни")
    if p["spouse"] and not any(g["name"] == p["spouse"] for g in p["girls"]):
        p["spouse"] = None
    for k in p["kids"]:
        k["bond"] = max(0, k["bond"] - days * 1)
    for b in list(p["pending"]):
        if now >= b["t"]:
            p["pending"].remove(b)
            fee = min(p["cash"], 400)
            p["cash"] -= fee
            kid = {"name": random.choice(KID_NAMES), "born": now, "bond": 50, "sick": False}
            p["kids"].append(kid)
            p["mood"] += 25
            logp(p, f"родился ребёнок: {kid['name']} (роды -{fmt(fee)}$)")
    if p["jail"] and now >= p["jail"]:
        p["jail"] = 0
        logp(p, "тебя выпустили")
    try:
        p10_tick(p)
    except Exception:
        pass
    clamp(p)


def die(p):
    cause = p.get("cod") or "здоровье не выдержало"
    deaths = p["deaths"] + 1
    wealth = max(0, p["cash"] + p["bank"] - debt_total(p))
    fresh = new_player(p["uid"], p["name"])
    fresh["deaths"] = deaths
    fresh["pref"] = p["pref"]
    fresh["city"] = p.get("city", "samara")
    if p.get("p10", {}).get("will_set") and wealth > 0:
        fresh["cash"] = wealth * 0.6
        logp(fresh, f"получено наследство по завещанию: {fmt(fresh['cash'])}$")
    fresh["ach"] = p["ach"]
    msg = f"☠ ты умер. причина: {cause}."
    if p["kids"]:
        kid = max(p["kids"], key=lambda k: k["bond"])
        fresh["name"] = p["name"]
        fresh["cash"] = 500 + wealth * 0.5
        fresh["home"], fresh["home_own"] = p["home"], p["home_own"]
        fresh["car"], fresh["fuel"], fresh["cond"] = p["car"], p["fuel"], p["cond"]
        fresh["biz"] = p["biz"]
        fresh["kids"] = [k for k in p["kids"] if k is not kid]
        msg += f" играешь за наследника {kid['name']} (50% денег, жильё, авто, бизнес)."
    else:
        msg += " начинаешь с нуля."
    p.clear()
    p.update(fresh)
    return msg


def finalize(p):
    clamp(p)
    for k, (txt, cond) in ACHIEVEMENTS.items():
        if k not in p["ach"] and cond(p):
            p["ach"].append(k)
            logp(p, f"🏅 достижение: {txt}")
    if p["hp"] <= 0:
        return die(p)
    return None


# ───────────────────────── random events ─────────────────────────
def rand_event(p):
    if cdleft(p, "event") > 0:
        return
    p["cd"]["event"] = time.time() + EVENT_CD
    if random.random() > 0.55:
        return
    e = random.choice(["find", "robbed", "lotto", "breakdown", "parking", "police", "friend", "text", "birthday", "bonus", "layoff",
                       "flood", "heir", "scam", "fight", "bite", "pizza", "compliment", "boss", "kidsick", "sale", "stray", "charity"])
    c = p["cash"]
    if e == "find":
        x = random.randint(20, 150)
        p["cash"] += x
        logp(p, f"нашёл на улице {x}$")
    elif e == "robbed":
        x = min(c, random.randint(30, 200))
        p["cash"] -= x
        p["mood"] -= 8
        logp(p, f"тебя обчистили: -{fmt(x)}$")
    elif e == "lotto" and random.random() < 0.2:
        x = random.randint(200, 3000)
        p["cash"] += x
        logp(p, f"выиграл в лотерею {fmt(x)}$")
    elif e == "breakdown" and motor(p):
        x = min(c, random.randint(50, 300))
        p["cash"] -= x
        p["cond"] -= 10
        logp(p, f"машина сломалась, ремонт -{fmt(x)}$")
    elif e == "parking" and motor(p):
        x = min(c, 60)
        p["cash"] -= x
        logp(p, f"штраф за парковку -{x}$")
    elif e == "police" and p["heat"] > 20:
        x = min(c, 100 + p["heat"])
        p["cash"] -= x
        logp(p, f"остановили, нашли к чему придраться: -{fmt(x)}$")
    elif e == "friend":
        p["mood"] += 10
        logp(p, "друг позвал посидеть, стало легче")
    elif e == "text" and p["girls"]:
        g = random.choice(p["girls"])
        g["rel"] += 4
        logp(p, f"{g['name']} написала(ал) что скучает (+отношения)")
    elif e == "birthday":
        p["mood"] += 5
        p["cash"] += 50
        logp(p, "день рождения: подарили 50$")
    elif e == "bonus" and p["job"] is not None:
        x = random.randint(*JOBS[p["job"]][3]) * 2
        p["cash"] += x
        logp(p, f"премия на работе +{x}$")
    elif e == "layoff" and p["job"] is not None and random.random() < 0.15:
        p["job"] = None
        p["mood"] -= 12
        logp(p, "сократили, ты безработный")
    elif e == "flood" and p["home"] != "street":
        x = min(c, 200)
        p["cash"] -= x
        logp(p, f"соседи затопили, ремонт -{x}$")
    elif e == "heir" and random.random() < 0.1:
        x = random.randint(1000, 8000)
        p["cash"] += x
        logp(p, f"дальний родственник оставил наследство {fmt(x)}$")
    elif e == "scam":
        x = min(c, 120)
        p["cash"] -= x
        logp(p, f"развели по телефону на {x}$")
    elif e == "fight":
        catch(p, random.choice(["conc", "fract"])) if random.random() < 0.3 else None
        p["hp"] -= 8
        p["mood"] -= 5
        logp(p, "ввязался в драку")
    elif e == "bite" and p["pets"]:
        logp(p, "питомец устроил погром дома")
        p["mood"] -= 2
    elif e == "pizza":
        p["hunger"] -= 20
        logp(p, "угостили пиццей")
    elif e == "compliment":
        p["mood"] += 6
        logp(p, "незнакомка сделала комплимент")
    elif e == "boss" and p["job"] is not None:
        p["mood"] -= 7
        logp(p, "начальник орал на планёрке")
    elif e == "kidsick" and p["kids"]:
        k = random.choice(p["kids"])
        k["sick"] = True
        logp(p, f"{k['name']} заболел(а), расходы выросли, вылечи в разделе «Семья»")
    elif e == "sale":
        logp(p, "в Пятёрочке акция, но тебе без разницы")
    elif e == "stray":
        p["mood"] += 3
        logp(p, "погладил бездомную собаку")
    elif e == "charity":
        x = min(c, 30)
        p["cash"] -= x
        p["mood"] += 4
        logp(p, f"отдал {x}$ на благотворительность, на душе теплее")


# ───────────────────────── actions: each returns a note ─────────────────────────
def need(p, cash=0, energy=0):
    if p["cash"] < cash:
        return f"нужно {fmt(cash)}$"
    if p["energy"] < energy:
        return f"нужно {energy} энергии"
    return ""


def dui(p):
    if p["drunk"] > 30 and random.random() < 0.35:
        fee = min(p["cash"], 400)
        p["cash"] -= fee
        p["heat"] += 20
        if p["drunk"] > 60:
            p["jail"] = time.time() + 600
            p["jailed"] += 1
        return f" ⚠ ГИБДД: пьяный за рулём, штраф {fmt(fee)}$" + (" и ночь в обезьяннике" if p["drunk"] > 60 else "")
    return ""


def sick_now(p):
    now = time.time()
    return any(d.get("managed", 0) <= now for d in p["dis"].values())


def act_work(p, a, arg):
    if a == "pick":
        i = int(arg)
        name, xp, edu, pay, en, nd, risk = JOBS[i]
        if p["xp"] < xp:
            return f"рано, нужен опыт {xp}"
        if p["edu"] < edu:
            return f"нужно образование уровня {edu}"
        if nd == "car" and not motor(p):
            return "нужна машина или мотоцикл"
        p["job"] = i
        return f"теперь ты: {name}"
    if a == "quit":
        p["job"] = None
        return "уволился"
    if a == "do":
        if p["job"] is None:
            return "сначала выбери работу"
        name, xp, edu, (lo, hi), en, nd, risk = JOBS[p["job"]]
        if p["energy"] < en:
            return "нет сил, отдохни"
        if nd == "car":
            use = max(1, CARS[p["car"]][2] * 4) if p["car"] else 99
            if not motor(p) or p["cond"] < 15:
                return "машина не на ходу: в раздел «Машина»"
            if CARS[p["car"]][2] > 0 and p["fuel"] < use:
                return "нет бензина"
            p["fuel"] -= CARS[p["car"]][2] * 4
            p["cond"] -= 0.5
        note = dui(p) if nd == "car" else ""
        p["energy"] -= en
        mult = (1 + (p["skill"]["int"] + p["skill"]["cha"]) / 400) * cm(p, 2)
        if p["mood"] < 30:
            mult *= 0.75
        if sick_now(p):
            mult *= 0.8
        if p["car"] and "Курьер" in name:
            mult *= 1.2
        pay = int(random.randint(lo, hi) * mult)
        p["cash"] += pay
        p["earned"] += pay
        p["xp"] += random.randint(4, 8)
        p["mood"] -= 2
        p["hunger"] += 3
        if risk and random.random() < 0.03:
            catch(p, risk)
        return f"смена ({name}): +{pay}$" + note
    return ""


def act_edu(p, a, arg):
    if a == "start":
        name, cost, sess, req, give, sk, gain, xp = COURSES[arg]
        if p["study"]:
            return "сначала закончи или брось текущий курс"
        if p["edu"] < req:
            return "нет базового образования"
        if arg == "lic" and p["lic"]:
            return "права уже есть"
        if p["cash"] < cost:
            return f"нужно {fmt(cost)}$"
        p["cash"] -= cost
        p["study"] = {"c": arg, "n": 0}
        return f"записался: {name} ({sess} занятий)"
    if a == "study":
        s = p["study"]
        if not s:
            return "ты нигде не учишься"
        name, cost, sess, req, give, sk, gain, xp = COURSES[s["c"]]
        if p["energy"] < 10:
            return "нет сил"
        p["energy"] -= 10
        p["hunger"] += 2
        s["n"] += 1
        p["skill"]["int"] += 0.3
        if s["n"] >= sess:
            p["edu"] = max(p["edu"], give)
            p["skill"][sk] += gain
            p["xp"] += xp
            if s["c"] == "lic":
                p["lic"] = True
            p["study"] = None
            return f"закончил: {name}!"
        return f"занятие {s['n']}/{sess}"
    if a == "drop":
        p["study"] = None
        return "бросил учёбу"
    return ""


def act_crime(p, a, arg):
    now = time.time()
    if a == "bail":
        cost = 200 + p["heat"] * 5
        if p["cash"] < cost:
            return f"залог {fmt(cost)}$, не хватает"
        p["cash"] -= cost
        p["jail"] = 0
        return f"вышел под залог ({fmt(cost)}$)"
    if a == "bribe":
        cost = 300 + p["heat"] * 10
        if p["cash"] < cost:
            return f"взятка {fmt(cost)}$, не хватает"
        p["cash"] -= cost
        p["heat"] = max(0, p["heat"] - 30)
        return "договорился, розыск снижен"
    if a == "do":
        name, en, (lo, hi), base, heat, jsec, minsk, inj = CRIMES[arg]
        if p["skill"]["crime"] < minsk:
            return f"нужен навык криминала {minsk}"
        if p["energy"] < en:
            return "нет сил"
        p["energy"] -= en
        car_bonus = 0
        if motor(p) and p["fuel"] >= 2:
            car_bonus = CARS[p["car"]][4] * 1.2
            p["fuel"] -= 2 * CARS[p["car"]][2]
        if p["drunk"] > 40:
            base -= 10
        chance = max(3, min(92, base + p["skill"]["crime"] * 0.4 + p["skill"]["stealth"] * 0.2 - p["heat"] * 0.3 + car_bonus))
        p["heat"] += heat
        if random.uniform(0, 100) < chance:
            x = random.randint(lo, hi)
            p["cash"] += x
            p["earned"] += x
            p["skill"]["crime"] += random.choice([0.5, 1, 1, 2])
            p["skill"]["stealth"] += 0.3
            return f"{name}: прокатило, +{fmt(x)}$ (шанс {int(chance)}%)"
        p["hp"] -= 10
        if inj and random.random() < 0.4:
            catch(p, inj)
        if random.random() < 0.5:
            fine = min(p["cash"], random.randint(50, 250) + int(lo * 0.3))
            p["cash"] -= fine
            return f"{name}: спалили, откупился {fmt(fine)}$"
        p["jail"] = now + jsec
        p["jailed"] += 1
        return f"{name}: взяли, сидишь {jsec // 60} мин"
    return ""


def pay_debts(p, amount):
    paid = 0.0
    for d in sorted(p["debts"], key=lambda x: -x["rate"]):
        if amount <= 0:
            break
        x = min(amount, d["amt"])
        d["amt"] -= x
        amount -= x
        paid += x
        if d["amt"] < 1 and d["kind"] == "bank" and time.time() < d["due"]:
            p["credit"] += 5
    p["debts"] = [d for d in p["debts"] if d["amt"] >= 1]
    return paid


def act_bank(p, a, arg):
    now = time.time()
    if a in ("dep", "wd"):
        src, dst = ("cash", "bank") if a == "dep" else ("bank", "cash")
        amt = p[src] if arg == "all" else min(float(arg), p[src])
        if amt <= 0:
            return "нечего двигать"
        p[src] -= amt
        p[dst] += amt
        return f"{'внёс' if a == 'dep' else 'снял'} {fmt(amt)}$"
    if a == "loan":
        kind, amt = arg.split("_")
        amt = float(amt)
        if kind == "bank":
            limit = p["credit"] * 20
            if debt_total(p, "bank") + amt > limit:
                return f"банк отказал, лимит {fmt(limit)}$ (рейтинг {p['credit']})"
            p["debts"].append(dict(kind="bank", amt=amt, rate=0.02, due=now + 3 * DAY))
        else:
            if debt_total(p, "shark") + amt > 2000:
                return "ростовщик больше не даёт"
            p["debts"].append(dict(kind="shark", amt=amt, rate=0.15, due=now + DAY))
        p["cash"] += amt
        return f"взял {fmt(amt)}$ ({'банк 2%/день' if kind == 'bank' else 'ростовщик 15%/день'})"
    if a == "pay":
        amt = p["cash"] if arg == "all" else min(float(arg), p["cash"])
        if amt <= 0 or not p["debts"]:
            return "платить нечего или нечем"
        paid = pay_debts(p, amt)
        p["cash"] -= paid
        return f"погасил {fmt(paid)}$"
    return ""


def market():
    row = db.execute("SELECT v FROM kv WHERE k='mkt'").fetchone()
    now = time.time()
    m = json.loads(row[0]) if row else {"t": now, "p": {k: v[1] for k, v in STOCKS.items()}}
    for k, v in STOCKS.items():
        m["p"].setdefault(k, v[1])
    steps = int(min((now - m["t"]) / 60, 300))
    if steps > 0 or not row:
        for _ in range(steps):
            for k, (n, base, vol) in STOCKS.items():
                x = m["p"][k] * (1 + random.gauss(0.0003, vol / 3))
                x += (base - x) * 0.002
                m["p"][k] = max(base * 0.2, x)
        m["t"] = now
        db.execute("INSERT OR REPLACE INTO kv(k,v) VALUES('mkt',?)", (json.dumps(m),))
        db.commit()
    return m["p"]


def act_invest(p, a, arg):
    prices = market()
    t, q = arg.split("_")
    if a == "buy":
        price = prices[t]
        qty = int(p["cash"] // price) if q == "all" else int(q)
        if qty <= 0 or qty * price > p["cash"]:
            return "не хватает денег"
        p["cash"] -= qty * price
        p["port"][t] = p["port"].get(t, 0) + qty
        return f"купил {qty} {t} по {price:.2f}$"
    if a == "sell":
        have = p["port"].get(t, 0)
        qty = have if q == "all" else min(int(q), have)
        if qty <= 0:
            return "нечего продавать"
        p["port"][t] = have - qty
        if p["port"][t] <= 0:
            del p["port"][t]
        p["cash"] += qty * prices[t] * 0.995
        return f"продал {qty} {t} по {prices[t]:.2f}$"
    return ""


def biz_net(k, b):
    name, cost, inc, up = BIZ[k]
    lvl = b["lvl"]
    return inc * (1 + 0.6 * (lvl - 1)) - up


def act_biz(p, a, arg):
    now = time.time()
    if a == "buy":
        name, cost, inc, up = BIZ[arg]
        if arg in p["biz"]:
            return "уже есть"
        if p["cash"] < cost:
            return f"нужно {fmt(cost)}$"
        p["cash"] -= cost
        p["biz"][arg] = {"lvl": 1, "last": now}
        return f"купил бизнес: {name}"
    if a == "upg":
        b = p["biz"].get(arg)
        if not b or b["lvl"] >= 5:
            return "нельзя улучшить"
        cost = BIZ[arg][1] * 0.6 * b["lvl"]
        if p["cash"] < cost:
            return f"нужно {fmt(cost)}$"
        p["cash"] -= cost
        b["lvl"] += 1
        return f"улучшил до уровня {b['lvl']}"
    if a == "sell":
        if arg not in p["biz"]:
            return "нет такого"
        p["cash"] += BIZ[arg][1] * 0.6
        del p["biz"][arg]
        return "продал бизнес за 60% цены"
    if a == "collect":
        total = 0.0
        for k, b in p["biz"].items():
            d = min((now - b["last"]) / DAY, 48)
            total += biz_net(k, b) * d
            b["last"] = now
        if not p["biz"]:
            return "у тебя нет бизнеса"
        p["cash"] += total
        return f"собрал прибыль {fmt(total)}$"
    return ""


def act_casino(p, a, arg):
    if a == "lotto":
        if p["inv"].get("good:lotto", 0) <= 0:
            return "нет билетов, купи в «Товарах»"
        p["inv"]["good:lotto"] -= 1
        r = random.random()
        win = 1000 if r < 0.002 else 50 if r < 0.032 else 10 if r < 0.132 else 0
        p["cash"] += win
        return f"лотерея: выигрыш {win}$" if win else "лотерея: пусто"
    kind, bet = arg.split("_")
    bet = p["cash"] if bet == "all" else float(bet)
    if bet <= 0 or p["cash"] < bet:
        return "не хватает денег"
    p["cash"] -= bet
    p["add"]["gam"] = p["add"].get("gam", 0) + 2
    p["lastuse"]["gam"] = time.time()
    r = random.random()
    mult = 0.0
    if a == "slots":
        mult = 10 if r < 0.03 else 4 if r < 0.10 else 2 if r < 0.30 else 0
    elif a == "coin":
        mult = 2 if r < 0.49 else 0
    elif a == "rou":
        n = random.randint(0, 36)
        if kind == "zero":
            mult = 36 if n == 0 else 0
        elif n != 0 and ((n % 2 == 1) == (kind == "red")):
            mult = 2
    elif a == "sport":
        mult = 2.1 if r < 0.45 else 0
    win = bet * mult
    p["cash"] += win
    if win > bet:
        p["mood"] += 6
        return f"выиграл {fmt(win - bet)}$"
    p["mood"] -= 4
    return f"проиграл {fmt(bet)}$"


def act_home(p, a, arg):
    now = time.time()
    pm = cm(p, 1)
    if a == "leave":
        if p["home_own"]:
            return "продай жильё, а не выселяйся"
        p["home"] = "street"
        for g in p["girls"]:
            g.pop("live", None)
        return "ты теперь на улице"
    if a == "rent":
        name, buy, rent, comf, util = HOUSING[arg]
        if arg == "street" or rent <= 0:
            return ""
        rent = max(1, int(rent * pm))
        if p["home_own"]:
            return "сначала продай своё жильё"
        dep = rent * 3
        if p["cash"] < dep:
            return f"залог {fmt(dep)}$ (3 дня аренды)"
        p["cash"] -= dep
        p["home"] = arg
        return f"снял: {name}, залог {fmt(dep)}$"
    if a in ("buy", "mort"):
        name, buy, rent, comf, util = HOUSING[arg]
        buy = int(buy * pm)
        if buy <= 0:
            return "это не продаётся"
        refund = 0
        if p["home_own"]:
            refund = HOUSING[p["home"]][1] * pm * 0.85 - debt_total(p, "mortgage")
        down = buy if a == "buy" else buy * 0.2
        if p["cash"] + refund < down:
            return f"нужно {fmt(down)}$ " + ("(взнос 20%)" if a == "mort" else "")
        if p["home_own"]:
            p["cash"] += refund
            p["debts"] = [d for d in p["debts"] if d["kind"] != "mortgage"]
        p["cash"] -= down
        if a == "mort":
            p["debts"].append(dict(kind="mortgage", amt=buy * 0.8, rate=0.004, due=now + 30 * DAY))
        p["home"], p["home_own"] = arg, True
        return f"купил: {name}" + (" в ипотеку" if a == "mort" else "")
    if a == "sell":
        if not p["home_own"]:
            return "нечего продавать"
        net = HOUSING[p["home"]][1] * pm * 0.85 - debt_total(p, "mortgage")
        p["debts"] = [d for d in p["debts"] if d["kind"] != "mortgage"]
        p["cash"] += max(0, net)
        p["home"], p["home_own"] = "street", False
        for g in p["girls"]:
            g.pop("live", None)
        return f"продал жильё, получил {fmt(max(0, net))}$"
    return ""


def act_car(p, a, arg):
    if a == "buy":
        name, price, fuel, pres, spd, up, lic = CARS[arg]
        if lic and not p["lic"]:
            return "нужны права (раздел «Учёба»)"
        if p["car"]:
            return "сначала продай текущий транспорт"
        if p["cash"] < price:
            return f"нужно {fmt(price)}$"
        p["cash"] -= price
        p["car"], p["fuel"], p["cond"] = arg, 100.0, 100.0
        return f"купил: {name}"
    if not p["car"]:
        return "у тебя нет транспорта"
    if a == "sell":
        val = CARS[p["car"]][1] * 0.7 * (p["cond"] / 100)
        p["cash"] += val
        p["car"] = None
        return f"продал за {fmt(val)}$"
    if a == "fuel":
        cost = (100 - p["fuel"]) * 0.3
        if CARS[p["car"]][2] == 0:
            return "этому транспорту топливо не нужно"
        if p["cash"] < cost:
            return f"заправка стоит {fmt(cost)}$"
        p["cash"] -= cost
        p["fuel"] = 100
        return f"заправился ({fmt(cost)}$)"
    if a == "repair":
        cost = CARS[p["car"]][1] * 0.02 * (100 - p["cond"]) / 10
        if p["cash"] < cost:
            return f"ремонт стоит {fmt(cost)}$"
        p["cash"] -= cost
        p["cond"] = 100
        return f"починил ({fmt(cost)}$)"
    if a == "ride":
        if not motor(p) and p["car"] not in ("bike", "scoot"):
            return ""
        if p["energy"] < 5:
            return "нет сил"
        if CARS[p["car"]][2] > 0 and p["fuel"] < 6:
            return "нет бензина"
        p["energy"] -= 5
        p["fuel"] -= CARS[p["car"]][2] * 3
        p["mood"] += 4 + CARS[p["car"]][3] * 0.5
        return "покатался, настроение выросло" + dui(p)
    return ""


def act_food(p, a, arg):
    name, price, hunger, mood, poison = FOOD[arg]
    if p["cash"] < price:
        return f"нужно {price}$"
    p["cash"] -= price
    p["hunger"] -= hunger
    p["mood"] += mood
    if random.random() < poison:
        catch(p, "foodp")
        return f"съел: {name}... и это была ошибка"
    return f"съел: {name}"


def act_drinks(p, a, arg):
    name, price, en, hp, mood, caf = ENERGY[arg]
    if p["cash"] < price:
        return f"нужно {price}$"
    p["cash"] -= price
    t = tolerance(p, "caf")
    p["energy"] += en * t
    p["mood"] += mood
    p["hp"] -= hp
    if caf:
        p["add"]["caf"] = p["add"].get("caf", 0) + caf
        p["lastuse"]["caf"] = time.time()
    return f"выпил: {name} (+{int(en * t)} энергии)"


def act_alc(p, a, arg):
    if a == "cat":
        p["ui_alc"] = "" if arg == "all" else arg
        return ""
    name, price, drunk, mood, add, hp = ALC[arg]
    if p["cash"] < price:
        return f"нужно {price}$"
    p["cash"] -= price
    p["drunk"] += drunk
    p["mood"] += mood * tolerance(p, "alc")
    p["hp"] -= hp
    p["add"]["alc"] = p["add"].get("alc", 0) + add
    p["lastuse"]["alc"] = time.time()
    p["drank"] += 1
    p["hang"] = time.time() + (p["drunk"] / 60 + 0.5) * DAY
    if p["drunk"] >= 100:
        p["hp"] -= 40
        p["drunk"] = 60
        p["mood"] -= 20
        p["cod"] = "алкогольное отравление"
        return f"выпил: {name}. алкогольное отравление, скорая"
    if p["drunk"] > 80 and random.random() < 0.3:
        loss = p["cash"] * random.uniform(0.05, 0.2)
        p["cash"] -= loss
        return f"выпил: {name}. провал в памяти, пропало {fmt(loss)}$"
    return f"выпил: {name} (опьянение {int(p['drunk'])})"


def act_cigs(p, a, arg):
    if a == "buy":
        name, price, nic, hp = CIGS[arg]
        if p["cash"] < price:
            return f"нужно {price}$"
        p["cash"] -= price
        p["inv"]["cig:" + arg] = p["inv"].get("cig:" + arg, 0) + 20
        return f"купил пачку: {name}"
    if a == "smoke":
        key = "cig:" + arg
        if p["inv"].get(key, 0) <= 0:
            return "пусто"
        name, price, nic, hp = CIGS[arg]
        p["inv"][key] -= 1
        if p["inv"][key] <= 0:
            del p["inv"][key]
        p["add"]["nic"] = p["add"].get("nic", 0) + nic
        p["lastuse"]["nic"] = time.time()
        p["mood"] += 4 * tolerance(p, "nic")
        p["hp"] -= hp
        p["smoked"] += 1
        return f"перекур: {name}"
    if a == "quit":
        if cdleft(p, "quit") > 0:
            return "ты недавно уже бросал"
        p["cd"]["quit"] = time.time() + DAY
        p["add"]["nic"] = max(0, p["add"].get("nic", 0) - 30)
        p["mood"] -= 10
        return "бросаешь курить: ломка, зато тяга падает"
    return ""


def act_goods(p, a, arg):
    name, price = GOODS[arg]
    if p["cash"] < price:
        return f"нужно {fmt(price)}$"
    p["cash"] -= price
    n = {"protect": 3, "syr": 5, "pill": 5}.get(arg, 1)
    p["inv"]["good:" + arg] = p["inv"].get("good:" + arg, 0) + n
    return f"купил: {name}"


def act_pharm(p, a, arg):
    name, price, rx, cures, manage, hp = MEDS[arg]
    if a == "buy":
        mult = 1
        if rx and p["rx"] < time.time():
            mult = 3
        cost = price * mult
        if p["cash"] < cost:
            return f"нужно {fmt(cost)}$"
        p["cash"] -= cost
        p["inv"]["med:" + arg] = p["inv"].get("med:" + arg, 0) + 1
        return f"купил: {name}" + (" (без рецепта втридорога)" if mult > 1 else "")
    if a == "take":
        key = "med:" + arg
        if p["inv"].get(key, 0) <= 0:
            return "нет такого лекарства"
        p["inv"][key] -= 1
        if p["inv"][key] <= 0:
            del p["inv"][key]
        out = []
        for dk, pr in cures.items():
            if dk in p["dis"] and random.random() < pr:
                del p["dis"][dk]
                out.append(DIS[dk][0] if DIS[dk][7] == 0 else "что-то скрытое")
        for dk, d in manage.items():
            if dk in p["dis"]:
                p["dis"][dk]["managed"] = time.time() + d * DAY
                out.append(f"симптомы под контролем: {DIS[dk][0]}" if p["dis"][dk]["dx"] else "симптомы под контролем")
        p["hp"] += hp
        return f"принял: {name}. " + ("помогло: " + ", ".join(out) if out else "эффекта не заметил")
    return ""


def act_health(p, a, arg):
    now = time.time()
    if a == "check":
        if p["cash"] < 60:
            return "осмотр стоит 60$"
        p["cash"] -= 60
        p["rx"] = now + DAY / 2
        found = []
        for k, d in p["dis"].items():
            d["dx"] = True
            found.append(DIS[k][0])
        return "диагноз: " + (", ".join(found) if found else "здоров") + ". выписал рецепты на 30 минут"
    if a == "stitest":
        if p["cash"] < 40:
            return "тест на ЗППП стоит 40$"
        p["cash"] -= 40
        found = []
        for k, d in p["dis"].items():
            if k in STI_IDS:
                d["dx"] = True
                found.append(DIS[k][0])
        return "тест на ЗППП: " + (", ".join(found) if found else "чисто")
    if a == "stay":
        if p["cash"] < 300:
            return "стационар 300$"
        p["cash"] -= 300
        p["hp"] += 50
        p["energy"] = 100
        p["hunger"] = max(0, p["hunger"] - 30)
        for k in list(p["dis"]):
            if DIS[k][5] > 0 and random.random() < 0.5:
                del p["dis"][k]
        return "полежал в стационаре: лучше"
    if a == "therapy":
        if p["cash"] < 80:
            return "сеанс 80$"
        p["cash"] -= 80
        p["mood"] += 20
        for k in ("depr", "anx", "insom"):
            if k in p["dis"] and random.random() < 0.12:
                del p["dis"][k]
        return "сеанс у психолога: легче"
    if a == "surg":
        name, cost, ok = SURG[arg]
        if arg not in p["dis"]:
            return "эта болезнь у тебя не найдена"
        if p["cash"] < cost:
            return f"{name}: {fmt(cost)}$"
        p["cash"] -= cost
        if random.random() < ok:
            if arg == "hiv":
                p["dis"][arg]["managed"] = now + 3 * DAY
                return f"{name}: подобрали терапию, симптомы утихли"
            del p["dis"][arg]
            return f"{name}: успешно"
        p["hp"] -= 15
        return f"{name}: не помогло, потерял здоровье"
    if a == "rehab":
        if p["cash"] < 800:
            return "клиника зависимостей 800$"
        p["cash"] -= 800
        for k in list(p["add"]):
            if k != "gam":
                p["add"][k] = 0
        p["energy"] = min(p["energy"], 20)
        p["mood"] -= 10
        return "лечение зависимостей пройдено"
    if a == "gamrehab":
        if p["cash"] < 300:
            return "группа поддержки 300$"
        p["cash"] -= 300
        p["add"]["gam"] = 0
        return "азарт отпустило"
    return ""


def act_subs(p, a, arg):
    now = time.time()
    if a == "buy":
        name, price, *_ = DRUGS[arg]
        if p["cash"] < price:
            return "нет денег"
        p["cash"] -= price
        if random.random() < 0.06:
            fine = min(p["cash"], 150)
            p["cash"] -= fine
            p["heat"] += 20
            p["jail"] = now + 300
            p["jailed"] += 1
            return f"засада на точке: штраф {fmt(fine)}$ и 5 мин в обезьяннике"
        p["inv"]["drug:" + arg] = p["inv"].get("drug:" + arg, 0) + 1
        return f"купил: {name}"
    if a == "use":
        key = "drug:" + arg
        if p["inv"].get(key, 0) <= 0:
            return "нечего употреблять"
        name, price, mood, en, hp, addg, od = DRUGS[arg]
        p["inv"][key] -= 1
        if p["inv"][key] <= 0:
            del p["inv"][key]
        tol = tolerance(p, arg)
        p["mood"] += mood * tol
        p["energy"] += en * tol if en > 0 else en
        p["hp"] += hp
        p["add"][arg] = p["add"].get(arg, 0) + addg
        p["lastuse"][arg] = now
        extra = ""
        if arg in INJECT:
            if p["inv"].get("good:syr", 0) > 0:
                p["inv"]["good:syr"] -= 1
            else:
                if random.random() < 0.10:
                    catch(p, "hepc")
                if random.random() < 0.03:
                    catch(p, "hiv")
                extra = " (шприц общий, это риск)"
        for dz, ch in DRUG_SIDE.get(arg, ()):
            if random.random() < ch * (1 + p["add"][arg] / 50):
                catch(p, dz)
        if arg in ("coc", "met", "mef", "amph") and p["add"][arg] > 50 and random.random() < 0.02:
            catch(p, "heart")
        if random.random() < od * (1 + p["add"][arg] / 40):
            fee = min(p["cash"], 400)
            p["cash"] -= fee
            p["hp"] -= 50
            p["mood"] -= 20
            p["cod"] = f"передозировка ({name})"
            return f"{name}: передоз. скорая, -{fmt(fee)}$ и половина здоровья"
        return f"{name}: накрыло (зависимость {int(p['add'][arg])}%)" + extra
    return ""


def act_self(p, a, arg):
    now = time.time()
    if a == "sleep":
        if cdleft(p, "sleep") > 0:
            return f"не хочется спать, подожди {int(cdleft(p, 'sleep') // 60) + 1} мин"
        p["cd"]["sleep"] = now + 600
        p["energy"] += 45 * comfort(p)
        p["hp"] += 5 * comfort(p)
        p["hunger"] += 8
        p["mood"] += 3
        return "поспал"
    if a == "gym":
        cost = 0 if "gym" in p["biz"] else 15
        if p["cash"] < cost or p["energy"] < 12:
            return "нужно 15$ и 12 энергии"
        p["cash"] -= cost
        p["energy"] -= 12
        p["skill"]["str"] += 1
        p["hp"] += 1
        p["mood"] += 2
        p["hunger"] += 4
        return "потренировался: сила +1"
    if a == "read":
        if p["energy"] < 8:
            return "нет сил"
        p["energy"] -= 8
        p["skill"]["int"] += 0.5
        p["mood"] -= 1
        return "почитал: интеллект растёт"
    if a == "cook":
        if p["energy"] < 8 or p["cash"] < 5:
            return "нужно 8 энергии и 5$"
        p["energy"] -= 8
        p["cash"] -= 5
        p["skill"]["cook"] += 1
        p["hunger"] -= 30 + p["skill"]["cook"] * 0.3
        p["mood"] += 2
        return "приготовил ужин: навык готовки растёт"
    if a == "meditate":
        if p["energy"] < 3:
            return "нет сил"
        p["energy"] -= 3
        p["mood"] += 8
        for k in ("anx", "insom"):
            if k in p["dis"] and random.random() < 0.05:
                del p["dis"][k]
        return "помедитировал, голова чище"
    if a == "party":
        if p["cash"] < 60 or p["energy"] < 10:
            return "нужно 60$ и 10 энергии"
        p["cash"] -= 60
        p["energy"] -= 10
        p["mood"] += 15
        p["skill"]["cha"] += 0.5
        return "потусил на вечеринке"
    if a == "daily":
        if now - p["lastdaily"] < 20 * DAY:
            return f"бонус будет через {int((20 * DAY - (now - p['lastdaily'])) // DAY) + 1} ч"
        p["streak"] = p["streak"] + 1 if now - p["lastdaily"] < 44 * DAY else 1
        x = 100 + 20 * min(p["streak"], 10)
        p["lastdaily"] = now
        p["cash"] += x
        return f"ежедневный бонус {x}$ (серия {p['streak']})"
    if a == "pref":
        p["pref"] = {"f": "m", "m": "any", "any": "f"}[p["pref"]]
        return "предпочтения знакомств: " + {"f": "девушки", "m": "парни", "any": "все"}[p["pref"]]
    return ""


def stage(p, g):
    if p["spouse"] == g["name"]:
        return "супруг(а)"
    r = g["rel"]
    return "знакомые" if r < 30 else "встречаетесь" if r < 60 else "пара" if r < 85 else "любовь"


def gen_person(p):
    g = random.choice(["f"] if p["pref"] == "f" else ["m"] if p["pref"] == "m" else ["f", "m"])
    taken = {x["name"] for x in p["girls"]}
    first = NAMES_F if g == "f" else NAMES_M
    nm = "Незнакомец"
    for _ in range(40):
        cand = random.choice(first) + " " + surname(g, random.choice(SURNAMES))
        if cand not in taken:
            nm = cand
            break
    return {"name": nm, "age": random.randint(18, 55), "trait": random.choice(TRAITS), "rel": 15.0, "g": g}


def act_love(p, a, arg):
    if a == "pref":
        return act_self(p, "pref", "")
    if a == "meet":
        name, cost, en, succ = MEET[arg]
        if len(p["girls"]) >= 6:
            return "контактов и так много, кого-то придётся отпустить"
        if p["cash"] < cost or p["energy"] < en:
            return f"нужно {cost}$ и {en} энергии"
        p["cash"] -= cost
        p["energy"] -= en
        succ += p["skill"]["cha"] * 0.004 + (CARS[p["car"]][3] * 0.01 if p["car"] else 0) + (0.05 if 20 < p["mood"] else -0.1)
        if p["drunk"] > 50:
            succ -= 0.15
        if random.random() < succ:
            g = gen_person(p)
            p["girls"].append(g)
            p["mood"] += 8
            p["skill"]["cha"] += 0.3
            return f"познакомился: {g['name']}, {g['age']}, {g['trait']}"
        p["mood"] -= 2
        return f"{name}: никого интересного"
    return ""


def act_girl(p, a, arg):
    now = time.time()
    parts = arg.split("_")
    i = int(parts[0])
    if i >= len(p["girls"]):
        return "такого контакта нет"
    g = p["girls"][i]
    sub = parts[1] if len(parts) > 1 else ""
    cheat = ""
    exclusive = [x for x in p["girls"] if x is not g and x["rel"] >= 60]
    if a in ("date", "night", "intim") and exclusive and random.random() < 0.25:
        x = random.choice(exclusive)
        x["rel"] -= 35
        cheat = f" ⚠ {x['name']} узнала(ал) про измену (-35)"
    if a == "talk":
        if p["energy"] < 3:
            return "нет сил"
        p["energy"] -= 3
        g["rel"] += random.randint(1, 3)
        return f"поболтали с {g['name']}"
    if a == "date":
        name, cost, en, lo, hi = DATES[sub]
        if p["cash"] < cost or p["energy"] < en:
            return f"нужно {cost}$ и {en} энергии"
        p["cash"] -= cost
        p["energy"] -= en
        gain = random.randint(lo, hi) * (1.2 if g["trait"].startswith("амбиц") and cost >= 100 else 1)
        if p["drunk"] > 50:
            gain *= 0.4
        g["rel"] += gain
        p["mood"] += 8
        p["skill"]["cha"] += 0.2
        return f"{name} с {g['name']}: +{int(gain)} к отношениям" + cheat
    if a == "gift":
        for item, bonus in (("good:gift", 20), ("good:flowers", 10)):
            if p["inv"].get(item, 0) > 0:
                p["inv"][item] -= 1
                g["rel"] += bonus
                p["mood"] += 3
                return f"{g['name']} в восторге (+{bonus})"
        return "нет цветов или подарка, купи в «Товарах»"
    if a == "night":
        return intimacy(p, g, "romantic", now) + cheat
    if a == "intim":
        return intimacy(p, g, sub, now) + cheat
    if a == "touch":
        return touch(p, g, sub) if sub in TOUCH else ""
    if a == "movein":
        if g.get("live"):
            g["live"] = False
            return f"{g['name']} съехала(ал)"
        if g["rel"] < 70:
            return "рано, отношения < 70"
        if p["home"] == "street":
            return "сначала нужно жильё"
        if any(x.get("live") for x in p["girls"]):
            return "ты уже живёшь с кем-то"
        g["live"] = True
        return f"{g['name']} переехала(ал) к тебе: аренда дешевле"
    if a == "propose":
        if p["spouse"]:
            return "ты уже в браке"
        if g["rel"] < 85:
            return "рано, отношения < 85"
        if p["inv"].get("good:ring", 0) <= 0:
            return "нужно кольцо (товары)"
        if p["cash"] < 3000:
            return "свадьба стоит 3000$"
        p["cash"] -= 3000
        p["inv"]["good:ring"] -= 1
        p["spouse"] = g["name"]
        p["mood"] += 30
        return f"свадьба с {g['name']}!"
    if a == "divorce":
        if p["spouse"] != g["name"]:
            return "вы не в браке"
        fee = (p["cash"] + p["bank"]) * 0.2
        p["cash"] = max(0, p["cash"] - fee)
        p["spouse"] = None
        p["girls"].remove(g)
        p["mood"] -= 20
        return f"развод. раздел имущества: -{fmt(fee)}$"
    if a == "break":
        if p["spouse"] == g["name"]:
            return "сначала развод"
        p["girls"].remove(g)
        p["mood"] -= 12
        return f"расстался с {g['name']}"
    return ""


def act_family(p, a, arg):
    i = int(arg) if arg else 0
    if a == "heal_all":
        sick = [k for k in p["kids"] if k.get("sick")]
        cost = 80 * len(sick)
        if not sick:
            return "дети здоровы"
        if p["cash"] < cost:
            return f"лечение стоит {cost}$"
        p["cash"] -= cost
        for k in sick:
            k["sick"] = False
        return "детей вылечили"
    if i >= len(p["kids"]):
        return "нет такого ребёнка"
    k = p["kids"][i]
    if a == "play":
        if p["energy"] < 8:
            return "нет сил"
        p["energy"] -= 8
        k["bond"] = min(100, k["bond"] + 8)
        p["mood"] += 8
        return f"поиграл с {k['name']}"
    if a == "toy":
        if p["inv"].get("good:toy", 0) <= 0:
            return "нет игрушки, купи в «Товарах»"
        p["inv"]["good:toy"] -= 1
        k["bond"] = min(100, k["bond"] + 12)
        return f"подарил игрушку: {k['name']} счастлив(а)"
    return ""


def act_pets(p, a, arg):
    if a == "buy":
        name, price, up, mood = PETS[arg]
        if len(p["pets"]) >= 3:
            return "дома и так зоопарк (макс 3)"
        if p["home"] == "street":
            return "питомцу нужен дом"
        if p["cash"] < price:
            return f"нужно {price}$"
        p["cash"] -= price
        p["pets"].append(arg)
        return f"завёл: {name}"
    if a == "free":
        i = int(arg)
        if i < len(p["pets"]):
            p["pets"].pop(i)
            return "отдал в добрые руки"
    return ""


def act_social(p, a, arg):
    if a == "rob":
        uid, = [int(arg)]
        v = load_raw(uid)
        if not v or uid == p["uid"]:
            return "цель не найдена"
        if p["energy"] < 15:
            return "нужно 15 энергии"
        p["energy"] -= 15
        chance = max(10, min(80, 40 + p["skill"]["stealth"] * 0.4 + p["skill"]["crime"] * 0.2 - v["skill"].get("str", 0) * 0.3 - p["heat"] * 0.2))
        p["heat"] += 25
        if random.random() * 100 < chance and v["cash"] > 20:
            x = min(v["cash"], v["cash"] * random.uniform(0.05, 0.12))
            v["cash"] -= x
            p["cash"] += x
            v["log"] = (v.get("log", []) + [f"тебя ограбил {p['name']}: -{fmt(x)}$"])[-5:]
            save(v)
            p["skill"]["crime"] += 1
            return f"обчистил {v['name']} на {fmt(x)}$"
        p["hp"] -= 10
        p["jail"] = time.time() + 600
        p["jailed"] += 1
        return f"{v['name']} дал отпор, ты в обезьяннике на 10 мин"
    if a == "send":
        uid, amt = arg.split("_")
        uid, amt = int(uid), float(amt)
        v = load_raw(int(uid))
        if not v or uid == p["uid"]:
            return "получатель не найден"
        if p["cash"] < amt:
            return "не хватает денег"
        p["cash"] -= amt
        v["cash"] += amt
        v["log"] = (v.get("log", []) + [f"{p['name']} перевёл тебе {fmt(amt)}$"])[-5:]
        save(v)
        return f"перевёл {fmt(amt)}$ игроку {v['name']}"
    return ""


# ───────────────────────── extended actions ─────────────────────────
def surname(g, s):
    if g == "f":
        for a, b in SURN_END:
            if s.endswith(a):
                return s[:-len(a)] + b
        if s.endswith(("ов", "ев", "ин", "ын")):
            return s + "а"
    return s


def touch(p, g, key):
    name, min_rel, en, cost, lo, hi, mood, needs_home = TOUCH[key]
    if g["rel"] < min_rel:
        return f"рано, отношения < {min_rel}"
    if needs_home and p["home"] == "street":
        return "для этого нужен дом"
    if p["energy"] < en or p["cash"] < cost:
        return f"нужно {cost}$ и {en} энергии"
    p["energy"] -= en
    p["cash"] -= cost
    gain = random.randint(lo, hi)
    if p["drunk"] > 50:
        gain *= 0.5
    g["rel"] += gain
    p["mood"] += mood
    if key == "dinner":
        p["hunger"] = max(0, p["hunger"] - 20)
        p["skill"]["cook"] += 0.3
    if key == "friends" and random.random() < 0.2:
        g["rel"] -= 6
        return f"{name.split(' ', 1)[1]}: друзья {g['name']} тебя не оценили (-6)"
    return f"{name.split(' ', 1)[1]} с {g['name']}: +{int(gain)} к отношениям"


def intimacy(p, g, key, now):
    if key not in INTIM:
        return ""
    name, min_rel, en, mood, risk, gain, cost = INTIM[key]
    if g["rel"] < min_rel:
        return f"рано, отношения < {min_rel}"
    if p["energy"] < en:
        return "нет сил"
    if p["cash"] < cost:
        return f"нужно {cost}$"
    p["cash"] -= cost
    p["energy"] -= en
    p["mood"] += mood
    p["hp"] += 5
    g["rel"] += gain
    txt = f"{name} с {g['name']}. утром всё хорошо."
    condom = p["inv"].get("good:protect", 0) > 0
    if condom:
        p["inv"]["good:protect"] -= 1
    else:
        for k, pr in STI_RISK:
            if random.random() < pr * risk:
                catch(p, k)
    pill = (not condom) and p["inv"].get("good:pill", 0) > 0
    if pill:
        p["inv"]["good:pill"] -= 1
    conceive = min(0.5, (0.03 if condom else 0.04 if pill else 0.12) * risk)
    if g["g"] == "f" and p["pref"] != "m" and random.random() < conceive and not any(b.get("m") == g["name"] for b in p["pending"]):
        p["pending"].append({"t": now + 3 * DAY, "m": g["name"]})
        txt += f" {g['name']} ждёт ребёнка."
    return txt


def act_snus(p, a, arg):
    if a == "buy":
        name, price, nic, hp, taste = SNUS[arg]
        if p["cash"] < price:
            return f"нужно {price}$"
        p["cash"] -= price
        p["inv"]["snus:" + arg] = p["inv"].get("snus:" + arg, 0) + SNUS_TIN
        return f"купил банку: {name} ({SNUS_TIN} порций)"
    if a == "use":
        key = "snus:" + arg
        if p["inv"].get(key, 0) <= 0:
            return "пусто"
        name, price, nic, hp, taste = SNUS[arg]
        p["inv"][key] -= 1
        if p["inv"][key] <= 0:
            del p["inv"][key]
        p["add"]["nic"] = p["add"].get("nic", 0) + nic
        p["lastuse"]["nic"] = time.time()
        p["mood"] += 4 * tolerance(p, "nic")
        p["hp"] -= hp
        p["snused"] = p.get("snused", 0) + 1
        return f"порция: {name} ({taste})"
    return ""


def act_vape(p, a, arg):
    if a == "buy":
        name, price, nic, hp, taste, kind = VAPE[arg]
        if p["cash"] < price:
            return f"нужно {price}$"
        p["cash"] -= price
        p["inv"]["vape:" + arg] = p["inv"].get("vape:" + arg, 0) + VAPE_UNITS[kind]
        return f"купил: {name} ({VAPE_UNITS[kind]} затяжек)"
    if a == "puff":
        key = "vape:" + arg
        if p["inv"].get(key, 0) <= 0:
            return "пусто"
        name, price, nic, hp, taste, kind = VAPE[arg]
        if kind == "liq" and p["inv"].get("good:pod", 0) <= 0 and p["inv"].get("good:vmod", 0) <= 0:
            return "для жидкости нужна pod-система или мод (Магазины → Товары)"
        p["inv"][key] -= 1
        if p["inv"][key] <= 0:
            del p["inv"][key]
        p["add"]["nic"] = p["add"].get("nic", 0) + nic
        p["lastuse"]["nic"] = time.time()
        p["mood"] += 3 * tolerance(p, "nic")
        p["hp"] -= hp
        p["vaped"] = p.get("vaped", 0) + 1
        return f"затяжка: {name} ({taste})"
    return ""


def act_hookah(p, a, arg):
    if a == "bt":
        name, price, st, taste = HTOB[arg]
        if p["cash"] < price:
            return f"нужно {price}$"
        p["cash"] -= price
        p["inv"]["ht:" + arg] = p["inv"].get("ht:" + arg, 0) + HTOB_JAR
        return f"купил табак: {name} ({HTOB_JAR} кальянов)"
    if a == "bc":
        name, price, co = COALS[arg]
        if p["cash"] < price:
            return f"нужно {price}$"
        p["cash"] -= price
        p["inv"]["coal:" + arg] = p["inv"].get("coal:" + arg, 0) + COAL_BOX
        return f"купил угли: {name} ({COAL_BOX} кальяна)"
    if a == "go":
        if p["inv"].get("good:hookah", 0) <= 0:
            return "нужен кальян (Магазины → Товары)"
        key = "ht:" + arg
        if p["inv"].get(key, 0) <= 0:
            return "нет табака"
        ck = next((k for k, v in p["inv"].items() if k.startswith("coal:") and v > 0), None)
        if ck is None:
            return "нужны угли"
        name, price, st, taste = HTOB[arg]
        co = COALS[ck[5:]][2]
        for k in (key, ck):
            p["inv"][k] -= 1
            if p["inv"][k] <= 0:
                del p["inv"][k]
        p["add"]["nic"] = p["add"].get("nic", 0) + 2 + 0.8 * st
        p["lastuse"]["nic"] = time.time()
        p["mood"] += 8 * tolerance(p, "nic")
        p["hp"] -= 1.0
        p["energy"] -= 4
        p["hooked"] = p.get("hooked", 0) + 1
        if random.random() < 0.02 * co:
            catch(p, "copois")
            return f"кальян: {name}. голова кружится, это угарный газ"
        return f"кальян: {name} ({taste})"
    return ""


def act_city(p, a, arg):
    if a != "go" or arg not in CITIES:
        return ""
    if arg == p.get("city"):
        return "ты уже здесь"
    if p["home_own"]:
        return "сначала продай жильё (Жильё → Продать)"
    cost = 300 + int(300 * CITIES[arg][3])
    if p["cash"] < cost:
        return f"переезд стоит {cost}$"
    p["cash"] -= cost
    p["city"] = arg
    p["home"] = "street"
    for g in p["girls"]:
        g.pop("live", None)
    p["mood"] -= 5
    return f"переехал: {CITIES[arg][0]}. жильё нужно искать заново (-{cost}$)"


def cm(p, i):
    """city multiplier: 1 price, 2 wage, 3 cost of living, 4 cold"""
    return CITIES.get(p.get("city"), CITIES["samara"])[i]


