def r_car(p, page=0):
    if p["car"]:
        n, price, fuel, pres, spd, up, lic = CARS[p["car"]]
        txt = f"Транспорт: {n}. Топливо {int(p['fuel'])}%, состояние {int(p['cond'])}%. Престиж {pres}, скорость {spd}. Содержание {up}/день."
        rows = [[B("⛽ Заправить", "car:fuel"), B("🔧 Починить", "car:repair")], [B("🏁 Покататься", "car:ride"), B("💸 Продать", "car:sell")], back("car")]
        return txt, rows

    def mk(k):
        n, price, fuel, pres, spd, up, lic = CARS[k]
        return [B(f"{'🏍' if k == 'moto' else '🚲' if k in ('bike', 'scoot') else '🚗'} {n} · {fmt(price)}$", f"car:buy:{k}")]
    rows = paged("car", list(CARS), page, 8, mk)
    rows.append(back("car"))
    return "Транспорт. Для машин и мотоциклов нужны права. Своя тачка: больше шансов в криминале, доступ к работам с авто, престиж на свиданиях.", rows


