def r_health(p, page=0):
    L = [f"Здоровье. ❤ {int(p['hp'])}"]
    rows = [
        [B("🩺 Осмотр 60$", "health:check"), B("🛏 Стационар 300$", "health:stay")],
        [B("🧠 Психолог 80$", "health:therapy"), B("🏥 Лечение зависимостей 800$", "health:rehab")],
    ]
    rows.append([B("🧪 Тест на ЗППП 40$", "health:stitest")])
    if p["add"].get("gam", 0) > 0:
        rows.append([B("🎲 Группа по азарту 300$", "health:gamrehab")])
    for k, d in p["dis"].items():
        shown = DIS[k][0] if d.get("dx") else "неясные симптомы"
        L.append(f"· {shown}" + (" (под контролем)" if d.get("managed", 0) > time.time() else ""))
        if d.get("dx") and k in SURG:
            rows.append([B(f"{SURG[k][0]} · {fmt(SURG[k][1])}$", f"health:surg:{k}")])
    if not p["dis"]:
        L.append("болезней не замечено")
    rows.append([B("💊 В аптеку", "pharm")])
    rows.append(back("health"))
    return "\n".join(L), rows


