def r_family(p, page=0):
    now = time.time()
    rows = []
    L = ["Семья."]
    if p["spouse"]:
        L.append(f"Супруг(а): {p['spouse']}")
    if not p["kids"]:
        L.append("Детей нет.")
    for i, k in enumerate(p["kids"]):
        a = int((now - k["born"]) / YEAR)
        L.append(f"· {k['name']}, {a} лет, связь {int(k['bond'])}" + (", болеет 🤒" if k.get("sick") else ""))
        rows.append([B(f"Играть: {k['name']}", f"family:play:{i}"), B("🧸 Игрушка", f"family:toy:{i}")])
    if any(k.get("sick") for k in p["kids"]):
        rows.append([B("💊 Вылечить больных (80$ каждому)", "family:heal_all")])
    for b in p["pending"]:
        L.append(f"🤰 {b['m']} родит через ~{max(1, int((b['t'] - now) // 60))} мин")
    L.append(f"Расходы на детей: {20} в день каждый (×3 если больны).")
    rows.append(back("family"))
    return "\n".join(L), rows


