def r_hookah(p, page=0):
    own_t = [(k[3:], v) for k, v in p["inv"].items() if k.startswith("ht:") and v > 0]
    coal = sum(v for k, v in p["inv"].items() if k.startswith("coal:") and v > 0)
    rows = [[B(f"🫖 Кальян: {HTOB[k][0]} ×{v}", f"hookah:go:{k}")] for k, v in own_t[:4]]
    items = [("bt", k) for k in HTOB] + [("bc", k) for k in COALS]

    def mk(it):
        kind, k = it
        if kind == "bt":
            return [B(f"🍃 {HTOB[k][0]} · {HTOB[k][1]}$", f"hookah:bt:{k}")]
        return [B(f"🪨 {COALS[k][0]} · {COALS[k][1]}$", f"hookah:bc:{k}")]
    rows += paged("hookah", items, page, 8, mk)
    rows.append(back("hookah"))
    lines = []
    for kind, k in slice_page(items, page, 8):
        if kind == "bt":
            lines.append(f"· {HTOB[k][0]}: {HTOB[k][3]}, крепость {HTOB[k][2]}/10")
        else:
            lines.append(f"· {COALS[k][0]}: угли, риск CO ×{COALS[k][2]}")
    hk = "кальян есть ✅" if p["inv"].get("good:hookah", 0) > 0 else "кальяна нет (Магазины → Товары)"
    head = (f"Кальян. {hk}. Углей хватит на {coal} сессий. Банка табака = {HTOB_JAR} кальянов, коробка углей = {COAL_BOX}. "
            "Побочки: угарный газ, бронхит, никотин.")
    return head + "\n\n" + "\n".join(lines), rows


