def r_home(p, page=0):
    keys = [k for k in HOUSING if k != "street"]
    pm = cm(p, 1)

    def mk(k):
        n, buy, rent, comf, util = HOUSING[k]
        rent, buy = (max(1, int(rent * pm)) if rent else 0), int(buy * pm)
        row = [B(f"🏠 {n} · аренда {rent}/д", f"home:rent:{k}")] if rent else []
        if buy:
            row.append(B(f"💰 {fmt(buy)}$", f"home:buy:{k}"))
        if buy >= 30000:
            row.append(B("🏦 ипотека", f"home:mort:{k}"))
        return row
    rows = paged("home", keys, page, 4, mk)
    rows.append([B("📦 Продать жильё", "home:sell"), B("🚪 Съехать на улицу", "home:leave")])
    rows.append([B("🌆 Сменить город", "city")])
    rows.append(back("home"))
    h = HOUSING[p["home"]]
    c = CITIES.get(p.get("city"), CITIES["samara"])
    return (f"Город: {c[0]} (цены ×{c[1]:g}, зарплаты ×{c[2]:g}, жизнь ×{c[3]:g}).\n"
            f"Жильё: {h[0]} (комфорт ×{h[3]}). Комфорт ускоряет сон и восстановление энергии. Коммуналка: {int(h[4] * c[3])}/день. "
            "Залог аренды = 3 дня, ипотека = взнос 20%."), rows


