# [2b] REAL LIFE PACK
#   ₽ вместо $, регистрация (город/имя, старт с 14), ДР раз в час, 18+ товары (купить / попросить взрослого / своровать),
#   вейпы (затяжки, зарядка, одноразки не заправляются), телефоны + SIM, браузер, улица (граффити → сайт → клад),
#   закладчик, интим-магазин (строго 18+)
# ══════════════════════════════════════════════════════════════════════
import copy
import re

FX = 90.0   # 1 внутренняя единица = 90 ₽. Логика считает по-старому, build() переводит каждое «N$» в ₽


def R(rub):
    return rub / FX


def fmt(n):
    if abs(n) < 1000 and n != int(n):
        return f"{n:.2f}".rstrip("0").rstrip(".")
    return f"{int(n):,}".replace(",", " ")


_RNG = re.compile(r"(\d[\d ]*(?:\.\d+)?)-(\d[\d ]*(?:\.\d+)?)\$")
_ONE = re.compile(r"(\d[\d ]*(?:\.\d+)?)\$")


def _rub1(v):
    return f"{int(round(float(v.replace(' ', '')) * FX)):,}".replace(",", " ")


def rub(s):
    s = _RNG.sub(lambda m: f"{_rub1(m.group(1))}-{_rub1(m.group(2))} ₽", s)
    return _ONE.sub(lambda m: f"{_rub1(m.group(1))} ₽", s)


def _scale(tbl, k):
    for key, v in list(tbl.items()):
        tbl[key] = (v[0], round(v[1] * k, 4)) + tuple(v[2:])


