# ───────── возраст / регистрация / новая жизнь ─────────
def age(p):
    if "age_n" in p:
        return p["age_n"]
    return p.get("age0", 18) + int((time.time() - p["born"]) / YEAR)


def yrs(a):
    return "год" if a % 10 == 1 and a % 100 != 11 else "года" if a % 10 in (2, 3, 4) and a % 100 not in (12, 13, 14) else "лет"


_new_player0 = new_player


def new_player(uid, name):
    d = _new_player0(uid, name)
    d.update(age_n=14, home="family", home_own=False, cash=R(2500), reg="done", named=True, vpd=[], sims=[], ph=None, sites=[],
             orders=[], batch=None, dealer=0, bm="buy", vtab="d", ptab="1", vsel="", ws="", log=["новая жизнь началась. тебе 14"])
    return d


def get_player(user):
    name = user.first_name or "Аноним"
    p = load_raw(user.id)
    base = new_player(user.id, name)
    if p:
        p.setdefault("reg", "done")
        p.setdefault("age0", 18)
        p.setdefault("city", "samara")
        for k, v in base.items():
            if k not in ("age_n", "named", "reg"):
                p.setdefault(k, v)
        for k, v in base["skill"].items():
            p["skill"].setdefault(k, v)
        if not p.get("named"):
            p["name"] = name
    else:
        p = base
        p["reg"] = "city"
        p["named"] = False
    tick(p)
    return p


def r_reg(p, page=0):
    if p.get("reg") == "name":
        return (f"📍 {CITIES[p['city']][0]}. Тебе 14.\nШаг 2/2 — напиши имя одним сообщением (до 20 символов) или жми кнопку.",
                [[B("🎲 Случайное имя", "reg:rnd")], [B("🔙 Другой город", "reg:back")]])
    keys = sorted(CITIES, key=lambda k: CITIES[k][0])
    per = 12
    pages = (len(keys) + per - 1) // per
    page = max(0, min(page, pages - 1))
    chunk = keys[page * per:(page + 1) * per]
    rows = [[B(f"📍 {CITIES[k][0]}", f"reg:city:{k}") for k in chunk[i:i + 2]] for i in range(0, len(chunk), 2)]
    nav = []
    if page > 0:
        nav.append(B("⬅️", f"reg:pg:{page - 1}"))
    nav.append(B(f"📄 {page + 1}/{pages}", f"reg:pg:{page}"))
    if page < pages - 1:
        nav.append(B("➡️", f"reg:pg:{page + 1}"))
    rows.append(nav)
    return (f"🆕 Новая жизнь. Тебе 14.\nШаг 1/2 — выбери город из {len(CITIES)}. От него зависят цены, зарплаты и климат.", rows)


def act_reg(p, a, arg):
    if a == "city" and arg in CITIES:
        p["city"] = arg
        p["reg"] = "name"
    elif a == "back":
        p["reg"] = "city"
    elif a == "rnd" and p.get("reg") == "name":
        p["name"] = random.choice(NAMES_M + NAMES_F)
        p["named"] = True
        p["reg"] = "done"
        return f"тебя зовут {p['name']}. поехали"
    return ""


def act_main(p, a, arg):
    if a != "bday":
        return ""
    left = cdleft(p, "bday")
    if left > 0:
        return f"день рождения только через {int(left // 60) + 1} мин"
    p["cd"]["bday"] = time.time() + 3600
    n = age(p) + 1
    p["age_n"] = n
    p["mood"] += 8
    gift = R(random.randint(500, 3000)) if n < 18 else R(random.randint(0, 2000))
    p["cash"] += gift
    msg = f"🎂 тебе {n}. подарили {fmt(gift)}$"
    if n == 18:
        msg += ". теперь 18: сигареты и алкоголь продадут без вопросов, открылись любовь, казино и интим-магазин"
        if p["home"] == "family":
            p["home"] = "hostel"
            msg += ". родители намекнули про своё жильё: ты в общаге"
    return msg


def _adult_only(fn):
    def w(p, a, arg):
        if age(p) < 18:
            return "до 18 нельзя"
        return fn(p, a, arg)
    return w


def _adult_screen(fn, sec):
    def r(p, page=0):
        if age(p) < 18:
            return "🔒 Откроется с 18 лет.", [back(sec)]
        return fn(p, page)
    return r


