# ───────── покупка: купить / попросить взрослого / своровать ─────────
def _sell_chance(p):
    return max(0.05, min(0.7, 0.10 + (age(p) - 14) * 0.12 + p["skill"]["cha"] * 0.004 - (0.1 if p["drunk"] > 40 else 0)))


def _steal(p, fn, a, arg):
    snap = copy.deepcopy(p)
    dry = copy.deepcopy(p)
    dry["cash"] += 1e9
    fn(dry, a, arg)
    spent = max(0.0, p["cash"] + 1e9 - dry["cash"])
    price_rub = spent * FX
    chance = max(0.08, min(0.85, 0.55 + p["skill"]["stealth"] * 0.01 - min(0.35, price_rub / 25000) - p["heat"] * 0.004))
    if random.random() < chance:
        p["cash"] = snap["cash"] + spent + 1
        msg = fn(p, a, arg)
        p["cash"] = snap["cash"]
        p["heat"] += 3 + price_rub / 2000
        p["skill"]["stealth"] += 0.4
        return "🥷 " + msg + " (стырил, никто не заметил)"
    p.clear()
    p.update(snap)
    p["heat"] += 12
    r = random.random()
    if r < 0.5:
        fine = min(p["cash"], R(1500))
        p["cash"] -= fine
        return f"охранник схватил за руку: штраф {fmt(fine)}$, товар отобрали"
    if r < 0.85:
        p["jail"] = time.time() + 180
        p["jailed"] += 1
        return "задержали: " + ("детская комната полиции" if age(p) < 18 else "обезьянник") + ", 3 мин"
    return "заметили, убежал без товара"


def _ask_adult(p, fn, a, arg):
    if random.random() < 0.3:
        return random.choice(["прохожий отмахнулся: «не буду»", "дядька отказался и ушёл", "тётка пригрозила позвать родителей"])
    snap = copy.deepcopy(p)
    msg = fn(p, a, arg)
    spent = snap["cash"] - p["cash"]
    if spent <= 0 and p["inv"] == snap["inv"]:
        return msg
    tip = spent * 0.3
    if p["cash"] < tip:
        p.clear()
        p.update(snap)
        return f"взрослый просит {fmt(spent + tip)}$ вместе с чаевыми, не хватает"
    p["cash"] -= tip
    if random.random() < 0.08:
        keep = max(0.0, snap["cash"] - spent - tip)
        p.clear()
        p.update(snap)
        p["cash"] = keep
        return "взрослый взял деньги, зашёл в магазин и не вернулся"
    return msg + f" (взрослому +{fmt(tip)}$ за помощь)"


def shop_wrap(fn, buys, is18):
    def w(p, a, arg):
        if a == "mode":
            p["bm"] = BM_ORDER[(BM_ORDER.index(p.get("bm", "buy")) + 1) % 3]
            return ""
        if buys is not None and a not in buys:
            return fn(p, a, arg)
        mode = p.get("bm", "buy")
        young = is18 and age(p) < 18
        if mode == "steal":
            return _steal(p, fn, a, arg)
        if mode == "ask" and young:
            return _ask_adult(p, fn, a, arg)
        if young and random.random() > _sell_chance(p):
            p["heat"] += 1
            return "продавец: «паспорт покажи». не продали"
        return fn(p, a, arg)
    return w


def wrap_render(sec, fn, is18):
    def r(p, page=0):
        t, rows = fn(p, page)
        hint = f"\n\n{BM[p.get('bm', 'buy')]}"
        if is18 and age(p) < 18:
            hint += f" · тебе {age(p)}: шанс, что продадут, ~{int(_sell_chance(p) * 100)}%"
        return t + hint, [[B("🔀 Способ: " + BM[p.get("bm", "buy")], f"{sec}:mode")]] + rows
    return r


# ───────── вейпы ─────────
def vp_refresh(p):
    now = time.time()
    for d in p["vpd"]:
        if d.get("ct"):
            d["chg"] = min(100.0, d["chg"] + (now - d["ct"]) / CHG_SEC * 100)
            d["ct"] = now if d["chg"] < 100 else 0


def vp_info(d):
    if d["t"] == "d":
        n, pr, puffs, nic, hp, rech, taste = DISP[d["k"]]
        return dict(name=n, nic=nic, hp=hp, taste=taste, rech=rech, cap=puffs * (0.45 if rech else 1.0))
    n, pr, tank, cap, _ = PODS[d["k"]]
    lq = LIQ.get(d.get("liq"))
    return dict(name=n, nic=lq[2] if lq else 0, hp=lq[3] if lq else 0, taste=lq[4] if lq else "пусто", rech=True, cap=cap)


def act_vape(p, a, arg):
    vp_refresh(p)
    v = p["vpd"]
    if a == "tab":
        p["vtab"] = arg
        return ""
    if a == "sel":
        p["vsel"] = arg
        return f"заправляю: {LIQ[arg][0]}"
    if a == "buy":
        t, _, k = arg.partition(":")
        src = {"d": DISP, "p": PODS, "l": LIQ}.get(t)
        if not src or k not in src:
            return ""
        price = src[k][1]
        if t != "l" and len(v) >= 8:
            return "в карманах уже 8 устройств"
        if p["cash"] < price:
            return f"нужно {fmt(price)}$"
        p["cash"] -= price
        if t == "d":
            v.append({"t": "d", "k": k, "puffs": DISP[k][2], "chg": 100.0, "ct": 0})
            return f"купил: {DISP[k][0]} ({DISP[k][2]} затяжек" + (", USB-C)" if DISP[k][5] else ", без зарядки)")
        if t == "p":
            v.append({"t": "p", "k": k, "puffs": 0, "chg": 100.0, "ct": 0, "liq": None})
            return f"купил: {PODS[k][0]}. залей жидкость"
        p["inv"]["vliq:" + k] = p["inv"].get("vliq:" + k, 0) + LIQ_FILLS
        p["vsel"] = k
        return f"купил жидкость: {LIQ[k][0]} ({LIQ_FILLS} заправок)"
    if a not in ("puff", "chg", "fill", "trash"):
        return ""
    i = int(arg)
    if i >= len(v):
        return "такого устройства нет"
    d = v[i]
    sp = vp_info(d)
    if a == "trash":
        v.pop(i)
        return f"выкинул: {sp['name']}"
    if a == "chg":
        if not sp["rech"]:
            return "у этой одноразки нет зарядки: села — выкидывай"
        if d.get("ct"):
            d["ct"] = 0
            return "снял с зарядки"
        if d["chg"] >= 100:
            return "и так полная"
        if p["home"] == "street" and p["inv"].get("good:powerbank", 0) <= 0:
            return "негде зарядить: нужен дом или повербанк"
        d["ct"] = time.time()
        return f"заряжается (~{CHG_SEC // 60} мин)"
    if a == "fill":
        if d["t"] == "d":
            if random.random() < 0.2:
                p["hp"] -= 4
                return "полез вскрывать одноразку: картридж запаян, жижа не заливается, только хлебнул химии (-4 ❤)"
            return "в одноразку жидкость не залить: картридж запаянный. хочешь заправляемый — бери под-систему"
        own = [k[5:] for k, n in p["inv"].items() if k.startswith("vliq:") and n > 0]
        if not own:
            return "нет жидкости, купи во вкладке «Жидкости»"
        lk = p["vsel"] if p["vsel"] in own else own[0]
        p["inv"]["vliq:" + lk] -= 1
        if p["inv"]["vliq:" + lk] <= 0:
            del p["inv"]["vliq:" + lk]
        d["puffs"] = PODS[d["k"]][2]
        d["liq"] = lk
        return f"заправил {sp['name']}: {LIQ[lk][0]}"
    # puff
    if d.get("ct"):
        return "стоит на зарядке"
    if d["puffs"] <= 0:
        return "пусто. " + ("залей жидкость" if d["t"] == "p" else "выкидывай")
    if d["chg"] <= 0:
        return "села батарея. " + ("воткни USB-C" if sp["rech"] else "одноразка не заряжается, выкидывай")
    d["puffs"] -= 1
    d["chg"] = max(0.0, d["chg"] - 100.0 / sp["cap"])
    p["add"]["nic"] = p["add"].get("nic", 0) + sp["nic"]
    p["lastuse"]["nic"] = time.time()
    p["mood"] += 3 * tolerance(p, "nic")
    p["hp"] -= sp["hp"]
    p["vaped"] = p.get("vaped", 0) + 1
    return f"затяжка: {sp['name']} ({sp['taste']})"


def r_vape(p, page=0):
    vp_refresh(p)
    rows = []
    for i, d in enumerate(p["vpd"][:8]):
        sp = vp_info(d)
        bat = f"🔌{int(d['chg'])}%" if d.get("ct") else f"🔋{int(d['chg'])}%"
        rows.append([B(f"💨 {sp['name']} · {d['puffs']} · {bat}", f"vape:puff:{i}")])
        rows.append([B("🔌 зарядка", f"vape:chg:{i}"), B("🧪 залить", f"vape:fill:{i}"), B("🗑", f"vape:trash:{i}")])
    liqs = [(k[5:], n) for k, n in p["inv"].items() if k.startswith("vliq:") and n > 0]
    for k, n in liqs[:3]:
        rows.append([B(("✅ " if p["vsel"] == k else "🧴 ") + f"{LIQ[k][0]} ×{n}", f"vape:sel:{k}")])
    tab = p.get("vtab", "d")
    rows.append([B(("• " if tab == t else "") + n, f"vape:tab:{t}") for t, n in (("d", "Одноразки"), ("p", "Под-системы"), ("l", "Жидкости"))])
    src = {"d": DISP, "p": PODS, "l": LIQ}[tab]
    keys = list(src)
    rows += paged("vape", keys, page, 6, lambda k: [B(f"{src[k][0]} · {fmt(src[k][1])}$", f"vape:buy:{tab}:{k}")])
    rows.append(back("vape"))
    info = []
    for k in slice_page(keys, page, 6):
        if tab == "d":
            info.append(f"· {DISP[k][0]}: {DISP[k][2]} затяжек, {'USB-C зарядка' if DISP[k][5] else 'без зарядки'}, {DISP[k][6]}")
        elif tab == "p":
            info.append(f"· {PODS[k][0]}: заправляемая, бак ~{PODS[k][2]} затяжек, USB-C")
        else:
            info.append(f"· {LIQ[k][0]}: {LIQ[k][4]}")
    head = (f"Вейпы. Никотин {int(p['add'].get('nic', 0))}%, затяжек за жизнь {p.get('vaped', 0)}. "
            "Одноразки не заправляются, у части есть USB-C. Под-системы заправляются жидкостью. Побочки: кашель, бронхит, EVALI.")
    return head + "\n\n" + "\n".join(info), rows


# ───────── телефон / SIM ─────────
def sim_tick(p):
    now = time.time()
    for s in p["sims"]:
        fee, gb = TAR[s["tar"]][2], TAR[s["tar"]][3]
        if s.get("off"):
            if s["bal"] >= fee:
                s["bal"] -= fee
                s["gb"] = gb
                s["t"] = now + 30 * DAY
                s["off"] = False
            continue
        n = 0
        while now >= s["t"] and n < 6:
            n += 1
            if s["bal"] >= fee:
                s["bal"] -= fee
                s["gb"] = gb
                s["t"] += 30 * DAY
            else:
                s["off"] = True
                s["gb"] = 0
                break


def ph_refresh(p):
    sim_tick(p)
    ph = p.get("ph")
    if ph and ph.get("ct"):
        now = time.time()
        ph["bat"] = min(100.0, ph["bat"] + (now - ph["ct"]) / PH_CHG * 100)
        ph["ct"] = now if ph["bat"] < 100 else 0


def net_state(p):
    ph = p.get("ph")
    if not ph:
        return "у тебя нет телефона"
    if PH[ph["k"]][3] == 0:
        return "кнопочный телефон не тянет интернет"
    if ph["bat"] <= 0:
        return "телефон разряжен"
    if p["home"] != "street":
        return ""
    i = ph.get("sim")
    if i is None or i >= len(p["sims"]):
        return "на улице нужна SIM с трафиком (дома работает Wi-Fi)"
    s = p["sims"][i]
    if s.get("off") or s["gb"] <= 0:
        return "на SIM нет денег или трафика"
    return ""


def ph_use(p, gb=0.05):
    ph = p["ph"]
    ph["bat"] = max(0.0, ph["bat"] - PH[ph["k"]][4] * 2)
    if p["home"] == "street" and ph.get("sim") is not None:
        p["sims"][ph["sim"]]["gb"] = max(0.0, p["sims"][ph["sim"]]["gb"] - gb)


def act_phone(p, a, arg):
    ph_refresh(p)
    ph = p.get("ph")
    if a == "chg":
        if not ph:
            return "нет телефона"
        if ph.get("ct"):
            ph["ct"] = 0
            return "снял с зарядки"
        if ph["bat"] >= 100:
            return "и так 100%"
        if p["home"] == "street" and p["inv"].get("good:powerbank", 0) <= 0:
            return "негде зарядить: нужен дом или повербанк"
        ph["ct"] = time.time()
        return f"заряжается (~{PH_CHG // 60} мин)"
    if a == "ins":
        i = int(arg)
        if not ph or i >= len(p["sims"]):
            return ""
        ph["sim"] = i
        return f"SIM в телефоне: {TAR[p['sims'][i]['tar']][0]}"
    if a == "top":
        i = int(arg)
        if i >= len(p["sims"]):
            return ""
        amt = R(300)
        if p["cash"] < amt:
            return f"нужно {fmt(amt)}$"
        p["cash"] -= amt
        p["sims"][i]["bal"] += amt
        return f"баланс пополнен на {fmt(amt)}$"
    if a == "sell":
        if not ph:
            return "нечего продавать"
        v = PH[ph["k"]][1] * 0.5
        p["cash"] += v
        p["ph"] = None
        return f"продал {PH[ph['k']][0]} за {fmt(v)}$"
    if a == "feed":
        if not ph:
            return "нет телефона"
        err = net_state(p)
        if err:
            return err
        ph_use(p, 0.1)
        p["mood"] += 4
        return "полистал ленту: +4 к настроению"
    return ""


def r_phone(p, page=0):
    ph_refresh(p)
    ph = p.get("ph")
    if not ph:
        return ("📱 Телефона нет. В салоне связи есть всё: от кнопочных за пару тысяч до флагманов. "
                "Без телефона нет браузера, а без SIM он работает только дома по Wi-Fi."), [[B("🛒 Салон связи", "pshop")], back("phone")]
    n, pr, tier, net, dr = PH[ph["k"]]
    sim = p["sims"][ph["sim"]] if ph.get("sim") is not None and ph["sim"] < len(p["sims"]) else None
    L = [f"📱 {n} · {TIERS[tier]}", f"🔋 {bar(ph['bat'])} {int(ph['bat'])}%" + (" 🔌 заряжается" if ph.get("ct") else ""),
         "📶 " + (f"{TAR[sim['tar']][0]} · {fmt(sim['bal'])}$ · {sim['gb']:.1f} ГБ" + (" · ⛔ заблокирована" if sim.get("off") else "") if sim else "SIM не вставлена"),
         "🌐 интернет: " + (net_state(p) or ("Wi-Fi" if p["home"] != "street" else "мобильный"))]
    rows = [[B("🌐 Браузер", "web:site:"), B("📲 Лента", "phone:feed"), B("🔌 Зарядка", "phone:chg")]]
    for i, s in enumerate(p["sims"][:4]):
        rows.append([B(("✅ " if ph.get("sim") == i else "📶 ") + f"{TAR[s['tar']][0]} {s['num']}", f"phone:ins:{i}"), B(f"💳 +{fmt(R(300))}$", f"phone:top:{i}")])
    rows.append([B("🛒 Салон связи", "pshop"), B("💸 Продать телефон", "phone:sell")])
    rows.append(back("phone"))
    return "\n".join(L), rows


def act_pshop(p, a, arg):
    if a == "tab":
        p["ptab"] = arg
        return ""
    if a == "buy":
        if arg not in PH:
            return ""
        n, price, tier, net, dr = PH[arg]
        if p["cash"] < price:
            return f"нужно {fmt(price)}$"
        p["cash"] -= price
        old = p.get("ph")
        trade = 0.0
        if old:
            trade = PH[old["k"]][1] * 0.3
            p["cash"] += trade
        p["ph"] = {"k": arg, "bat": 80.0, "sim": old.get("sim") if old else None, "ct": 0}
        return f"купил: {n}" + (f" (старый в трейд-ин +{fmt(trade)}$)" if trade else "")
    if a == "sim":
        if arg not in TAR:
            return ""
        op, n, fee, gb = TAR[arg]
        cost = fee + R(100)
        if p["cash"] < cost:
            return f"нужно {fmt(cost)}$ (SIM 100 ₽ + первый месяц)"
        if len(p["sims"]) >= 4:
            return "в кармане уже 4 SIM"
        p["cash"] -= cost
        s = {"tar": arg, "bal": 0.0, "gb": float(gb), "t": time.time() + 30 * DAY, "off": False, "num": "+7 9" + "".join(random.choice("0123456789") for _ in range(2)) + "…" + "".join(random.choice("0123456789") for _ in range(2))}
        p["sims"].append(s)
        if p.get("ph") and p["ph"].get("sim") is None:
            p["ph"]["sim"] = len(p["sims"]) - 1
        return f"купил SIM: {op} «{n}»"
    return ""


def r_pshop(p, page=0):
    tab = p.get("ptab", "1")
    chips = [B(("• " if tab == str(i) else "") + n, f"pshop:tab:{i}") for i, n in enumerate(TIERS)] + [B(("• " if tab == "sim" else "") + "SIM", "pshop:tab:sim")]
    rows = [chips[:3], chips[3:]]
    if tab == "sim":
        keys = list(TAR)
        rows += paged("pshop", keys, page, 6, lambda k: [B(f"📶 {TAR[k][0]} {TAR[k][1]} · {fmt(TAR[k][2] + R(100))}$", f"pshop:sim:{k}")])
        info = "\n".join(f"· {TAR[k][0]} «{TAR[k][1]}»: {fmt(TAR[k][2])}$/мес, {TAR[k][3]} ГБ" for k in slice_page(keys, page, 6))
    else:
        keys = sorted([k for k in PH if PH[k][2] == int(tab)], key=lambda k: PH[k][1])
        rows += paged("pshop", keys, page, 6, lambda k: [B(f"📱 {PH[k][0]} · {fmt(PH[k][1])}$", f"pshop:buy:{k}")])
        info = "\n".join(f"· {PH[k][0]}: {'интернет есть' if PH[k][3] else 'только звонки, без интернета'}" for k in slice_page(keys, page, 6))
    rows.append(back("pshop"))
    return "Салон связи. Старый телефон уходит в трейд-ин за 30%. SIM: 100 ₽ + первый месяц тарифа, дальше списание раз в 30 дней с баланса.\n\n" + info, rows


# ───────── браузер ─────────
def av_price(p, k):
    return PH[k][1] * random.Random(f"{p['uid']}{k}{int(time.time() // 3600)}").uniform(0.45, 0.7)


def _paycheck(p, price):
    if p["cash"] < price:
        return f"нужно {fmt(price)}$"
    p["cash"] -= price
    return ""


def act_web(p, a, arg):
    ph_refresh(p)
    if a == "site":
        p["ws"] = arg
        return ""
    err = net_state(p)
    if err:
        return err
    ph_use(p)
    if a == "eda":
        name, price, *_ = FOOD[arg]
        extra = price * 0.2 + R(100)
        if p["cash"] < price + extra:
            return f"нужно {fmt(price + extra)}$ (доставка)"
        p["cash"] -= extra
        return "🛵 " + act_food(p, "eat", arg)
    if a == "oz":
        name, price = GOODS[arg]
        extra = price * 0.1
        if p["cash"] < price + extra:
            return f"нужно {fmt(price + extra)}$"
        p["cash"] -= extra
        return "📦 " + act_goods(p, "buy", arg)
    if a == "av":
        if arg not in PH:
            return ""
        pr = av_price(p, arg)
        if p["cash"] < pr:
            return f"нужно {fmt(pr)}$"
        p["cash"] -= pr
        if random.random() < 0.12:
            return "встретились у метро: коробка с кирпичом вместо телефона. развели"
        old = p.get("ph")
        p["ph"] = {"k": arg, "bat": 60.0, "sim": old.get("sim") if old else None, "ct": 0}
        return f"купил с рук: {PH[arg][0]} за {fmt(pr)}$"
    if a == "dbuy":
        si, _, dk = arg.partition("_")
        si = int(si)
        if si not in p["sites"] or dk not in DRUGS:
            return "сайт не найден"
        if len(p["orders"]) >= 3:
            return "у тебя уже 3 неподобранных заказа"
        price = DRUGS[dk][1] * DSHOPS[si][2]
        if p["cash"] < price:
            return f"нужно {fmt(price)}$"
        p["cash"] -= price
        city = CITIES.get(p["city"], CITIES["samara"])[0]
        p["orders"].append({"d": dk, "spot": f"{city}: {random.choice(SP_AREA)}, у места «{random.choice(SP_MARK)}»", "t": time.time()})
        return f"оплачено: {DRUGS[dk][0]}. адрес пришёл — смотри Улица → Клады"
    return ""


def r_web(p, page=0):
    ph_refresh(p)
    ws = p.get("ws", "")
    err = net_state(p)
    if err:
        return f"🌐 Браузер. {err}.", [[B("📱 Телефон", "phone")]]
    home_back = [B("🔙 Сайты", "web:site:")]
    if ws == "eda":
        keys = list(FOOD)
        rows = paged("web", keys, page, 6, lambda k: [B(f"🍽 {FOOD[k][0]} · {fmt(FOOD[k][1] * 1.2 + R(100))}$", f"web:eda:{k}")])
        return "🛵 Яндекс Еда. Доставка +20% и 100 ₽.", rows + [home_back]
    if ws == "oz":
        keys = list(GOODS)
        rows = paged("web", keys, page, 6, lambda k: [B(f"📦 {GOODS[k][0]} · {fmt(GOODS[k][1] * 1.1)}$", f"web:oz:{k}")])
        return "🟣 Ozon. Товары без возрастных ограничений, +10% к цене.", rows + [home_back]
    if ws == "av":
        keys = random.Random(f"{p['uid']}{int(time.time() // 3600)}").sample(list(PH), 8)
        rows = paged("web", keys, page, 8, lambda k: [B(f"🏷 {PH[k][0]} · {fmt(av_price(p, k))}$", f"web:av:{k}")])
        return "🟢 Авито. Б/у телефоны на 30-55% дешевле. Иногда попадаются мошенники.", rows + [home_back]
    if ws.startswith("d") and ws[1:].isdigit() and int(ws[1:]) in p["sites"]:
        si = int(ws[1:])
        sh = DSHOPS[si]
        keys = list(DRUGS)
        rows = paged("web", keys, page, 6, lambda k: [B(f"{ICON.get(k, '💊')} {DRUGS[k][0]} · {fmt(DRUGS[k][1] * sh[2])}$", f"web:dbuy:{si}_{k}")])
        return f"🕶 {sh[0]} · {sh[1]}\nПосле оплаты придёт адрес закладки. Идти за ней нужно самому: Улица → Клады. Бывает, что клад не находят или кидают.", rows + [home_back]
    rows = [[B("🛵 Яндекс Еда", "web:site:eda"), B("🟣 Ozon", "web:site:oz")], [B("🟢 Авито", "web:site:av")]]
    for si in p["sites"]:
        rows.append([B(f"🕶 {DSHOPS[si][1]}", f"web:site:d{si}")])
    rows.append([B("📱 Телефон", "phone")])
    return "🌐 Браузер. Закрытых сайтов в закладках: " + str(len(p["sites"])) + ". Адреса пишут на стенах, ищи на улице.", rows


# ───────── улица: граффити → сайт → клад, закладчик, прогулка ─────────
def act_street(p, a, arg):
    now = time.time()
    if a == "graf":
        if p["energy"] < 2:
            return "нет сил"
        p["energy"] -= 2
        new = [i for i in range(len(DSHOPS)) if i not in p["sites"]]
        if not new:
            return "все граффити в округе уже срисовал"
        if random.random() > 0.9:
            return "облазил пару дворов, ничего нового"
        i = random.choice(new)
        p["sites"].append(i)
        return f"нашёл граффити: «{DSHOPS[i][0]} · {DSHOPS[i][1]} · закладки 24/7». адрес в закладках браузера"
    if a == "walk":
        if p["energy"] < 3:
            return "нет сил"
        p["energy"] -= 3
        r = random.random()
        if r < 0.35:
            x = R(random.randint(50, 400))
            p["cash"] += x
            return f"нашёл на асфальте {fmt(x)}$"
        if r < 0.55:
            p["mood"] += 4
            return "встретил знакомых, поболтали (+4 к настроению)"
        if r < 0.65 and p["heat"] > 10:
            p["heat"] += 5
            return "патруль проверил документы, нервный день"
        p["mood"] += 1
        return "просто прошёлся по району"
    if a == "dig":
        i = int(arg)
        if i >= len(p["orders"]):
            return "такого заказа нет"
        if p["energy"] < 8:
            return "нужно 8 энергии"
        p["energy"] -= 8
        o = p["orders"].pop(i)
        r = random.random() - p["skill"]["stealth"] * 0.002
        name = DRUGS[o["d"]][0]
        if r < 0.72:
            p["inv"]["drug:" + o["d"]] = p["inv"].get("drug:" + o["d"], 0) + 1
            p["skill"]["stealth"] += 0.3
            return f"нашёл клад: {name}"
        if r < 0.85:
            return f"на месте пусто ({name}). либо кинули, либо подобрали раньше"
        if r < 0.95:
            p["heat"] += 25
            if random.random() < 0.4:
                p["jail"] = now + 300
                p["jailed"] += 1
                return "на точке были оперативники: 5 мин в обезьяннике, клад пропал"
            return "рядом ходил патруль, ушёл ни с чем"
        p["heat"] += 8
        return "клад перехватил кто-то другой, ты опоздал"
    if a == "take":
        if p["batch"]:
            return "у тебя уже есть незакрытая партия"
        ph = p.get("ph")
        if not ph or ph["bat"] <= 0:
            return "куратор пишет в мессенджер: нужен заряженный телефон"
        rank = min(4, p.get("dealer", 0) // 3)
        dep = R(3000) if rank < 2 else 0.0
        if p["cash"] < dep:
            return f"залог {fmt(dep)}$"
        p["cash"] -= dep
        pay = R(900) * (1 + 0.25 * rank) * cm(p, 2)
        p["batch"] = {"left": 5, "pay": pay, "dep": dep, "got": 0.0}
        return f"взял партию: 5 закладок, {fmt(pay)}$ за каждую" + (f", залог {fmt(dep)}$" if dep else "")
    if a == "place":
        b = p["batch"]
        if not b:
            return "партии нет, возьми у куратора"
        if p["energy"] < 6:
            return "нужно 6 энергии"
        p["energy"] -= 6
        p["skill"]["stealth"] += 0.2
        if random.random() < 0.03:
            p["batch"] = None
            return "куратор пропал вместе с залогом. кинули"
        if random.random() < 0.035 + p["heat"] * 0.002:
            p["batch"] = None
            p["heat"] += 30
            p["jail"] = now + 480
            p["jailed"] += 1
            return "задержали с партией: 8 мин, залог и партия пропали"
        b["left"] -= 1
        b["got"] += b["pay"]
        p["heat"] += 4
        if b["left"] > 0:
            return f"заложил, осталось {b['left']}. накоплено {fmt(b['got'])}$"
        total = b["got"] + b["dep"]
        p["cash"] += total
        p["batch"] = None
        p["dealer"] = p.get("dealer", 0) + 1
        return f"партия закрыта: +{fmt(total)}$. ранг: {DEALER_RANKS[min(4, p['dealer'] // 3)]}"
    if a == "drop":
        if not p["batch"]:
            return ""
        p["batch"] = None
        return "бросил партию, залог сгорел"
    return ""


def r_street(p, page=0):
    rank = DEALER_RANKS[min(4, p.get("dealer", 0) // 3)]
    L = [f"🌆 Улица · {CITIES.get(p['city'], CITIES['samara'])[0]}", f"🎨 граффити-сайтов найдено: {len(p['sites'])}/{len(DSHOPS)}", f"📦 заказов ждёт: {len(p['orders'])}"]
    rows = [[B("🎨 Искать граффити", "street:graf"), B("🚶 Прогуляться", "street:walk")]]
    for i, o in enumerate(p["orders"]):
        rows.append([B(f"🧭 Клад: {DRUGS[o['d']][0]}", f"street:dig:{i}")])
        L.append(f"· {DRUGS[o['d']][0]}: {o['spot']}")
    L.append("")
    if p["batch"]:
        b = p["batch"]
        L.append(f"🎒 Закладчик ({rank}): осталось {b['left']}, накоплено {fmt(b['got'])}$")
        rows.append([B("📍 Заложить", "street:place"), B("🗑 Бросить", "street:drop")])
    else:
        L.append(f"🎒 Закладчик ({rank}), закрыто партий {p.get('dealer', 0)}. Работа для любого возраста: залог 3000 ₽ (с ранга 3 без залога), риск облав и кидалова.")
        rows.append([B("🎒 Взять партию", "street:take")])
    rows.append(back("street"))
    return "\n".join(L), rows


# ───────── интим-магазин (строго 18+, никаких обходов) ─────────
def act_sexshop(p, a, arg):
    if age(p) < 18:
        return "🔞 не пускают. вообще. только с 18"
    if a == "buy":
        name, price, kind, val = SEX[arg]
        if p["cash"] < price:
            return f"нужно {fmt(price)}$"
        p["cash"] -= price
        if kind == "cond":
            p["inv"]["good:protect"] = p["inv"].get("good:protect", 0) + val
            return f"купил: {name}"
        p["inv"]["sx:" + arg] = p["inv"].get("sx:" + arg, 0) + 1
        return f"купил: {name}"
    if a == "use":
        key = "sx:" + arg
        if p["inv"].get(key, 0) <= 0:
            return "нет такого"
        name, price, kind, val = SEX[arg]
        if kind == "gift":
            if not p["girls"]:
                return "дарить некому"
            g = max(p["girls"], key=lambda x: x["rel"])
            g["rel"] += val
            msg = f"подарил {g['name']}: {name} (+{val} к отношениям)"
        else:
            p["mood"] += val
            msg = f"{name}: +{val} к настроению"
        p["inv"][key] -= 1
        if p["inv"][key] <= 0:
            del p["inv"][key]
        return msg
    return ""


def r_sexshop(p, page=0):
    if age(p) < 18:
        return "🔞 Вход только с 18 лет.", [back("sexshop")]
    own = [(k[3:], n) for k, n in p["inv"].items() if k.startswith("sx:") and n > 0]
    rows = [[B(f"🎁 Использовать/подарить {SEX[k][0]} ×{n}", f"sexshop:use:{k}")] for k, n in own[:4]]
    keys = list(SEX)
    rows += paged("sexshop", keys, page, 7, lambda k: [B(f"{SEX[k][0]} · {fmt(SEX[k][1])}$", f"sexshop:buy:{k}")])
    rows.append(back("sexshop"))
    return "Интим-магазин 18+. Контрацептивы, подарки и всё для приятного вечера. Презервативы идут в общий запас.", rows


