def status(p):
    h = HOUSING[p["home"]]
    job = JOBS[p["job"]][0] if p["job"] is not None else "безработный"
    a = age(p)
    c = CITIES.get(p.get("city"), CITIES["samara"])[0]
    L = [f"┏━━ 👤 {p['name']} · {a} {yrs(a)}",
         f"┃ 📍 {c} · ☠ смертей {p['deaths']}",
         "┣━━━━━━━━━━━━━━━",
         f"┃ 💵 {fmt(p['cash'])}$  🏦 {fmt(p['bank'])}$  📉 {fmt(debt_total(p))}$",
         f"┃ ❤️ {bar(p['hp'])} {int(p['hp'])}",
         f"┃ ⚡ {bar(p['energy'])} {int(p['energy'])}",
         f"┃ 🙂 {bar(p['mood'])} {int(p['mood'])}",
         f"┃ 🍔 голод {int(p['hunger'])}  🚨 розыск {int(p['heat'])}" + (f"  🥴 {int(p['drunk'])}" if p["drunk"] >= 1 else ""),
         f"┃ 🏠 {h[0]} ({'своё' if p['home_own'] else 'аренда' if p['home'] not in ('street', 'family') else 'без жилья' if p['home'] == 'street' else 'семья'})",
         f"┃ 💼 {job} (опыт {p['xp']})" + (f" · 🚗 {CARS[p['car']][0]}" if p["car"] else "")]
    ph = p.get("ph")
    if ph:
        sim = p["sims"][ph["sim"]] if ph.get("sim") is not None and ph["sim"] < len(p["sims"]) else None
        L.append(f"┃ 📱 {PH[ph['k']][0]} · 🔋{int(ph['bat'])}% · {TAR[sim['tar']][0] if sim else 'без SIM'}")
    L.append("┗━━━━━━━━━━━━━━━")
    if a >= 18 and p["girls"]:
        L.append("💞 " + ", ".join(g["name"] + ("💍" if p["spouse"] == g["name"] else "") for g in p["girls"][:4]))
    if p["kids"]:
        L.append(f"👶 детей: {len(p['kids'])}")
    if p["dis"]:
        L.append("🤒 " + ", ".join(DIS[k][0] if d.get("dx") else "неясное" for k, d in p["dis"].items()))
    adds = [f"{ADD_INFO.get(k, (k,))[0]} {int(v)}%" for k, v in p["add"].items() if v >= 5]
    if adds:
        L.append("⛓ зависимость: " + ", ".join(adds))
    if p["jail"]:
        L.append(f"🔒 в тюрьме ещё ~{int((p['jail'] - time.time()) // 60) + 1} мин")
    return "\n".join(L)


