# ---- config ----
kBdayCdSec = 0            # кд на день рождения
kPoliceActive = False     # False: розыск не копится, тюрьмы нет (штрафы остаются)
kShopMinAge = 18          # свой шоп: паспорт на сайт/ИП
kLighterPrice = R(120)
kLighterCharges = 20
kSiteCost = R(40000)
kCourierHire, kMgrHire, kGrafCost = R(4000), R(12000), R(2500)
kWholesale, kMarkup = 0.55, 1.6
kRepairMax, kFurnMax = 5, 8
kFlatSleepCdSec = 0      # кд сна дома (0 = без кд)
SMOKABLE = {"weed", "hash", "spi"}   # drug ids, которые курят (нужен огонь)


def _snap(p):
    return {"mood": p["mood"], "hp": p["hp"], "energy": p["energy"], "add": dict(p["add"])}


def _fx(p, s):
    out = []
    for k, label in (("mood", "настроение"), ("hp", "здоровье"), ("energy", "энергия")):
        d = p[k] - s[k]
        if abs(d) >= 0.5:
            out.append(f"{label} {d:+.0f}")
    for k, v in p["add"].items():
        d = v - s["add"].get(k, 0)
        if d >= 0.5:
            out.append(f"зависимость {ADD_INFO.get(k, (k,))[0]} +{d:.0f}%")
    return " · ".join(out)


# ---- birthday: no cooldown ----
_main0 = ACT["main"]


def act_main2(p, a, arg):
    p["cd"]["bday"] = 0
    r = _main0(p, a, arg)
    p["cd"]["bday"] = time.time() + kBdayCdSec if kBdayCdSec else 0
    return r


# ---- police: nobody cares ----
_fin0 = finalize


def finalize(p):
    if not kPoliceActive:
        p["jail"] = 0
        p["heat"] = min(p["heat"], 5.0)
    return _fin0(p)


# ---- lighter-gated smoking + side-effect notes ----
def _fire_wrap(fn, needs):
    def w(p, a, arg):
        need = needs(a, arg)
        if need and p.get("lighter", 0) <= 0:
            return "🔥 без зажигалки не закуришь. купи в 🔥 Курилке"
        snap, before = _snap(p), sum(p["inv"].values())
        msg = fn(p, a, arg)
        if need and sum(p["inv"].values()) < before:
            p["lighter"] -= 1
        fx = _fx(p, snap) if a in ("smoke", "use", "take") else ""
        return msg + (f"\n[{fx}]" if fx else "")
    return w


_pharm0 = ACT["pharm"]


def _pharm_take(p, a, arg):
    if a != "take":
        return _pharm0(p, a, arg)
    now = time.time()
    recent = [t for t in p.get("mt", []) if now - t < 1800] + [now]
    p["mt"] = recent
    msg = _pharm0(p, a, arg)
    n = len(recent)
    if n > 3:
        loss = 6 * (n - 3) + (40 if n >= 8 else 0)
        p["hp"] -= loss
        msg += f"\n⚠ таблеток за полчаса: {n}. передоз-симптомы: -{loss} здоровья"
    return msg


ACT["cigs"] = _fire_wrap(ACT["cigs"], lambda a, arg: a == "smoke")
ACT["subs"] = _fire_wrap(ACT["subs"], lambda a, arg: a == "use" and arg in SMOKABLE)
ACT["pharm"] = _fire_wrap(_pharm_take, lambda a, arg: False)


def _use_item(p, key):
    kind, _, k = key.partition(":")
    if kind == "cig":
        return ACT["cigs"](p, "smoke", k)
    if kind == "drug":
        return ACT["subs"](p, "use", k)
    if kind == "med":
        return ACT["pharm"](p, "take", k)
    return "это так не используют"


# ---- 🎒 pocket ----
def _item_name(key):
    kind, _, k = key.partition(":")
    src = {"cig": CIGS, "drug": DRUGS, "med": MEDS}.get(kind)
    if not src or k not in src:
        return None
    ic = {"cig": "🚬", "med": "💊"}.get(kind) or ICON.get(k, "💊")
    return f"{ic} {src[k][0]}"


def _item_info(key):
    kind, _, k = key.partition(":")
    if kind == "cig":
        n, price, nic, hp = CIGS[k]
        return f"{n}. никотин +{nic}% зависимости, здоровье -{hp} за сигарету. нужна зажигалка."
    if kind == "drug":
        n, price, mood, en, hp, addg, od = DRUGS[k]
        fire = " Курится: нужна зажигалка." if k in SMOKABLE else ""
        return (f"{n}. настроение {mood:+d}, энергия {en:+d}, здоровье {hp:+d}, зависимость +{addg}%, "
                f"риск передоза {int(od * 100)}%/приём (растёт с толерантностью).{fire}")
    if kind == "med":
        n, price, rx, cures, manage, hp = MEDS[k]
        cure = ", ".join(DIS[d][0] for d in cures if d in DIS) or "симптоматика"
        return f"{n}. помогает: {cure}. много за раз = передоз-симптомы."
    return ""


def r_pocket(p, page=0):
    items = [(k, v) for k, v in p["inv"].items() if v > 0 and _item_name(k)]
    sel = p.get("psel")
    if sel and p["inv"].get(sel, 0) > 0 and _item_name(sel):
        rows = [[B("▶ Использовать", "pocket:use:" + sel)], [B("↩ К карману", "pocket:close")], back("pocket")]
        return f"{_item_name(sel)} ×{p['inv'][sel]}\n\n{_item_info(sel)}\n\n🔥 зажигалка: {p.get('lighter', 0)} зарядов", rows
    rows = paged("pocket", items, page, 8, lambda kv: [B(f"{_item_name(kv[0])} ×{kv[1]}", "pocket:open:" + kv[0])])
    rows.append(back("pocket"))
    head = f"🎒 Карман. Всё, что купил: тапни предмет, увидишь побочки и сможешь использовать.\n🔥 зажигалка: {p.get('lighter', 0)} зарядов"
    return head if items else head + "\n\nпусто", rows


def act_pocket(p, a, arg):
    if a == "open":
        p["psel"] = arg
        return ""
    if a == "close":
        p["psel"] = ""
        return ""
    if a == "use":
        r = _use_item(p, arg)
        if p["inv"].get(arg, 0) <= 0:
            p["psel"] = ""
        return r
    return ""


# ---- 🔥 smoke room ----
def r_smoke(p, page=0):
    own = [(k, v) for k, v in p["inv"].items() if v > 0 and (k.startswith("cig:") or (k.startswith("drug:") and k[5:] in SMOKABLE))]
    rows = [[B(f"🔥 Зажигалка · {fmt(kLighterPrice)}$ (+{kLighterCharges})", "smoke:lighter")]]
    rows += [[B(f"{_item_name(k)} ×{v} · курить", f"smoke:use:{k}"), B("ℹ", "pocket:open:" + k)] for k, v in own[:6]]
    rows.append([B("💨 Вейпы", "vape"), B("🟢 Снюс", "snus"), B("🫖 Кальян", "hookah")])
    rows.append(back("smoke"))
    head = (f"🔥 Курилка. Сигареты, трава, гашиш, спайс: без зажигалки нельзя. Заряды: {p.get('lighter', 0)}.\n"
            "Побочки пишутся после каждой затяжки. Предметы лежат в 🎒 Кармане.")
    return head + ("" if own else "\n\nкурить нечего: сигареты в 🚬 Сигареты, остальное в 💊 Вещества"), rows


def act_smoke(p, a, arg):
    if a == "lighter":
        if p["cash"] < kLighterPrice:
            return f"нужно {fmt(kLighterPrice)}$"
        p["cash"] -= kLighterPrice
        p["lighter"] = p.get("lighter", 0) + kLighterCharges
        return f"купил зажигалку: {p['lighter']} зарядов"
    if a == "use":
        return _use_item(p, arg)
    return ""


# ---- 🛋 flat ----
def _fl(p):
    return p.setdefault("flat", {"rep": 0, "furn": 0, "fridge": 0})


_comfort0 = comfort


def comfort(p):
    f = p.get("flat") or {}
    return _comfort0(p) * (1 + (f.get("rep", 0) * 4 + f.get("furn", 0) * 3) / 100)


def _flat_ok(p):
    return p["home"] != "street"


def _own(p):
    return p["home"] not in ("family", "capsule", "hostel")


def r_flat(p, page=0):
    if not _flat_ok(p):
        return "🛋 Ты на улице. Сначала сними жильё в 🏠 Жильё.", [back("flat")]
    f, own = _fl(p), _own(p)
    rc, fc = R(25000) * (f["rep"] + 1), R(8000) + R(2000) * f["furn"]
    rows = []
    if own:
        rows.append([B(f"🛠 Ремонт {f['rep']}/{kRepairMax} · {fmt(rc)}$", "flat:repair"), B(f"🪑 Мебель {f['furn']}/{kFurnMax} · {fmt(fc)}$", "flat:furn")])
    rows.append([B(f"🍳 Готовить (холодильник {f['fridge']})", "flat:cook"), B(f"🛒 Закупить продукты · {fmt(R(1200))}$", "flat:shop")])
    left = cdleft(p, "fsleep")
    rows.append([B("🛏 Поспать" + (f" · через {int(left) + 1}с" if left > 0 else ""), "flat:sleep")])
    rows.append([B("🧹 Прибраться", "flat:clean"), B(f"👥 Позвать друзей · {fmt(R(600))}$", "flat:friends")])
    if age(p) >= 18 and p["girls"] and own:
        rows.append([B(f"💞 Позвать на ужин · {fmt(R(400))}$", "flat:date")])
    rows.append(back("flat"))
    bonus = f["rep"] * 4 + f["furn"] * 3
    h = HOUSING[p["home"]]
    rent = 0 if p["home_own"] else int(h[2] * cm(p, 1))
    debt = debt_total(p, "bills")
    info = f"🛋 {h[0]} · " + ("своё" if p["home_own"] else f"аренда {fmt(rent)}$/день" if rent else "жильё семьи")
    info += f" · коммуналка {fmt(h[4] * cm(p, 3))}$/день"
    if debt > 1:
        info += f"\n⚠ долг по счетам {fmt(debt)}$: выселят, если не погасить"
    return f"{info}\nКомфорт от ремонта и мебели: +{bonus}% к восстановлению энергии.", rows


def act_flat(p, a, arg):
    if not _flat_ok(p):
        return "нужна квартира"
    f, own = _fl(p), _own(p)
    if a in ("repair", "furn") and not own:
        return "это квартира родителей"
    if a == "repair":
        cost = R(25000) * (f["rep"] + 1)
        if f["rep"] >= kRepairMax:
            return "ремонт закончен"
        if p["cash"] < cost:
            return f"нужно {fmt(cost)}$"
        p["cash"] -= cost
        f["rep"] += 1
        p["mood"] += 6
        return f"ремонт, этап {f['rep']}/{kRepairMax}: комфорт +4%"
    if a == "furn":
        cost = R(8000) + R(2000) * f["furn"]
        if f["furn"] >= kFurnMax:
            return "обставлено под завязку"
        if p["cash"] < cost:
            return f"нужно {fmt(cost)}$"
        p["cash"] -= cost
        f["furn"] += 1
        p["mood"] += 4
        return f"обставил ({f['furn']}/{kFurnMax}): комфорт +3%"
    if a == "sleep":
        left = cdleft(p, "fsleep")
        if left > 0:
            return f"только лёг, подожди {int(left) + 1} сек"
        p["cd"]["fsleep"] = time.time() + kFlatSleepCdSec
        c = comfort(p)
        p["energy"] += 55 * c
        p["hp"] += 8 * c
        p["hunger"] += 8
        p["mood"] += 5
        return f"выспался дома: энергия +{int(55 * c)}, здоровье +{int(8 * c)}"
    if a == "shop":
        if p["cash"] < R(1200):
            return f"нужно {fmt(R(1200))}$"
        p["cash"] -= R(1200)
        f["fridge"] += 6
        return "закупился: +6 порций в холодильнике"
    if a == "cook":
        if p["energy"] < 3:
            return "нет сил"
        if f["fridge"] > 0:
            f["fridge"] -= 1
        elif p["cash"] >= R(150):
            p["cash"] -= R(150)
        else:
            return f"нужно {fmt(R(150))}$ или продукты"
        p["energy"] -= 3
        p["hunger"] = max(0, p["hunger"] - 35)
        p["mood"] += 5
        return "приготовил и поел дома: голод -35"
    if a == "clean":
        if p["energy"] < 4:
            return "нет сил"
        p["energy"] -= 4
        p["mood"] += 3
        return "прибрался: на душе спокойнее"
    if a == "friends":
        if p["home"] == "capsule":
            return "в капсуле гостей не принять"
        if p["cash"] < R(600) or p["energy"] < 3:
            return f"нужно {fmt(R(600))}$ и 3 энергии"
        p["cash"] -= R(600)
        p["energy"] -= 3
        p["mood"] += 10
        return "друзья зашли, посидели: настроение +10"
    if a == "date":
        if age(p) < 18 or not p["girls"] or not own:
            return "пока нельзя"
        if p["cash"] < R(400):
            return f"нужно {fmt(R(400))}$"
        p["cash"] -= R(400)
        g = random.choice(p["girls"])
        g["rel"] += random.randint(4, 9)
        p["mood"] += 8
        return f"ужин дома с {g['name']}: отношения выросли"
    return ""


# ---- 🕸 own shop ----
def _ds_sim(p):
    d = p["ds"]
    now = time.time()
    hrs = min((now - d["t"]) / 3600, 12)
    d["t"] = now
    if hrs <= 0:
        return ""
    demand = (1 + d["graf"] * 0.6) * (0.4 + d["rep"] / 60) * 4 * hrs / (1 + d.get("comp", 0) * 0.35)
    cap = (0.5 + d["couriers"] * 5) * hrs
    want = int(min(demand, cap) + random.random())
    keys = [k for k, v in d["stock"].items() if v > 0]
    sold, rev = 0, 0.0
    for _ in range(want):
        if not keys:
            break
        k = random.choice(keys)
        d["stock"][k] -= 1
        rev += DRUGS[k][1] * kMarkup
        sold += 1
        if d["stock"][k] <= 0:
            keys.remove(k)
    wage = (d["couriers"] * R(120) + d["mgrs"] * R(300)) * hrs
    d["cash"] += rev - wage
    d["sold"] += sold
    d["rep"] = max(0.0, min(100.0, d["rep"] + sold * 0.15 - (2 * hrs if want and not sold else 0)))
    msg = ""
    if random.random() < min(0.9, hrs * 0.04 * (1 - min(0.75, d["mgrs"] * 0.25))) and any(d["stock"].values()):
        for k in d["stock"]:
            d["stock"][k] //= 2
        d["rep"] = max(0.0, d["rep"] - 8)
        msg = "облава на склад: половина товара пропала, репутация -8"
    ev = [msg] if msg else []
    if d.get("comp", 0) < 4 and random.random() < min(0.6, hrs * 0.05):
        d["comp"] = d.get("comp", 0) + 1
        ev.append("в районе открылся конкурент: трафик падает")
    if d["graf"] > 0 and random.random() < min(0.8, hrs * 0.05 * d["graf"] / 3):
        d["graf"] -= 1
        ev.append("конкуренты закрасили твоё граффити")
    if d["couriers"] and random.random() < min(0.9, hrs * 0.03 * d["couriers"] * (1 - min(0.8, d["mgrs"] * 0.3))):
        d["couriers"] -= 1
        ks = [k for k, v in d["stock"].items() if v > 0]
        lost = 0
        if ks:
            k = random.choice(ks)
            lost = min(6, d["stock"][k])
            d["stock"][k] -= lost
        ev.append((f"курьер кинул: пропал с товаром ({lost} шт)" if lost else "курьер ушёл: склад пуст, платить нечем") + ". менеджеры снижают риск")
    d.setdefault("log", []).extend(ev)
    d["log"] = d["log"][-3:]
    return "; ".join(ev)


def r_dshop(p, page=0):
    if age(p) < kShopMinAge:
        return f"🕸 Свой шоп открывают с {kShopMinAge} лет: паспорт на сайт и ИП. Пока закладчик на улице.", [back("dshop")]
    d = p.get("ds")
    if not d:
        return "🕸 Свой шоп: сайт, свой товар, курьеры, менеджеры, граффити по району.", [[B(f"🌐 Запустить сайт · {fmt(kSiteCost)}$", "dshop:open")], back("dshop")]
    _ds_sim(p)
    stock = sum(d["stock"].values())
    L = [f"🕸 {d['name']} · репутация {int(d['rep'])}/100",
         f"📦 склад {stock} · 🛍 продано {d['sold']} · 🧑‍🚚 курьеров {d['couriers']} · 👔 менеджеров {d['mgrs']} · 🎨 граффити {d['graf']}",
         f"💵 в кассе {fmt(d['cash'])}$ (зарплаты вычитаются)",
         f"🏴 конкурентов в районе: {d.get('comp', 0)}/4 (режут трафик на {int(d.get('comp', 0) * 35)}%)"] + [f"· {x}" for x in d.get("log", [])]
    keys = list(DRUGS)

    def mk(k):
        n, price, *_ = DRUGS[k]
        return [B(f"{ICON.get(k, '💊')} {n} ×10 · {fmt(price * 10 * kWholesale)}$", f"dshop:buy:{k}"), B(f"на складе {d['stock'].get(k, 0)}", "dshop")]
    rows = paged("dshop", keys, page, 5, mk)
    rows.append([B(f"🧑‍🚚 Курьер · {fmt(kCourierHire)}$", "dshop:courier"), B(f"👔 Менеджер · {fmt(kMgrHire)}$", "dshop:mgr")])
    rows.append([B(f"🎨 Граффити · {fmt(kGrafCost * (d['graf'] + 1))}$", "dshop:graf"), B("💵 Забрать кассу", "dshop:collect")])
    rows.append([B(f"⚔ Перебить конкурента · {fmt(R(6000))}$", "dshop:rival"), B("🗑 Закрыть шоп", "dshop:close")])
    rows.append(back("dshop"))
    return "\n".join(L), rows


def act_dshop(p, a, arg):
    if age(p) < kShopMinAge:
        return f"с {kShopMinAge} лет"
    d = p.get("ds")
    if a == "open":
        if d:
            return "уже открыт"
        if p["cash"] < kSiteCost:
            return f"нужно {fmt(kSiteCost)}$"
        p["cash"] -= kSiteCost
        p["ds"] = {"name": random.choice(DSHOPS)[0] + f" {random.randint(10, 99)}", "t": time.time(), "stock": {}, "couriers": 0,
                   "mgrs": 0, "graf": 0, "cash": 0.0, "rep": 10.0, "sold": 0}
        return "сайт запущен. закупай товар, нанимай курьеров, рисуй граффити"
    if not d:
        return ""
    note = _ds_sim(p)
    if a == "buy" and arg in DRUGS:
        cost = DRUGS[arg][1] * 10 * kWholesale
        if p["cash"] < cost:
            return f"нужно {fmt(cost)}$"
        p["cash"] -= cost
        d["stock"][arg] = d["stock"].get(arg, 0) + 10
        return note or f"закупил 10: {DRUGS[arg][0]}"
    if a == "courier":
        if d["couriers"] >= 10 or p["cash"] < kCourierHire:
            return "лимит 10 или нет денег"
        p["cash"] -= kCourierHire
        d["couriers"] += 1
        return note or "курьер нанят: +5 заказов/час"
    if a == "mgr":
        if d["mgrs"] >= 3 or p["cash"] < kMgrHire:
            return "лимит 3 или нет денег"
        p["cash"] -= kMgrHire
        d["mgrs"] += 1
        return note or "менеджер нанят: меньше облав"
    if a == "graf":
        cost = kGrafCost * (d["graf"] + 1)
        if d["graf"] >= 10 or p["cash"] < cost:
            return "лимит 10 или нет денег"
        p["cash"] -= cost
        d["graf"] += 1
        p["skill"]["stealth"] += 0.2
        return note or "новое граффити в районе: трафик +60%"
    if a == "rival":
        if not d.get("comp"):
            return "конкурентов нет"
        if p["cash"] < R(6000):
            return f"нужно {fmt(R(6000))}$"
        p["cash"] -= R(6000)
        if random.random() < 0.7:
            d["comp"] -= 1
            return note or "акция сработала: конкурент ушёл из района"
        d["rep"] = max(0.0, d["rep"] - 5)
        return note or "акция не сработала: деньги ушли, репутация -5"
    if a == "collect":
        if d["cash"] <= 0:
            return note or "в кассе пусто"
        p["cash"] += d["cash"]
        got, d["cash"] = d["cash"], 0.0
        return note or f"забрал {fmt(got)}$"
    if a == "close":
        p["ds"] = None
        return "шоп закрыт"
    return note


# ---- wiring ----
def _inject(sec, row, before_last=True):
    fn = RENDER[sec]

    def r(p, page=0):
        text, rows = fn(p, page)
        rows = list(rows)
        rows.insert(max(0, len(rows) - 1), row)
        return text, rows
    RENDER[sec] = r


_inject("main", [B("🎒 Карман", "pocket"), B("🔥 Курилка", "smoke"), B("🛋 Квартира", "flat")])
_inject("home", [B("🛋 Моя квартира", "flat")])
_inject("shops", [B("🔥 Курилка", "smoke"), B("🎒 Карман", "pocket")])
_inject("work", [B("🎒 Закладчик", "street"), B("🕸 Свой шоп", "dshop")])
_inject("street", [B("🕸 Свой шоп", "dshop")])
PARENT.update({"pocket": "main", "smoke": "shops", "flat": "home", "dshop": "work"})
PARENT_NAME.setdefault("work", "Работа")
RENDER.update({"pocket": r_pocket, "smoke": r_smoke, "flat": r_flat, "dshop": r_dshop})
ACT.update({"main": act_main2, "pocket": act_pocket, "smoke": act_smoke, "flat": act_flat, "dshop": act_dshop})


# ══════════════════════════════════════════════════════════════════════
# [3b] PACK 2: соседи/поломки · день и ночь · вместимость кармана · ломка · конкуренты шопа
# ══════════════════════════════════════════════════════════════════════
kTzOffset = 3                 # часовой пояс игры (UTC+N), 3 = Москва
kPocketBase, kBagSlots, kBagMax = 12, 12, 3
kBagPrice = R(1500)
kMugChance, kMugNightChance = 0.06, 0.12
kNightSurcharge = 0.20
kNightJobs = {"Таксист", "Водитель-доставщик", "Бармен", "Охранник", "Курьер Яндекс.Еда"}
kBreakPerDay = 0.08           # шанс поломки за игровой день (= 1 реальный час)
BREAKS = {"tap": ("Течёт кран", R(1800)), "wire": ("Мигает свет, проводка", R(2500)),
          "heat": ("Не греет батарея", R(3500)), "lock": ("Заедает замок", R(1200))}


# ---- 🕒 day / night ----
_CTX = {"off": 0}   # сдвиг времени игрока в секундах (сон двигает часы)


kTimeScale = 24    # игровое время: 1 игровые сутки = 1 реальный час (как DAY), 1 игровой час = 2.5 реальных минуты


def _gts():
    return time.time() * kTimeScale + kTzOffset * 3600 + _CTX["off"]


def _hour():
    return int(_gts() % 86400 // 3600)


def _clock():
    t = time.gmtime(_gts())
    return f"{t.tm_hour:02d}:{t.tm_min:02d}"


def _night():
    h = _hour()
    return h >= 23 or h < 6


CLOSED = {  # section: (closed_from, closed_to) в часах, 24h-окно через полночь
    "alc": (23, 8), "goods": (23, 6), "sexshop": (23, 6), "vape": (23, 6), "snus": (23, 6),
}
BUY_A = {"cigs": {"buy"}, "snus": {"buy"}, "vape": {"buy"}, "alc": {"drink"}, "hookah": {"bt", "bc"}, "food": {"eat"},
         "drinks": {"buy"}, "goods": {"buy"}, "pharm": {"buy"}, "pshop": {"buy"}, "sexshop": {"buy"}}
NIGHT_PRICE = {"cigs", "food", "drinks", "pharm"}


def _hours_wrap(sec):
    fn = ACT[sec]
    win = CLOSED.get(sec)

    def w(p, a, arg):
        if a not in BUY_A[sec]:
            return fn(p, a, arg)
        h = _hour()
        if win and (h >= win[0] or h < win[1]):
            return f"🔒 закрыто до {win[1]:02d}:00 ({_clock()} сейчас)" + (". алкоголь не продают с 23 до 8" if sec == "alc" else "")
        before = p["cash"]
        msg = fn(p, a, arg)
        spent = before - p["cash"]
        if sec in NIGHT_PRICE and _night() and spent > 0:
            extra = min(p["cash"], spent * kNightSurcharge)
            p["cash"] -= extra
            msg += f"\n🌙 ночная наценка +{int(kNightSurcharge * 100)}%"
        return msg
    return w


for _s in BUY_A:
    ACT[_s] = _hours_wrap(_s)

_work0 = ACT["work"]


def act_work_dn(p, a, arg):
    if a == "do" and p.get("job") is not None and not (6 <= _hour() < 23):
        if JOBS[p["job"]][0] not in kNightJobs:
            return f"🌙 смена закончилась, выходи с 06:00 ({_clock()} сейчас). ночью берут: " + ", ".join(sorted(kNightJobs))
    return _work0(p, a, arg)


ACT["work"] = act_work_dn


# ---- 🎒 pocket capacity ----
def _slots(p):
    n = 1 if p.get("lighter", 0) > 0 else 0
    for k, v in p["inv"].items():
        if v > 0 and _item_name(k):
            n += -(-v // 20) if k.startswith("cig:") else v
    return n


def _cap(p):
    return kPocketBase + kBagSlots * p.get("bag", 0)


def _cap_wrap(fn):
    def w(p, a, arg):
        if a != "buy":
            return fn(p, a, arg)
        inv, cash = dict(p["inv"]), p["cash"]
        msg = fn(p, a, arg)
        if _slots(p) > _cap(p):
            p["inv"], p["cash"] = inv, cash
            return f"🎒 карман полон ({_slots(p)}/{_cap(p)}): выкинь лишнее или возьми рюкзак"
        return msg
    return w


for _s in ("cigs", "subs", "pharm"):
    ACT[_s] = _cap_wrap(ACT[_s])

_street0 = ACT["street"]


def act_street_mug(p, a, arg):
    msg = _street0(p, a, arg)
    if a == "walk" and random.random() < (kMugNightChance if _night() else kMugChance):
        own = [k for k, v in p["inv"].items() if v > 0 and _item_name(k)]
        lost = []
        if own:
            k = random.choice(own)
            lost.append(f"{_item_name(k)} ×{p['inv'].pop(k)}")
        cut = p["cash"] * 0.2
        p["cash"] -= cut
        p["mood"] -= 8
        msg += "\n🥊 гопники в подворотне: отжали " + (", ".join(lost) + " и " if lost else "") + f"{fmt(cut)}$"
    return msg


ACT["street"] = act_street_mug
_pocket_open0, _pocket_act0, _pocket_r0 = act_pocket, ACT["pocket"], RENDER["pocket"]


def act_pocket2(p, a, arg):
    if a == "drop":
        n = p["inv"].pop(arg, 0)
        p["psel"] = ""
        return f"выбросил ×{n}" if n else ""
    if a == "bag":
        cost = kBagPrice * (p.get("bag", 0) + 1)
        if p.get("bag", 0) >= kBagMax:
            return "рюкзаков больше не бывает"
        if p["cash"] < cost:
            return f"нужно {fmt(cost)}$"
        p["cash"] -= cost
        p["bag"] = p.get("bag", 0) + 1
        return f"купил рюкзак: вместимость {_cap(p)}"
    return _pocket_act0(p, a, arg)


def r_pocket2(p, page=0):
    text, rows = _pocket_r0(p, page)
    rows = list(rows)
    sel = p.get("psel")
    if sel and p["inv"].get(sel, 0) > 0:
        rows.insert(1, [B("🗑 Выбросить всё", "pocket:drop:" + sel)])
    else:
        bag = p.get("bag", 0)
        if bag < kBagMax:
            rows.insert(len(rows) - 1, [B(f"🎒 Рюкзак +{kBagSlots} мест · {fmt(kBagPrice * (bag + 1))}$", "pocket:bag")])
    return f"{text}\n📦 места: {_slots(p)}/{_cap(p)} (пачка сигарет = 1 место)", rows


ACT["pocket"], RENDER["pocket"] = act_pocket2, r_pocket2


# ---- 🏠 neighbors, noise, breakdowns ----
def _fl2(p):
    f = _fl(p)
    f.setdefault("noise", 0.0)
    f.setdefault("compl", 0)
    f.setdefault("broken", [])
    f.setdefault("t", time.time())
    return f


_comfort1 = comfort


def comfort(p):
    f = p.get("flat") or {}
    return _comfort1(p) * (1 - 0.1 * len(f.get("broken", [])))


_tick1 = tick


def tick(p):
    _tick1(p)
    now = time.time()
    if p.get("flat") and _flat_ok(p):
        f = _fl2(p)
        days = min(max(0.0, now - f["t"]), CAP) / DAY
        f["t"] = now
        f["noise"] = max(0.0, f["noise"] - 60 * days)
        if len(f["broken"]) < 3 and random.random() < min(0.5, days * kBreakPerDay):
            k = random.choice([k for k in BREAKS if k not in f["broken"]] or [None])
            if k:
                f["broken"].append(k)
                logp(p, f"в квартире сломалось: {BREAKS[k][0]}")
                p["notice"] = f"🔧 в квартире: {BREAKS[k][0]}. вызови мастера в 🛋 Квартире"
    # ломка: уведомление и учёт
    wd = p.setdefault("wd", {})
    for k, v in p["add"].items():
        hot = v > 20 and now - p["lastuse"].get(k, 0) > DAY / 3
        if hot and not wd.get(k):
            wd[k] = 1
            nm = DRUGS[k][0] if k in DRUGS else ADD_INFO.get(k, (k,))[0]
            logp(p, f"началась ломка: {nm}")
            p["notice"] = f"⚠ началась ломка: {nm}. настроение и здоровье падают, пока не примешь или не отболеешь"
        elif not hot:
            wd.pop(k, None)
    if not wd and str(p.get("notice", "")).startswith("⚠"):
        p["notice"] = ""


_flat_act0, _flat_r0 = ACT["flat"], RENDER["flat"]


def act_flat2(p, a, arg):
    if not _flat_ok(p):
        return _flat_act0(p, a, arg)
    f = _fl2(p)
    snap = p["energy"]
    if a == "fix":
        i = int(arg)
        if i >= len(f["broken"]):
            return ""
        k = f["broken"][i]
        name, cost = BREAKS[k]
        if p["cash"] < cost:
            return f"мастер просит {fmt(cost)}$"
        p["cash"] -= cost
        f["broken"].pop(i)
        p["mood"] += 3
        if not f["broken"] and str(p.get("notice", "")).startswith("🔧"):
            p["notice"] = ""
        return f"мастер починил: {name}"
    if a == "treat":
        if p["cash"] < R(500):
            return f"нужно {fmt(R(500))}$"
        p["cash"] -= R(500)
        f["compl"], f["noise"] = 0, max(0.0, f["noise"] - 25)
        p["mood"] += 2
        return "угостил соседей: претензий нет, шум спал"
    msg = _flat_act0(p, a, arg)
    if a == "sleep" and p["energy"] > snap:
        gain = p["energy"] - snap
        p["energy"] += gain * 0.3 if _night() else -gain * 0.3
        msg += " (ночью сон лучше)" if _night() else " (днём спится хуже)"
    if a in ("friends", "date") and not msg.startswith(("нужно", "нет сил", "пока")):
        f["noise"] += 35 if a == "friends" else 10
        if f["noise"] > 60:
            f["compl"] += 1
            fine = min(p["cash"], R(800))
            p["cash"] -= fine
            p["mood"] -= 6
            msg += f"\n🔔 соседи стучат в стену: претензия №{f['compl']}, штраф {fmt(fine)}$"
    return msg


def r_flat2(p, page=0):
    text, rows = _flat_r0(p, page)
    if not _flat_ok(p):
        return text, rows
    f = _fl2(p)
    rows = list(rows)
    extra = [[B(f"🔧 {BREAKS[k][0]} · мастер {fmt(BREAKS[k][1])}$", f"flat:fix:{i}")] for i, k in enumerate(f["broken"])]
    if f["compl"] or f["noise"] > 30:
        extra.append([B(f"🤝 Угостить соседей · {fmt(R(500))}$", "flat:treat")])
    rows[len(rows) - 1:len(rows) - 1] = extra
    return f"{text}\n🔊 шум {int(f['noise'])}/100 · претензий от соседей {f['compl']} · поломок {len(f['broken'])} (каждая -10% комфорта)", rows


ACT["flat"], RENDER["flat"] = act_flat2, r_flat2


# ---- banners: clock + notices, profile addictions ----
_main_r0, _prof_r0 = RENDER["main"], RENDER["profile"]


def r_main2(p, page=0):
    text, rows = _main_r0(p, page)
    head = f"🕒 {_clock()} · {'🌙 ночь' if _night() else '☀ день'} · игровое время"
    if p.get("notice"):
        head += "\n" + p["notice"]
    return head + "\n\n" + text, rows


def r_profile2(p, page=0):
    text, rows = _prof_r0(p, page)
    wd = p.get("wd", {})
    lines = []
    for k, v in p["add"].items():
        if v >= 5:
            nm = DRUGS[k][0] if k in DRUGS else ADD_INFO.get(k, (k,))[0]
            lines.append(f"· {nm}: зависимость {int(v)}%, толерантность {int(tolerance(p, k) * 100)}% " + ("🔴 ломка" if wd.get(k) else "🟢 ок"))
    if lines:
        text += "\n\n🧪 Зависимости:\n" + "\n".join(lines)
    return text, rows


RENDER["main"], RENDER["profile"] = r_main2, r_profile2


