_girl0 = ACT["girl"]


def act_girl2(p, a, arg):
    if a not in ("intim", "touch"):
        return _girl0(p, a, arg)
    try:
        i, _, key = arg.partition("_")
        g = p["girls"][int(i)]
    except (ValueError, IndexError):
        return _girl0(p, a, arg)
    rel0 = g["rel"]
    msg = _girl0(p, a, arg)
    if g["rel"] <= rel0 or not _flat_ok(p):
        return msg
    if a == "touch" and not TOUCH.get(key, (0,) * 8)[7]:
        return msg
    f = _fl2(p)
    f["noise"] += LOUD.get(key, 30) if a == "intim" else 6
    if a == "intim":
        msg += "\n" + random.choice(MOAN).format(n=g["name"].split()[0])
    if f["noise"] > 60:
        f["compl"] += 1
        fine = min(p["cash"], R(800))
        p["cash"] -= fine
        p["mood"] -= 6
        msg += f"\n🔔 соседи стучат в стену: «слышно всё!» претензия №{f['compl']}, штраф {fmt(fine)}$"
    return msg


