# ---- 🎂 profile: change age (раз в час, без дня рождения) ----
def act_profile(p, a, arg):
    sel = p.get("age_sel", age(p))
    if a == "adj":
        p["age_sel"] = max(kAgeMin, min(kAgeMax, sel + int(arg)))
        return ""
    if a == "apply":
        left = cdleft(p, "agechg")
        if left > 0:
            return f"возраст менялся недавно, подожди {int(left // 60) + 1} мин"
        if sel == age(p):
            return "выбран текущий возраст"
        old = age(p)
        p["age_n"] = sel
        p["cd"]["agechg"] = time.time() + kAgeChangeCdSec
        msg = f"возраст: {old} → {sel}"
        if sel >= 18 and p["home"] == "family":
            p["home"] = "hostel"
            msg += ". родительская квартира только до 18: ты в общаге"
        return msg
    return ""


def r_profile3(p, page=0):
    text, rows = r_profile2(p, page)
    sel = p.setdefault("age_sel", age(p))
    left = cdleft(p, "agechg")
    apply_t = f"✅ Применить {sel}" if left <= 0 else f"⏳ через {int(left // 60) + 1} мин"
    rows = list(rows)
    rows[len(rows) - 1:len(rows) - 1] = [
        [B("➖5", "profile:adj:-5"), B("➖1", "profile:adj:-1"), B(f"🎂 {sel}", "profile"), B("➕1", "profile:adj:1"), B("➕5", "profile:adj:5")],
        [B(apply_t, "profile:apply")]]
    return text + f"\n\n🎂 Смена возраста ({kAgeMin}–{kAgeMax}): выбери и примени. Раз в час, день рождения отдельно.", rows


RENDER["profile"] = r_profile3
