# [3e] PACK 5: 💪 СПОРТ — кд по группам мышц, абонемент, форма, протеин, травмы
# ══════════════════════════════════════════════════════════════════════
kGymSubPrice, kGymSubDays, kGymVisit = R(3500), 30, R(300)
kProteinPrice = R(120)
# id: (name, energy, cost, cd_sec, group, str_gain, fit_gain, mood, hunger, needs_gym, injury_risk)
SPORT = {
    "chest": ("🏋 Грудь и руки", 14, 0, 1800, "up", 1.0, 0.8, 3, 5, True, 0.0),
    "back": ("🧗 Спина и плечи", 14, 0, 1800, "bk", 1.0, 0.8, 3, 5, True, 0.0),
    "legs": ("🦵 Ноги", 16, 0, 1800, "lg", 1.1, 0.9, 3, 6, True, 0.0),
    "run": ("🏃 Пробежка", 10, 0, 600, "car", 0.1, 1.2, 6, 5, False, 0.0),
    "swim": ("🏊 Бассейн", 12, R(250), 900, "swm", 0.4, 1.3, 7, 5, False, 0.0),
    "box": ("🥊 Бокс", 16, R(400), 1200, "box", 0.8, 1.0, 6, 6, False, 0.06),
    "yoga": ("🧘 Йога", 7, R(200), 600, "yog", 0.1, 0.5, 9, 2, False, 0.0),
    "home": ("🏠 Тренировка дома", 8, 0, 300, "hom", 0.4, 0.6, 2, 3, False, 0.0),
    "hike": ("🥾 Поход", 18, R(150), 3600, "hik", 0.3, 2.0, 12, 8, False, 0.0),
}


def _gym_left(p):
    return max(0.0, p.get("gymsub", 0) - time.time())


def r_sport(p, page=0):
    fit = p.get("fit", 0.0)
    rows = []
    items = list(SPORT.items())
    for j in range(0, len(items), 2):
        row = []
        for k, v in items[j:j + 2]:
            left = cdleft(p, "sp_" + v[4])
            row.append(B(v[0] + (f" ⏳{int(left // 60) + 1}м" if left > 0 else ""), f"sport:do:{k}"))
        rows.append(row)
    rows.append([B(f"🎫 Абонемент {kGymSubDays}д · {fmt(kGymSubPrice)}$", "sport:sub"), B(f"🥛 Протеин · {fmt(kProteinPrice)}$" + (" ✅" if p.get("prot") else ""), "sport:prot")])
    rows.append(back("sport"))
    sub = f"{int(_gym_left(p) // DAY)}д" if _gym_left(p) > 0 else "нет"
    gymfree = "gym" in p["biz"]
    text = (f"💪 Спорт. Форма {fit:.0f}/100 (ускоряет восстановление до +25%), сила {p['skill']['str']:.1f}. Абонемент: {sub}"
            + (" · твой клуб: зал бесплатно" if gymfree else f". Разовый зал {fmt(kGymVisit)}$.")
            + "\nМышцы восстанавливаются: одну группу можно бить раз в 30 мин, другие в это время свободны. Усталым тренироваться = риск травмы. "
              "Без тренировок форма падает.")
    return text, rows


def act_sport(p, a, arg):
    now = time.time()
    if a == "sub":
        if p["cash"] < kGymSubPrice:
            return f"нужно {fmt(kGymSubPrice)}$"
        p["cash"] -= kGymSubPrice
        p["gymsub"] = max(now, p.get("gymsub", 0)) + kGymSubDays * DAY
        return f"абонемент продлён: {int(_gym_left(p) // DAY)} дн."
    if a == "prot":
        if p.get("prot"):
            return "протеин уже выпит, жди тренировку"
        if p["cash"] < kProteinPrice:
            return f"нужно {fmt(kProteinPrice)}$"
        p["cash"] -= kProteinPrice
        p["prot"] = True
        p["hunger"] = max(0, p["hunger"] - 12)
        return "выпил протеин: следующая тренировка даст +30% силы"
    if a != "do" or arg not in SPORT:
        return ""
    name, en, cost, cd, grp, sg, fg, mood, hun, gym, risk = SPORT[arg]
    left = cdleft(p, "sp_" + grp)
    if left > 0:
        return f"мышцы ещё болят, подожди {int(left // 60) + 1} мин"
    if p["cd"].get("inj", 0) > now:
        return f"травма: до {int((p['cd']['inj'] - now) // 60) + 1} мин только йога и дом"  if grp not in ("yog", "hom") else _sport_go(p, arg, now, cost)
    if gym and "gym" not in p["biz"] and _gym_left(p) <= 0:
        cost = kGymVisit
    if p["cash"] < cost or p["energy"] < en:
        return f"нужно {fmt(cost)}$ и {en} энергии"
    return _sport_go(p, arg, now, cost)


def _sport_go(p, arg, now, cost):
    name, en, _, cd, grp, sg, fg, mood, hun, gym, risk = SPORT[arg]
    if gym and "gym" not in p["biz"] and _gym_left(p) <= 0:
        cost = kGymVisit
    if p["cash"] < cost or p["energy"] < en:
        return f"нужно {fmt(cost)}$ и {en} энергии"
    tired = p["energy"] < en + 15
    p["cash"] -= cost
    p["energy"] -= en
    p["cd"]["sp_" + grp] = now + cd
    boost = 1.3 if p.get("prot") else 1.0
    p["prot"] = False
    fit = p.get("fit", 0.0)
    p["skill"]["str"] += sg * boost
    p["fit"] = min(100.0, fit + fg * (1.0 if fit < 60 else 0.5))
    p["mood"] += mood
    p["hunger"] += hun
    p["hp"] += 1
    p["fit_t"] = now
    msg = f"{name}: сила +{sg * boost:.1f}, форма +{fg:.1f}"
    if (tired and random.random() < 0.15) or (risk and random.random() < risk):
        p["hp"] -= 10
        p["cd"]["inj"] = now + 1200
        msg += "\n🩹 травма: -10 здоровья, 20 мин только йога и дом"
    return msg


_comfort2 = comfort


def comfort(p):
    return _comfort2(p) * (1 + p.get("fit", 0.0) / 400)


_tick3 = tick


def tick(p):
    _tick3(p)
    now = time.time()
    t = p.setdefault("fit_t", now)
    days = min(max(0.0, now - t), CAP) / DAY
    if days > 1 and p.get("fit", 0) > 0:
        p["fit"] = max(0.0, p["fit"] - 0.3 * (days - 1))
        p["fit_t"] = now - DAY


_self1 = ACT["self"]


def act_self_nogym(p, a, arg):
    if a == "gym":
        return "зал теперь в 💪 Спорт: там кд, абонемент и другие тренировки"
    return _self1(p, a, arg)


_self_r0 = RENDER["self"]


def r_self2(p, page=0):
    text, rows = _self_r0(p, page)
    rows = [list(r) for r in rows]
    rows[0] = [b if b[1] != "self:gym" else B("💪 Спорт", "sport") for b in rows[0]]
    return text, rows


ACT["self"], RENDER["self"] = act_self_nogym, r_self2
_inject("main", [B("💪 Спорт", "sport")])
PARENT.update({"sport": "self"})
PARENT_NAME.setdefault("self", "Быт")
