# [3f] PACK 6: обнулить профиль (новая жизнь с нуля, регистрация заново)
# ══════════════════════════════════════════════════════════════════════
kResetConfirmSec = 30         # сколько секунд живёт кнопка подтверждения
_prof_act0, _prof_r1 = ACT["profile"], RENDER["profile"]


def act_profile_reset(p, a, arg):
    if a == "rst":
        p["rst_arm"] = time.time() + kResetConfirmSec
        return "точно обнулить? всё пропадёт: деньги, жильё, девушки, шоп, прогресс"
    if a == "rstno":
        p.pop("rst_arm", None)
        return "отменил"
    if a == "rstok":
        if p.get("rst_arm", 0) < time.time():
            return "подтверждение истекло, нажми «Обнулить профиль» ещё раз"
        uid, name = p["uid"], p["name"]
        fresh = new_player(uid, name)
        fresh.update(reg="city", named=False)
        p.clear()
        p.update(fresh)
        return "профиль обнулён: заполняй заново"
    return _prof_act0(p, a, arg)


def r_profile4(p, page=0):
    text, rows = _prof_r1(p, page)
    rows = list(rows)
    if p.get("rst_arm", 0) > time.time():
        extra = [[B("✅ Да, обнулить всё", "profile:rstok"), B("↩ Отмена", "profile:rstno")]]
        text += "\n\n⚠ Обнуление необратимо. Подтверди в течение 30 сек."
    else:
        extra = [[B("♻ Обнулить профиль", "profile:rst")]]
    rows[len(rows) - 1:len(rows) - 1] = extra
    return text, rows


ACT["profile"], RENDER["profile"] = act_profile_reset, r_profile4


