# [3g] PACK 7: сон двигает время · больше работ (14+ подработки и 18+ с нормальной зп)
# ══════════════════════════════════════════════════════════════════════
kNapHours = 2                 # дневной сон сдвигает время на N часов
kWakeHour = 7                 # ночной сон будит около этого часа
_gp0 = get_player


def get_player(user):
    p = _gp0(user)
    _CTX["off"] = p.get("toff", 0)
    return p


def _skip_time(p):
    h = _hour()
    add = (((kWakeHour - h) % 24) or 24) if (h >= 20 or h < 6) else kNapHours
    p["toff"] = p.get("toff", 0) + add * 3600 + random.randint(0, 50) * 60
    _CTX["off"] = p["toff"]
    p["hunger"] += add * 1.5
    return add


def _sleep_time(fn):
    def w(p, a, arg):
        if a != "sleep":
            return fn(p, a, arg)
        e0 = p["energy"]
        msg = fn(p, a, arg)
        if p["energy"] > e0:
            add = _skip_time(p)
            msg += f"\n🕒 проснулся в {_clock()} (прошло ~{add} ч)"
        return msg
    return w


ACT["flat"] = _sleep_time(ACT["flat"])
ACT["self"] = _sleep_time(ACT["self"])

# ---- jobs ----
