def _job_min_age(i):
    if i < 0 or i >= len(JOBS):
        return 18
    n = JOBS[i][0]
    return 14 if n in TEEN_JOBS else 18


_work1, _work_r1 = ACT["work"], RENDER["work"]


def act_work_age(p, a, arg):
    if a == "pick":
        try:
            i = int(arg)
        except ValueError:
            return ""
        if 0 <= i < len(JOBS) and age(p) < _job_min_age(i):
            return f"🔞 {JOBS[i][0]}: с {_job_min_age(i)} лет"
    if a == "do" and p.get("job") is not None and age(p) < _job_min_age(p["job"]):
        return f"{JOBS[p['job']][0]}: с {_job_min_age(p['job'])} лет, выбери подработку попроще"
    return _work1(p, a, arg)


def r_work_age(p, page=0):
    text, rows = _work_r1(p, page)
    out = []
    for r in rows:
        r2 = []
        for t, d in r:
            if d.startswith("work:pick:"):
                i = int(d.split(":")[2])
                m = _job_min_age(i)
                if m > age(p):
                    t = "🔒" + t[1:]
                if m >= 18:
                    t += " · 18+"
            r2.append((t, d))
        out.append(r2)
    return text + f"\nРабот: {len(JOBS)}. 14+: подработки, 18+: нормальные зарплаты (вахты, стройка, айти, финансы).", out


ACT["work"], RENDER["work"] = act_work_age, r_work_age


