# [3h] PACK 8: игровое время · зарядка телефона из квартиры · SIM: пополнение в салоне
# ══════════════════════════════════════════════════════════════════════
kTopupSteps = (300, 1000)     # ₽, кнопки пополнения SIM в салоне
_pshop2, _pshop_r2 = ACT["pshop"], RENDER["pshop"]


def act_pshop_top(p, a, arg):
    if a != "top":
        return _pshop2(p, a, arg)
    i, _, amt = arg.partition("_")
    i, amt = int(i), R(int(amt))
    if i >= len(p["sims"]):
        return "такой SIM нет"
    if p["cash"] < amt:
        return f"нужно {fmt(amt)}$"
    p["cash"] -= amt
    s = p["sims"][i]
    s["bal"] += amt
    s["off"] = False
    return f"баланс {TAR[s['tar']][0]} {s['num']}: +{fmt(amt)}$ (теперь {fmt(s['bal'])}$)"


def r_pshop_top(p, page=0):
    text, rows = _pshop_r2(p, page)
    if p.get("ptab") == "sim":
        rows = list(rows)
        extra = []
        for i, s in enumerate(p["sims"][:4]):
            extra.append([B(f"💳 {TAR[s['tar']][0]} {s['num']} · {fmt(s['bal'])}$", "pshop")] +
                         [B(f"+{n}₽", f"pshop:top:{i}_{n}") for n in kTopupSteps])
        rows[len(rows) - 1:len(rows) - 1] = extra
        text += "\n\nПополнение баланса твоих SIM: кнопки внизу." if p["sims"] else "\n\nУ тебя пока нет SIM: купи любую выше."
    return text, rows


ACT["pshop"], RENDER["pshop"] = act_pshop_top, r_pshop_top

