def act_flat_chg(p, a, arg):
    if a == "charge":
        if not _flat_ok(p):
            return "ты на улице: нужен дом или повербанк"
        return ACT["phone"](p, "chg", "")
    return _flat_act3(p, a, arg)


def r_flat_chg(p, page=0):
    text, rows = _flat_r3(p, page)
    if not _flat_ok(p):
        return text, rows
    ph = p.get("ph")
    label = "🔌 Зарядить телефон"
    if ph:
        label += f" ({int(ph['bat'])}%" + (", идёт зарядка)" if ph.get("ct") else ")")
    rows = list(rows)
    rows.insert(len(rows) - 1, [B(label, "flat:charge")])
    return text, rows


