# ───────── близость: секс, куннилингус, дети (текст без графики) ─────────
INTIM.update({
    "sex": ("Секс", 50, 14, 24, 1.2, 5, 0),
    "oral": ("Куннилингус", 45, 10, 20, 0.35, 4, 0),
})
LOUD.update({"sex": 45, "oral": 35})
NO_CONCEIVE = {"oral"}
SEX_TXT = {
    "sex": ["секс с {n}: без спешки, потом долго лежали молча", "{n} и ты не тратили время на разговоры. оба довольны",
            "секс с {n}: всё как надо"],
    "oral": ["куннилингус: {n} в полном восторге, просит повторить", "ты не торопился, {n} осталась очень довольна"],
}


def intimacy(p, g, key, now):
    if key not in INTIM:
        return ""
    if age(p) < 18 or g.get("age", 18) < 18:
        return "до 18 нельзя"
    name, min_rel, en, mood, risk, gain, cost = INTIM[key]
    if key == "oral" and g["g"] != "f":
        return "этот вариант только для девушек"
    if g["rel"] < min_rel:
        return f"рано, отношения < {min_rel}"
    if p["energy"] < en:
        return "нет сил"
    if p["cash"] < cost:
        return f"нужно {cost}$"
    p["cash"] -= cost
    p["energy"] -= en
    p["mood"] += mood
    p["hp"] += 5
    g["rel"] += gain
    first = g["name"].split()[0]
    txt = random.choice(SEX_TXT[key]).format(n=first) if key in SEX_TXT else f"{name} с {g['name']}. утром всё хорошо."
    noconc = key in NO_CONCEIVE
    condom = (not noconc) and p["inv"].get("good:protect", 0) > 0
    if condom:
        p["inv"]["good:protect"] -= 1
    else:
        for k, pr in STI_RISK:
            if random.random() < pr * risk:
                catch(p, k)
    pill = (not noconc) and (not condom) and p["inv"].get("good:pill", 0) > 0
    if pill:
        p["inv"]["good:pill"] -= 1
    conceive = 0.0 if noconc else min(0.5, (0.03 if condom else 0.04 if pill else 0.12) * risk)
    if (g["g"] == "f" and p["pref"] != "m" and random.random() < conceive
            and not any(b.get("m") == g["name"] for b in p["pending"])
            and len(p["kids"]) + len(p["pending"]) < kKidsMax):
        p["pending"].append({"t": now + kPregSec, "m": g["name"]})
        txt += f" {g['name']} ждёт ребёнка."
    return txt


def baby(p, g, now):
    """осознанно завести ребёнка: девушка = беременность, иначе усыновление"""
    if age(p) < 18 or g.get("age", 18) < 18:
        return "до 18 нельзя"
    if g["rel"] < kBabyMinRel:
        return f"рано, отношения < {kBabyMinRel}"
    if p["home"] == "street":
        return "ребёнку нужен дом"
    if len(p["kids"]) + len(p["pending"]) >= kKidsMax:
        return f"детей уже {kKidsMax}, больше не потянуть"
    if any(b.get("m") == g["name"] for b in p["pending"]):
        return f"{g['name']} уже ждёт ребёнка"
    natural = g["g"] == "f" and p["pref"] != "m"
    cost, en = (kBabyCost, kBabyEnergy) if natural else (kAdoptCost, 10)
    if p["cash"] < cost or p["energy"] < en:
        return f"нужно {fmt(cost)}$ и {en} энергии"
    p["cash"] -= cost
    p["energy"] -= en
    if not natural:
        kid = {"name": random.choice(KID_NAMES), "born": now - YEAR * random.randint(1, 5), "bond": 40, "sick": False}
        p["kids"].append(kid)
        p["mood"] += 20
        g["rel"] += 5
        return f"усыновили: {kid['name']}. теперь вы семья"
    for k, pr in STI_RISK:
        if random.random() < pr * 0.6:
            catch(p, k)
    g["rel"] += 3
    chance = kBabyChance * (0.5 if p["drunk"] > 50 else 1.0)
    if random.random() < chance:
        p["pending"].append({"t": now + kPregSec, "m": g["name"]})
        p["mood"] += 15
        return f"{g['name']} ждёт ребёнка. роды через ~{int(kPregSec // 60)} мин"
    p["mood"] += 4
    return "в этот раз не вышло, пробуйте ещё"


_girl_a0, _girl_r0 = ACT["girl"], RENDER["girl"]


def act_girl_v3(p, a, arg):
    if a != "baby":
        return _girl_a0(p, a, arg)
    i = int(arg.split("_")[0])
    if i >= len(p["girls"]):
        return "такого контакта нет"
    return baby(p, p["girls"][i], time.time())


def r_girl_v2(p, page=0):
    text, rows = _girl_r0(p, page)
    if page >= len(p["girls"]):
        return text, rows
    g = p["girls"][page]
    rows = [list(r) for r in rows]
    if g["g"] != "f":
        rows = [[b for b in r if not b[1].endswith("_oral")] for r in rows]
        rows = [r for r in rows if r]
    rows.insert(max(0, len(rows) - 1), [B(f"👶 Завести ребёнка · {fmt(kBabyCost if g['g'] == 'f' else kAdoptCost)}$", f"girl:baby:{page}")])
    return text, rows


ACT["girl"], RENDER["girl"] = act_girl_v3, r_girl_v2

# ───────── шопы игроков: домен, каталог, заказы, честно / кинуть ─────────
def _ds_init(d):
    d.setdefault("domain", "")
    d.setdefault("mk", kMkDefault)
    d.setdefault("auto", False)
    d.setdefault("ok", 0)
    d.setdefault("scam", 0)
    return d


def _dom(own):
    return (own.get("ds") or {}).get("domain") or "шоп"


def _o_fetch(oid, shop=None):
    r = db.execute("SELECT id,shop,buyer,bname,drug,price,ts FROM dorders WHERE id=? AND st='new'", (oid,)).fetchone()
    if not r or (shop is not None and r[1] != shop):
        return None
    return dict(id=r[0], shop=r[1], buyer=r[2], bname=r[3], drug=r[4], price=r[5], ts=r[6])


def _o_rows(shop):
    return db.execute("SELECT id,buyer,bname,drug,price,ts FROM dorders WHERE shop=? AND st='new' ORDER BY ts", (shop,)).fetchall()


def _o_set(oid, st):
    db.execute("UPDATE dorders SET st=? WHERE id=?", (st, oid))
    db.commit()


def order_send(o, live):
    own, buy = _pl(o["shop"], live), _pl(o["buyer"], live)
    _o_set(o["id"], "sent")
    dom = _dom(own) if own else "шоп"
    if own and own.get("ds"):
        d = own["ds"]
        d["cash"] += o["price"]
        d["sold"] += 1
        d["ok"] = d.get("ok", 0) + 1
        d["rep"] = min(100.0, d["rep"] + 1.5)
    if buy:
        city = CITIES.get(buy.get("city"), CITIES["samara"])[0]
        buy.setdefault("orders", []).append(
            {"d": o["drug"], "spot": f"{city}: {random.choice(SP_AREA)}, у места «{random.choice(SP_MARK)}»", "t": time.time()})
        logp(buy, f"{dom}: закладка отправлена, адрес в Улица → Клады")
    _put(own, live)
    _put(buy, live)
    _note(o["buyer"], f"📦 {dom}: «{DRUGS[o['drug']][0]}» отправлен. Адрес: Улица → Клады")


def order_scam(o, live):
    own, buy = _pl(o["shop"], live), _pl(o["buyer"], live)
    _o_set(o["id"], "scam")
    dom = _dom(own) if own else "шоп"
    if own and own.get("ds"):
        d = own["ds"]
        d["cash"] += o["price"]
        d["stock"][o["drug"]] = d["stock"].get(o["drug"], 0) + 1
        d["scam"] = d.get("scam", 0) + 1
        d["rep"] = max(0.0, d["rep"] - 12)
    if buy:
        buy["mood"] = buy.get("mood", 50) - 8
        logp(buy, f"{dom} кинул: деньги ушли, закладки нет")
    _put(own, live)
    _put(buy, live)
    _note(o["buyer"], f"🃏 {dom} кинул тебя на {fmt(o['price'])}$. Закладки не будет")


def order_refund(o, live, reason, rep_pen=0.0):
    own, buy = _pl(o["shop"], live), _pl(o["buyer"], live)
    _o_set(o["id"], "refund")
    dom = _dom(own) if own else "шоп"
    if own and own.get("ds"):
        d = own["ds"]
        d["stock"][o["drug"]] = d["stock"].get(o["drug"], 0) + 1
        d["rep"] = max(0.0, d["rep"] - rep_pen)
    if buy:
        buy["cash"] += o["price"]
        logp(buy, f"{dom}: возврат {fmt(o['price'])}$ ({reason})")
    _put(own, live)
    _put(buy, live)
    _note(o["buyer"], f"↩ {dom}: возврат {fmt(o['price'])}$ ({reason})")


def orders_sweep(live=None):
    now = time.time()
    for (oid,) in db.execute("SELECT id FROM dorders WHERE st='new' AND ts<?", (now - kOrderTtlSec,)).fetchall():
        o = _o_fetch(oid)
        if o:
            order_refund(o, live, "продавец не ответил", 4.0)
    for (uid,) in db.execute("SELECT DISTINCT shop FROM dorders WHERE st='new'").fetchall():
        own = _pl(uid, live)
        if not own or not own.get("ds"):
            for (oid,) in db.execute("SELECT id FROM dorders WHERE shop=? AND st='new'", (uid,)).fetchall():
                o = _o_fetch(oid)
                if o:
                    order_refund(o, live, "шоп закрыт", 0.0)
    for (uid,) in db.execute("SELECT uid FROM pubshops").fetchall():
        own = _pl(uid, live)
        if not own or not own.get("ds"):
            db.execute("DELETE FROM pubshops WHERE uid=?", (uid,))
    db.commit()


def shop_teardown(uid, live, reason):
    for (oid,) in db.execute("SELECT id FROM dorders WHERE shop=? AND st='new'", (uid,)).fetchall():
        o = _o_fetch(oid)
        if o:
            order_refund(o, live, reason, 0.0)
    db.execute("DELETE FROM pubshops WHERE uid=?", (uid,))
    db.commit()


def pub_shops():
    out = []
    for uid, dom in db.execute("SELECT uid, domain FROM pubshops").fetchall():
        o = load_raw(uid)
        if o and o.get("ds") and o["ds"].get("domain") == dom:
            _ds_init(o["ds"])
            out.append((uid, o))
    out.sort(key=lambda t: -t[1]["ds"]["rep"])
    return out


def _open_cnt(p):
    n = db.execute("SELECT COUNT(*) FROM dorders WHERE buyer=? AND st='new'", (p["uid"],)).fetchone()[0]
    return len(p.get("orders", [])) + n


def domain_set(p, raw):
    d = p.get("ds")
    if not d:
        p["await"] = ""
        return "сначала запусти шоп"
    if p.get("ds_ban"):
        p["await"] = ""
        return "публичный шоп тебе закрыт администрацией"
    _ds_init(d)
    dom = raw.strip().lower()
    if not DOMAIN_RE.match(dom):
        return "не подходит. формат: название.зона (a-z, цифры, дефис, 3–20 знаков). зоны: " + ", ".join("." + z for z in DOMAIN_ZONES)
    if dom in {x[1] for x in DSHOPS}:
        return "этот адрес занят"
    if dom == d["domain"]:
        p["await"] = ""
        return "это и так твой домен"
    row = db.execute("SELECT uid FROM pubshops WHERE domain=?", (dom,)).fetchone()
    if row and row[0] != p["uid"]:
        return "домен занят, придумай другой"
    cost = kDomainChange if d["domain"] else 0
    if p["cash"] < cost:
        return f"смена домена стоит {fmt(cost)}$"
    p["cash"] -= cost
    db.execute("INSERT OR REPLACE INTO pubshops(uid,domain) VALUES(?,?)", (p["uid"], dom))
    db.commit()
    d["domain"] = dom
    p["await"] = ""
    return f"домен {dom} твой. шоп виден всем в каталоге браузера"


# ---- владелец: надстройка над 🕸 Свой шоп ----
_dshop_r0, _dshop_a0 = RENDER["dshop"], ACT["dshop"]


def r_dshop_pub(p, page=0):
    text, rows = _dshop_r0(p, page)
    d = p.get("ds")
    if not d or age(p) < kShopMinAge:
        return text, rows
    _ds_init(d)
    rows = list(rows)
    rows[len(rows) - 1:len(rows) - 1] = [
        [B(("🌐 " + d["domain"]) if d["domain"] else "🌐 Задать домен", "dshop:domain")],
        [B(f"💲 Наценка ×{d['mk']:.1f}", "dshop"), B("➖", "dshop:mk:-1"), B("➕", "dshop:mk:1"),
         B("🤖 Авто: " + ("вкл" if d["auto"] else "выкл"), "dshop:auto")],
        [B(f"📨 Заказы ({len(_o_rows(p['uid']))})", "dorders")],
    ]
    info = (f"\n🌐 {d['domain']} · виден всем в каталоге · честных {d['ok']} · кинул {d['scam']}" if d["domain"]
            else "\n🌐 Домена нет: шоп не виден в каталоге")
    return text + info, rows


def act_dshop_pub(p, a, arg):
    if age(p) < kShopMinAge:
        return _dshop_a0(p, a, arg)
    d = p.get("ds")
    if a == "close" and d:
        shop_teardown(p["uid"], p, "шоп закрыт")
        p["await"] = ""
    if not d:
        r = _dshop_a0(p, a, arg)
        if p.get("ds"):
            _ds_init(p["ds"])
        return r
    _ds_init(d)
    if a == "domain":
        if p.get("ds_ban"):
            return "публичный шоп тебе закрыт администрацией"
        p["await"] = "domain"
        return ("напиши домен одним сообщением. формат: название.зона, a-z, цифры, дефис, 3–20 знаков. зоны: "
                + ", ".join("." + z for z in DOMAIN_ZONES) + ". пример: tihiy-sad.shop")
    if a == "mk":
        d["mk"] = round(max(kMkMin, min(kMkMax, d["mk"] + int(arg) * kMkStep)), 1)
        return ""
    if a == "auto":
        d["auto"] = not d["auto"]
        return ("авто включено: заказы уходят сразу, пока есть склад" if d["auto"]
                else "авто выключено: сам решаешь, отправить или кинуть")
    return _dshop_a0(p, a, arg)


# ---- владелец: заказы ----
def r_dorders(p, page=0):
    d = p.get("ds")
    if not d or age(p) < kShopMinAge:
        return "🕸 Сначала запусти шоп.", [back("dorders")]
    orders_sweep(p)
    now = time.time()
    rows_db = _o_rows(p["uid"])
    L = [f"📨 Заказы · новых {len(rows_db)}", f"✅ честных {d.get('ok', 0)} · 🃏 кинул {d.get('scam', 0)} · ⭐ {int(d['rep'])}/100",
         f"Отправить закладку, кинуть (деньги тебе, репутация -12) или вернуть. Без ответа {kOrderTtlSec // 60} мин деньги вернутся сами."]
    rows = []
    for oid, buyer, bname, drug, price, ts in rows_db[:6]:
        left = max(0, int((kOrderTtlSec - (now - ts)) // 60))
        L.append(f"· #{oid} {bname[:12]} · {DRUGS[drug][0]} · {fmt(price)}$ · ещё {left} мин")
        rows.append([B(f"📦 #{oid}", f"dorders:send:{oid}"), B("🃏 кинуть", f"dorders:scam:{oid}"), B("↩ вернуть", f"dorders:ref:{oid}")])
    rows.append(back("dorders"))
    return "\n".join(L), rows


def act_dorders(p, a, arg):
    if not p.get("ds") or age(p) < kShopMinAge:
        return "нет шопа"
    o = _o_fetch(int(arg), p["uid"])
    if not o:
        return "заказ уже закрыт"
    if a == "send":
        order_send(o, p)
        return f"закладка ушла, в кассу +{fmt(o['price'])}$"
    if a == "scam":
        order_scam(o, p)
        return f"кинул {o['bname'][:12]}: +{fmt(o['price'])}$ в кассу, репутация -12"
    if a == "ref":
        order_refund(o, p, "продавец вернул деньги", 0.5)
        return "деньги возвращены покупателю"
    return ""


# ---- покупатель: каталог всех публичных шопов ----
def r_dmarket(p, page=0):
    ph_refresh(p)
    if age(p) < 18:
        return "🔒 Откроется с 18 лет.", [back("dmarket")]
    err = net_state(p)
    if err:
        return f"🌐 {err}.", [[B("📱 Телефон", "phone")]]
    orders_sweep(p)
    sel = p.get("mk_sel", 0)
    if sel:
        o = next((x for uid, x in pub_shops() if uid == sel), None)
        if o:
            d = o["ds"]
            L = [f"🕶 {d['domain']} · ⭐ {int(d['rep'])}/100", f"✅ честных {d['ok']} · 🃏 кинул {d['scam']}",
                 f"Деньги уходят продавцу сразу. Заклад или кидалово решает он; без ответа {kOrderTtlSec // 60} мин будет возврат."]
            items = [k for k in DRUGS if d["stock"].get(k, 0) > 0]
            rows = paged("dmarket", items, page, 6, lambda k: [B(
                f"{ICON.get(k, '💊')} {DRUGS[k][0]} · {fmt(DRUGS[k][1] * d['mk'])}$ · {d['stock'][k]} шт", f"dmarket:buy:{sel}_{k}")])
            if not items:
                L.append("Склад пуст.")
            rows.append([B("🔙 Каталог", "dmarket:list")])
            return "\n".join(L), rows
        p["mk_sel"] = 0
    shops = pub_shops()
    rows = paged("dmarket", shops, page, 5, lambda t: [B(
        f"🕶 {t[1]['ds']['domain']} · ⭐{int(t[1]['ds']['rep'])} · кинул {t[1]['ds']['scam']}", f"dmarket:go:{t[0]}")])
    rows.append(back("dmarket"))
    return (f"🕸 Шопы игроков: {len(shops)}. Продавец сам решает, отправить закладку или кинуть: смотри репутацию и сколько раз кидал. "
            f"Твоих открытых заказов: {_open_cnt(p)}/{kMaxOpenOrders}."), rows


def act_dmarket(p, a, arg):
    if a == "list":
        p["mk_sel"] = 0
        return ""
    if a == "go":
        p["mk_sel"] = int(arg)
        return ""
    if a != "buy":
        return ""
    ph_refresh(p)
    if age(p) < 18:
        return "до 18 нельзя"
    err = net_state(p)
    if err:
        return err
    uid_s, _, dk = arg.partition("_")
    uid = int(uid_s)
    if dk not in DRUGS:
        return ""
    if uid == p["uid"]:
        return "в свой шоп не покупают"
    o = load_raw(uid)
    row = db.execute("SELECT 1 FROM pubshops WHERE uid=?", (uid,)).fetchone()
    if not o or not o.get("ds") or not row or not o["ds"].get("domain"):
        p["mk_sel"] = 0
        return "шоп закрылся"
    d = _ds_init(o["ds"])
    if d["stock"].get(dk, 0) < 1:
        return "уже разобрали"
    if _open_cnt(p) >= kMaxOpenOrders:
        return f"у тебя уже {kMaxOpenOrders} необработанных заказа/клада"
    price = DRUGS[dk][1] * d["mk"]
    if p["cash"] < price:
        return f"нужно {fmt(price)}$"
    ph_use(p)
    p["cash"] -= price
    d["stock"][dk] -= 1
    save(o)
    cur = db.execute("INSERT INTO dorders(shop,buyer,bname,drug,price,ts,st) VALUES(?,?,?,?,?,?,'new')",
                     (uid, p["uid"], p["name"], dk, price, time.time()))
    db.commit()
    oid = cur.lastrowid
    if d.get("auto"):
        order_send(_o_fetch(oid), p)
        return f"оплачено: {DRUGS[dk][0]}. адрес пришёл, смотри Улица → Клады"
    _note(uid, f"📨 {d['domain']}: новый заказ #{oid}, {DRUGS[dk][0]} за {fmt(price)}$ от {p['name'][:12]}. Отправить или кинуть: Свой шоп → Заказы")
    return f"оплачено: {DRUGS[dk][0]}. ждём продавца до {kOrderTtlSec // 60} мин, иначе вернём деньги"


_web_r0 = RENDER["web"]


def r_web_pub(p, page=0):
    text, rows = _web_r0(p, page)
    if not p.get("ws") and age(p) >= 18 and not net_state(p):
        rows = list(rows)
        rows.insert(max(0, len(rows) - 1), [B("🕸 Шопы игроков", "dmarket:list")])
    return text, rows


# ───────── охрана: чем выше уровень, тем тяжелее тебя ограбить ─────────
def guard_upkeep(p):
    L = sec_lvl(p)
    now = time.time()
    t = p.setdefault("sec_t", now)
    p["sec_t"] = now
    if not L:
        return
    days = min(max(0.0, now - t), CAP) / DAY
    cost = GUARD[L][2] * days
    if p["cash"] >= cost:
        p["cash"] -= cost
    else:
        p["sec"] = L - 1
        logp(p, f"охрана «{GUARD[L][0]}» ушла: нечем платить, уровень {L - 1}")


_tick_g0 = tick


def tick(p):
    _tick_g0(p)
    guard_upkeep(p)


def r_guard(p, page=0):
    L = sec_lvl(p)
    L_ = [f"🛡 Охрана · уровень {L}/5: {GUARD[L][0]}",
          f"Шанс, что тебя ограбят: ×{SEC_BLOCK[L]:.2f}, добыча грабителя ×{SEC_LOOT[L]:.2f}. Содержание {fmt(GUARD[L][2])}$/день.",
          "Действует на ограбления игроками, гопников на улице и «тебя обчистили». Провал грабителя против охраны 2+ уровня стоит ему здоровья и штрафа в твою пользу. "
          "Нечем платить за содержание: охрана уходит на уровень ниже."]
    rows = []
    if L < 5:
        n = GUARD[L + 1]
        rows.append([B(f"⬆ Ур.{L + 1}: {n[0]} · {fmt(n[1])}$ + {fmt(n[2])}$/день", "guard:up")])
    if L > 0:
        rows.append([B("⬇ Снять уровень", "guard:down")])
    rows.append(back("guard"))
    return "\n".join(L_), rows


def act_guard(p, a, arg):
    L = sec_lvl(p)
    if a == "up":
        if L >= 5:
            return "выше некуда"
        price = GUARD[L + 1][1]
        if p["cash"] < price:
            return f"нужно {fmt(price)}$"
        p["cash"] -= price
        p["sec"] = L + 1
        p["sec_t"] = time.time()
        return f"охрана: {GUARD[L + 1][0]}"
    if a == "down" and L > 0:
        p["sec"] = L - 1
        return f"охрана снижена до уровня {L - 1} (деньги не возвращаются)"
    return ""


_social_a0, _social_r0 = ACT["social"], RENDER["social"]


def act_social_guard(p, a, arg):
    if a != "rob":
        return _social_a0(p, a, arg)
    uid = int(arg)
    v = load_raw(uid)
    if not v or uid == p["uid"]:
        return "цель не найдена"
    if p["energy"] < 15:
        return "нужно 15 энергии"
    p["energy"] -= 15
    L = sec_lvl(v)
    base = max(10, min(80, 40 + p["skill"]["stealth"] * 0.4 + p["skill"]["crime"] * 0.2 - v["skill"].get("str", 0) * 0.3 - p["heat"] * 0.2))
    chance = max(2.0, base * SEC_BLOCK[L])
    p["heat"] += 25
    if random.random() * 100 < chance and v["cash"] > 20:
        x = min(v["cash"], v["cash"] * random.uniform(0.05, 0.12)) * SEC_LOOT[L]
        v["cash"] -= x
        p["cash"] += x
        v["log"] = (v.get("log", []) + [f"тебя ограбил {p['name']}: -{fmt(x)}$"])[-5:]
        save(v)
        _note(uid, f"🔪 тебя ограбил {p['name'][:12]}: -{fmt(x)}$")
        p["skill"]["crime"] += 1
        return f"обчистил {v['name']} на {fmt(x)}$" + (f" (охрана ур.{L}: шанс был {int(chance)}%)" if L else "")
    p["hp"] -= 10 + 6 * L
    extra = ""
    if L >= 2:
        fine = min(p["cash"], R(600) * L)
        p["cash"] -= fine
        v["cash"] += fine
        extra = f", штраф {fmt(fine)}$ ушёл охране"
    v["log"] = (v.get("log", []) + [f"охрана остановила {p['name']}: попытка ограбления"])[-5:]
    save(v)
    _note(uid, f"🛡 охрана остановила {p['name'][:12]}: попытка тебя ограбить")
    p["jail"] = time.time() + 600
    p["jailed"] += 1
    return f"{v['name']} дал отпор{' (охрана ур.' + str(L) + ')' if L else ''}, ты в обезьяннике на 10 мин{extra}"


def r_social_guard(p, page=0):
    text, rows = _social_r0(p, page)
    out = []
    for r in rows:
        nr = []
        for t, d in r:
            if d.startswith("social:rob:"):
                try:
                    L = sec_lvl(load_raw(int(d.split(":")[2])) or {})
                except ValueError:
                    L = 0
                if L:
                    t += f" 🛡{L}"
            nr.append((t, d))
        out.append(nr)
    return text, out


_street_g0 = ACT["street"]


def act_street_guard(p, a, arg):
    global kMugChance, kMugNightChance
    m = SEC_BLOCK[sec_lvl(p)]
    old = (kMugChance, kMugNightChance)
    kMugChance, kMugNightChance = old[0] * m, old[1] * m
    try:
        return _street_g0(p, a, arg)
    finally:
        kMugChance, kMugNightChance = old


_re_g0 = rand_event


def rand_event(p):
    L = sec_lvl(p)
    if not L:
        return _re_g0(p)
    c0, m0 = p["cash"], p["mood"]
    last0 = p["log"][-1] if p["log"] else None
    _re_g0(p)
    if (p["cash"] < c0 and p["log"] and p["log"][-1] != last0 and p["log"][-1].startswith("тебя обчистили")
            and random.random() > SEC_BLOCK[L]):
        p["cash"], p["mood"] = c0, m0
        p["log"][-1] = "🛡 охрана отбила попытку тебя обчистить"


# ───────── админка: только ADMINS ─────────
def _all_players():
    return [json.loads(r[0]) for r in db.execute("SELECT data FROM players")]


def r_admin(p, page=0):
    if not is_admin(p):
        return "нет доступа", [back("admin")]
    allp = _all_players()
    banned = sum(1 for q in allp if q.get("ban"))
    n_shops = db.execute("SELECT COUNT(*) FROM pubshops").fetchone()[0]
    by_st = dict(db.execute("SELECT st, COUNT(*) FROM dorders GROUP BY st").fetchall())
    money = sum(q.get("cash", 0) + q.get("bank", 0) for q in allp)
    L = ["🛠 Админка", f"👥 игроков {len(allp)} (бан {banned})", f"💵 в обороте {fmt(money)}$",
         f"🕸 публичных шопов {n_shops} · заказов ждут {by_st.get('new', 0)}",
         f"📦 отправлено {by_st.get('sent', 0)} · 🃏 кинули {by_st.get('scam', 0)}"]
    rows = [[B("👥 Игроки", "admpl:list"), B("🕸 Шопы", "admsh")], [B("📣 Рассылка", "admin:bcast")]]
    if p.get("bc"):
        L.append("\n📣 Черновик рассылки:\n" + p["bc"])
        rows.insert(0, [B(f"✅ Отправить всем ({len(allp) - banned})", "admin:bsend"), B("🗑 Стереть", "admin:bclear")])
    rows.append(back("admin"))
    return "\n".join(L), rows


def act_admin(p, a, arg):
    if not is_admin(p):
        return "нет доступа"
    if a == "bcast":
        p["await"] = "bcast"
        return "пришли текст рассылки одним сообщением"
    if a == "bclear":
        p["bc"] = ""
        return "черновик стёрт"
    if a == "bsend" and p.get("bc"):
        n = 0
        for q in _all_players():
            if not q.get("ban"):
                _note(q["uid"], "📣 " + p["bc"])
                n += 1
        p["bc"] = ""
        return f"рассылка в очереди: {n} получателей"
    return ""


def r_admpl(p, page=0):
    if not is_admin(p):
        return "нет доступа", [back("admpl")]
    sel = p.get("adm_sel", 0)
    if sel:
        t = _pl(sel, p)
        if t:
            ds = t.get("ds") or {}
            jail_left = max(0, int(t.get("jail", 0) - time.time())) if t.get("jail") else 0
            dis_list = ", ".join(t.get("dis", {}).keys()) or "здоров"
            add_list = ", ".join(f"{k}:{int(v)}" for k, v in t.get("add", {}).items()) or "нет"
            L = [
                f"👤 <b>{t['name']}</b> (ID: <code>{t['uid']}</code>, {age(t)} лет)" + (" · 🚫 <b>БАН</b>" if t.get("ban") else ""),
                f"💵 Кэш: <b>{fmt(t['cash'])}$</b> · 🏦 Банк: <b>{fmt(t['bank'])}$</b> · 💰 Networth: <b>{fmt(networth(t))}$</b>",
                f"❤️ HP: {int(t['hp'])}/100 · ⚡ Энергия: {int(t['energy'])}/100 · 🍗 Голод: {int(t.get('hunger',0))}",
                f"⛓️ Тюрьма: {jail_left}с · 🚨 Розыск: {int(t.get('heat',0))}",
                f"🦠 Болезни: {dis_list}",
                f"🧪 Зависимости: {add_list}",
                f"📦 Инвентарь: {sum(t.get('inv', {}).values())} предм. в наличии",
            ]
            if p.get("adm_logs") == sel:
                logs = t.get("log", [])[-20:]
                L.append("\n🕵️ <b>ПОСЛЕДНИЕ СОБЫТИЯ / ЛОГ ИГРОКА (20):</b>")
                if logs:
                    for idx, x in enumerate(logs, 1):
                        L.append(f"{idx}. {x}")
                else:
                    L.append("<i>Лог пуст</i>")

            rows = [
                [B("💰 +10k$", "admpl:give:10000"), B("💰 +100k$", "admpl:give:100000"),
                 B("💸 −10k$", "admpl:take:10000"), B("💸 −100k$", "admpl:take:100000")],
                [B("💵 Задать сумму вручную (+ / -)", "admpl:cash_custom")],
                [B("⛓️ В тюрьму (5 мин)", "admpl:jail:300"), B("⛓️ В тюрьму (30 мин)", "admpl:jail:1800"), B("🔓 Выпустить", "admpl:free")],
                [B("❤️ Вылечить всё", "admpl:heal"), B("🦠 Заразить", "admpl:infect")],
                [B("📦 Очистить инвентарь", "admpl:clr_inv"), B("🕵️ " + ("Скрыть лог" if p.get("adm_logs") == sel else "Лог действий (20)"), "admpl:logs")],
                [B("💀 Убить персонажа", "admpl:kill"), B("✅ Разбанить" if t.get("ban") else "🚫 Бан", "admpl:ban")],
            ]
            if t.get("ds_ban"):
                rows.append([B("🕸 Разрешить публичный шоп", "admpl:shopok")])
            rows.append([B("⚠️ Точно сбросить? ДА" if p.get("adm_cf") == sel else "🗑️ Полный вайп аккаунта", "admpl:wipe2" if p.get("adm_cf") == sel else "admpl:wipe")])
            rows.append([B("🔙 Список игроков", "admpl:list")])
            return "\n".join(L), rows
        p["adm_sel"] = 0
    allp = sorted(_all_players(), key=networth, reverse=True)
    rows = paged("admpl", allp, page, 6, lambda q: [B(f"{q['name'][:12]} · {q['uid']}" + (" 🚫" if q.get("ban") else ""), f"admpl:sel:{q['uid']}")])
    rows.append([B("🔎 Найти по id", "admpl:find")])
    rows.append(back("admpl"))
    return f"👥 Игроки: {len(allp)}", rows


def act_admpl(p, a, arg):
    if not is_admin(p):
        return "нет доступа"
    if a == "list":
        p["adm_sel"], p["adm_cf"], p["adm_logs"] = 0, 0, 0
        return ""
    if a == "find":
        p["await"] = "admfind"
        return "пришли числовой id игрока"
    if a == "sel":
        p["adm_sel"], p["adm_cf"] = int(arg), 0
        return ""
    sel = p.get("adm_sel", 0)
    t = _pl(sel, p) if sel else None
    if not t:
        p["adm_sel"] = 0
        return "игрок не найден"
    other = sel in ADMINS and sel != p["uid"]
    msg = ""
    if a == "give":
        amt = int(arg)
        t["cash"] += amt
        logp(t, f"администратор начислил {fmt(amt)}$")
        msg = f"{t['name']}: +{fmt(amt)}$"
    elif a == "take":
        if other:
            return "другого админа не трогаем"
        amt = int(arg)
        t["cash"] = max(0.0, t["cash"] - amt)
        logp(t, f"администратор списал {fmt(amt)}$")
        msg = f"{t['name']}: −{fmt(amt)}$"
    elif a == "cash_custom":
        if other:
            return "другого админа не трогаем"
        p["await"] = "admcash"
        return f"пришли сумму для {t['name']} (например 50000 или -25000)"
    elif a == "jail":
        if other:
            return "админа нельзя посадить"
        sec = int(arg)
        t["jail"] = time.time() + sec
        t["heat"] += 30
        logp(t, f"посажен администрацией на {sec}с")
        msg = f"{t['name']} посажен на {sec} сек"
    elif a == "free":
        t["jail"] = 0
        t["heat"] = 0.0
        logp(t, "досрочно освобождён администрацией")
        msg = f"{t['name']} освобождён, розыск сброшен"
    elif a == "heal":
        t["hp"], t["energy"], t["hunger"] = 100.0, 100.0, 0.0
        t["mood"] = 100.0
        t["dis"] = {}
        t["add"] = {}
        t["drunk"] = 0.0
        t["hang"] = 0.0
        logp(t, "полностью исцелён администратором")
        msg = "полное здоровье, болезни и зависимости сняты"
    elif a == "infect":
        if other:
            return "другого админа не заражаем"
        t["dis"]["covid"] = time.time()
        t["dis"]["foodp"] = time.time()
        t["hp"] = max(15.0, t["hp"] - 40.0)
        logp(t, "заражён вирусом")
        msg = f"{t['name']} заражён COVID-19 и пищевым отравлением"
    elif a == "clr_inv":
        if other:
            return "инвентарь админа не трогаем"
        t["inv"] = {}
        logp(t, "инвентарь очищен администратором")
        msg = "инвентарь игрока полностью очищен"
    elif a == "logs":
        p["adm_logs"] = 0 if p.get("adm_logs") == sel else sel
        return "лог переключен"
    elif a == "kill":
        if other or sel == p["uid"]:
            return "себя и других админов убивать нельзя"
        t["cod"] = "приказ администрации"
        t["hp"] = 0.0
        logp(t, "персонаж умерщвлён администрацией")
        dead_msg = finalize(t)
        _put(t, p)
        return f"персонаж {t['name']} ликвидирован: {dead_msg or 'погиб'}"
    elif a == "ban":
        if other or sel == p["uid"]:
            return "себя и других админов банить нельзя"
        t["ban"] = not t.get("ban", False)
        msg = "забанен" if t["ban"] else "разбанен"
    elif a == "shopok":
        t["ds_ban"] = False
        msg = "публичный шоп разрешён"
    elif a == "wipe":
        if other or sel == p["uid"]:
            return "себя и других админов не вайпаем"
        p["adm_cf"] = sel
        return "подтверди вайп кнопкой ещё раз"
    elif a == "wipe2":
        if p.get("adm_cf") != sel or other or sel == p["uid"]:
            p["adm_cf"] = 0
            return "вайп отменён"
        shop_teardown(sel, p, "аккаунт сброшен администрацией")
        fresh = new_player(sel, t.get("name", "Аноним"))
        fresh["ban"] = t.get("ban", False)
        save(fresh)
        p["adm_cf"], p["adm_sel"] = 0, 0
        return "аккаунт сброшен"
    _put(t, p)
    return msg


def r_admsh(p, page=0):
    if not is_admin(p):
        return "нет доступа", [back("admsh")]
    shops = pub_shops()
    rows = paged("admsh", shops, page, 6, lambda t: [B(f"🗑 {t[1]['ds']['domain']} · {t[1]['name'][:10]}", f"admsh:kill:{t[0]}")])
    rows.append(back("admsh"))
    return f"🕸 Публичные шопы: {len(shops)}. Кнопка закрывает шоп, возвращает заказы и запрещает владельцу публичный шоп (снимается в карточке игрока).", rows


def act_admsh(p, a, arg):
    if not is_admin(p):
        return "нет доступа"
    if a == "kill":
        uid = int(arg)
        shop_teardown(uid, p, "шоп закрыт администрацией")
        o = _pl(uid, p)
        if o and o.get("ds"):
            o["ds"]["domain"] = ""
            o["ds_ban"] = True
            logp(o, "публичный шоп закрыт администрацией")
            _put(o, p)
            _note(uid, "🕸 твой публичный шоп закрыт администрацией")
        return "шоп закрыт, заказы возвращены"
    return ""


_main_r5 = RENDER["main"]


def r_main_adm(p, page=0):
    text, rows = _main_r5(p, page)
    if is_admin(p):
        rows = list(rows) + [[B("🛠 Админ", "admin")]]
    return text, rows


# ───────── текстовые ответы (домен / рассылка / поиск по id / сумма) ─────────
KEEP_AWAIT = {("dshop", "domain"), ("admin", "bcast"), ("admpl", "find"), ("admpl", "cash_custom")}


def text_await(p, txt):
    aw = p.get("await", "")
    if not aw:
        return None
    if aw == "domain":
        return "dshop", domain_set(p, txt)
    if is_admin(p) and aw == "bcast":
        p["bc"], p["await"] = txt[:1000], ""
        return "admin", "черновик готов, проверь и отправь"
    if is_admin(p) and aw == "admfind":
        try:
            uid = int(txt.strip())
        except ValueError:
            return "admpl", "нужен числовой id"
        if not _pl(uid, p):
            return "admpl", "такого игрока нет"
        p["adm_sel"], p["adm_cf"], p["await"] = uid, 0, ""
        return "admpl", ""
    if is_admin(p) and aw == "admcash":
        sel = p.get("adm_sel", 0)
        t = _pl(sel, p) if sel else None
        p["await"] = ""
        if not t:
            return "admpl", "игрок не выбран"
        try:
            delta = float(txt.replace(" ", "").replace("$", ""))
        except ValueError:
            return "admpl", "неверный формат числа"
        if delta >= 0:
            t["cash"] += delta
            logp(t, f"администратор выдал {fmt(delta)}$")
            _put(t, p)
            return "admpl", f"{t['name']}: выдано +{fmt(delta)}$"
        else:
            t["cash"] = max(0.0, t["cash"] + delta)
            logp(t, f"администратор списал {fmt(abs(delta))}$")
            _put(t, p)
            return "admpl", f"{t['name']}: списано {fmt(abs(delta))}$"
    p["await"] = ""
    return None


