# [3y] PACK 9: школа 14-17 · армия в 18 · отсрочка · будильник · госучреждения · работы · авто и тюнинг · отпуска · девушка+
# ══════════════════════════════════════════════════════════════════════
kSchoolFrom, kSchoolTo, kSchoolHours = 8, 12, 5     # окно уроков и сколько часов они съедают (игровые часы)
kSchoolEnergy = 8
kSchoolMaxReprim = 3                                # столько выговоров, и тебя исключают
kSchoolCleanStreak = 5                              # столько учебных дней подряд без прогулов снимают один выговор
kTruancyForgive = 1800                              # сек оффлайна, за которые прогулы не засчитываются
kArmySec = 600                                      # срок службы, реальные секунды
kArmyOrders = 8                                     # приказов за службу
kOrderWindow = 90                                   # сек на ответ по приказу
kArmyPenalty = 60                                   # сек к сроку за неверный ответ или пропущенный приказ
kArmyPay = R(6000)
kDraftMaxAge = 27                                   # старше не призывают
kGrandfather = True                                 # кто был 18+ до патча, считается отслужившим
kOversleepChance = 0.5                              # шанс проспать ночной сон без будильника
kAlarmWindow = 40 * 60                              # игровые сек: окно, в которое придёт пуш будильника
kPassCost = R(5000)
kBudgetInt = 10                                     # интеллект для бюджетного места
kTripCd = 1200                                      # сек между отпусками
kPolyEnergy = 6

WD = ("пн", "вт", "ср", "чт", "пт", "сб", "вс")
INST = {"inst", "instb", "uni", "mag"}              # учёба, которая даёт отсрочку от армии
COURSES.update({
    "inst": ("Институт (платно)", 8000, 40, 0, 2, "int", 15, 600),
    "instb": ("Институт (бюджет)", 0, 40, 0, 2, "int", 15, 600),
})
_CARS_BASE = None


def _gday(p):
    _CTX["off"] = p.get("toff", 0)
    return int(_gts() // 86400)


def _wd(day):
    return (day + 3) % 7                             # 0 = пн


def _sch(p):
    s = p.get("sch")
    if not s or s.get("born") != p["born"] or (age(p) < 18 and s.get("done")):
        old = age(p) >= 18
        s = p["sch"] = {"born": p["born"], "day": _gday(p), "att": False, "rep": 0, "exp": False, "cert": old,
                        "done": old, "streak": 0, "t": time.time(), "tot": 0}
    return s


def _mil(p):
    m = p.get("mil")
    if not m or m.get("born") != p["born"] or (age(p) < 18 and m.get("st") in ("done", "serving")):
        old = age(p) >= 18 and kGrandfather
        m = p["mil"] = {"born": p["born"], "st": "done" if old else "none", "ex": old, "ord": [], "t0": 0, "end": 0,
                        "pen": 0, "okc": 0}
    return m


def _note_p(p, text):
    logp(p, text)
    _note(p["uid"], text)


def _deferred(p):
    s = p.get("study")
    return bool(s) and s.get("c") in INST


# ───────── школа ─────────
def _sch_day(p, s, d, attended):
    if s["exp"] or _wd(d) >= 5:
        return
    if attended:
        s["streak"] += 1
        if s["streak"] % kSchoolCleanStreak == 0 and s["rep"] > 0:
            s["rep"] -= 1
            _note_p(p, f"📘 безупречная посещаемость: выговор снят ({s['rep']}/{kSchoolMaxReprim})")
        return
    if p["dis"] or p["jail"]:
        return                                       # справка от врача / ты за решёткой
    s["streak"] = 0
    s["rep"] += 1
    p["mood"] -= 3
    if s["rep"] >= kSchoolMaxReprim:
        s["exp"] = True
        p["mood"] -= 15
        _note_p(p, "🏫 тебя исключили из школы за прогулы. институт закрыт")
    else:
        _note_p(p, f"🏫 прогул: выговор {s['rep']}/{kSchoolMaxReprim}")


def sch_tick(p):
    s = _sch(p)
    if age(p) >= 18:
        if not s["done"]:
            s["done"] = True
            if not s["exp"]:
                s["cert"] = True
                p["mood"] += 10
                logp(p, "🎓 школа окончена: аттестат получен")
        return
    day, now = _gday(p), time.time()
    if day != s["day"]:
        if now - s["t"] <= kTruancyForgive:
            for d in range(s["day"], min(day, s["day"] + 3)):
                _sch_day(p, s, d, s["att"] if d == s["day"] else False)
        s["day"], s["att"] = day, False
    s["t"] = now


def act_school(p, a, arg):
    s = _sch(p)
    if a != "go":
        return ""
    if age(p) >= 18:
        return "школа уже позади"
    if s["exp"]:
        return "тебя исключили. в школу не пускают"
    day = _gday(p)
    if _wd(day) >= 5:
        return f"сегодня выходной ({WD[_wd(day)]})"
    if s["att"]:
        return "сегодня уже отсидел"
    h = _hour()
    if h < kSchoolFrom:
        return f"уроки с {kSchoolFrom}:00, сейчас {_clock()}"
    if h >= kSchoolTo:
        return f"уроки кончились в {kSchoolTo}:00. сегодня ты опоздал"
    if p["energy"] < kSchoolEnergy:
        return "нет сил на уроки"
    p["energy"] -= kSchoolEnergy
    p["mood"] -= 2
    p["hunger"] += 6
    p["skill"]["int"] += 0.4
    s["att"] = True
    s["tot"] += 1
    p["toff"] = p.get("toff", 0) + kSchoolHours * 3600
    _CTX["off"] = p["toff"]
    return f"отсидел уроки, сейчас {_clock()}. интеллект растёт"


def r_school(p, page=0):
    s = _sch(p)
    day = _gday(p)
    L = [f"🏫 Школа · {WD[_wd(day)]} {_clock()}"]
    rows = []
    if age(p) >= 18:
        L.append("школа окончена" + (", аттестат на руках" if s["cert"] else ", аттестата нет: исключили"))
    elif s["exp"]:
        L.append("❌ Исключён за прогулы. Института не будет.")
    else:
        L.append(f"Выговоры: {s['rep']}/{kSchoolMaxReprim}. На {kSchoolMaxReprim}-м исключат.")
        L.append(f"Уроки пн-пт {kSchoolFrom}:00-{kSchoolTo}:00 по игровым часам. Пропуск = выговор. Болезнь и тюрьма не считаются.")
        L.append("✅ сегодня отсидел" if s["att"] else ("😴 сегодня выходной" if _wd(day) >= 5 else "⏳ сегодня ещё не был"))
        L.append(f"Без прогулов подряд: {s['streak']}. Каждые {kSchoolCleanStreak} дня снимают выговор. Не проспи: будильник в телефоне.")
        rows.append([B("📚 Идти на уроки", "school:go")])
    rows.append(back("school"))
    return "\n".join(L), rows


# ───────── армия ─────────
ARMY_ORDERS = [
    ("Рота, подъём! Построение на плацу.", "Встать в строй", "Доспать пять минут", "Спросить, который час"),
    ("Рядовой, тридцать отжиманий. Время пошло.", "Отжаться", "Пожаловаться на спину", "Попросить воды"),
    ("Наряд по кухне: чистить картошку.", "Взять нож и чистить", "Уйти в курилку", "Позвать повара вместо себя"),
    ("Строевая подготовка. Шагом марш!", "Идти в ногу", "Идти как удобно", "Смотреть по сторонам"),
    ("Проверка заправки коек.", "Заправить по уставу", "Накрыть одеялом комом", "Лечь сверху"),
    ("Кросс три километра.", "Бежать со всеми", "Срезать через кусты", "Сесть у забора"),
    ("Мыть полы в казарме.", "Взять швабру", "Пролить ведро и уйти", "Позвать дневального"),
    ("Подмести плац.", "Подметать", "Пересыпать листья соседу", "Сделать вид, что подметаешь"),
    ("Караул у ворот. Заступить на пост.", "Заступить на пост", "Задремать в будке", "Отойти за чаем"),
    ("Политзанятие. Конспект.", "Писать конспект", "Рисовать в тетради", "Спать с открытыми глазами"),
    ("Погрузка ящиков на склад.", "Грузить", "Пересчитывать ящики часами", "Сесть на ящик"),
    ("Чистка сапог. Проверка через пять минут.", "Чистить до блеска", "Намазать кремом сверху", "Одолжить чужие"),
]


def _army_active(m, now):
    for j, o in enumerate(m["ord"]):
        if not o["ok"] and not o["late"] and o["due"] <= now:
            return j, o
    return None, None


def _army_start(p):
    m = _mil(p)
    now = time.time()
    gap = kArmySec / (kArmyOrders + 1)
    ks = random.sample(range(len(ARMY_ORDERS)), min(kArmyOrders, len(ARMY_ORDERS)))
    while len(ks) < kArmyOrders:
        ks.append(random.randrange(len(ARMY_ORDERS)))
    m.update(st="serving", t0=now, end=now + kArmySec, pen=0, okc=0, ex=False,
             ord=[{"k": k, "due": now + gap * (j + 1), "ok": False, "late": False, "push": False,
                   "perm": random.sample([0, 1, 2], 3)} for j, k in enumerate(ks)])
    p["await"] = ""
    logp(p, f"🪖 призыв: служба {kArmySec // 60} мин")


def _army_end(p, push):
    m = _mil(p)
    m["okc"] = sum(1 for o in m["ord"] if o["ok"])
    m["st"] = "done"
    p["cash"] += kArmyPay
    p["mood"] += 10
    p["skill"]["str"] += 4
    txt = f"🪖 дембель! приказов выполнено {m['okc']}/{len(m['ord'])}, нарядов вне очереди {m['pen']}. выплатили {fmt(kArmyPay)}$"
    logp(p, txt)
    if push:
        _note(p["uid"], txt)


def _army_sweep(p, now, push=False):
    m = _mil(p)
    if m["st"] != "serving":
        return
    p["hunger"] = min(p["hunger"], 60)               # в части кормят и спать дают
    p["energy"] = max(p["energy"], 25)
    for o in m["ord"]:
        if not o["ok"] and not o["late"] and now > o["due"] + kOrderWindow:
            o["late"] = True
            m["end"] += kArmyPenalty
            m["pen"] += 1
    if now >= m["end"] and all(o["ok"] or o["late"] for o in m["ord"]):
        _army_end(p, push)


def mil_tick(p):
    m = _mil(p)
    a = age(p)
    if m["st"] == "none":
        if a > kDraftMaxAge:
            m["st"], m["ex"] = "done", True
        elif a >= 18 and not _deferred(p):
            _army_start(p)
    if m["st"] == "serving":
        _army_sweep(p, time.time())


def act_army(p, a, arg):
    m = _mil(p)
    if m["st"] != "serving":
        return ""
    now = time.time()
    if a == "ans":
        j, _, k = arg.partition("_")
        j, k = int(j), int(k)
        o = m["ord"][j]
        if o["ok"] or o["late"] or o["due"] > now:
            return "этот приказ уже неактуален"
        if o["perm"][k] == 0:
            o["ok"] = True
            p["energy"] -= 2
            return "так точно! приказ выполнен"
        m["end"] += kArmyPenalty
        m["pen"] += 1
        return f"не по уставу: наряд вне очереди, +{kArmyPenalty} сек к сроку"
    return ""


def _mmss(sec):
    sec = max(0, int(sec))
    return f"{sec // 60}:{sec % 60:02d}"


def r_army(p, page=0):
    m = _mil(p)
    now = time.time()
    a = age(p)
    if m["st"] == "serving":
        done = sum(1 for o in m["ord"] if o["ok"])
        L = [f"🪖 Служба · до дембеля {_mmss(m['end'] - now)}",
             f"Приказов выполнено {done}/{len(m['ord'])}, нарядов вне очереди {m['pen']}"]
        rows = []
        j, o = _army_active(m, now)
        if o:
            opts = ARMY_ORDERS[o["k"]]
            L += ["", f"❗ Приказ: {opts[0]}", f"Ответь по уставу, осталось {max(0, int(o['due'] + kOrderWindow - now))} сек."]
            for k in range(3):
                rows.append([B(opts[1 + o["perm"][k]], f"army:ans:{j}_{k}")])
        else:
            nxt = next((x for x in m["ord"] if not x["ok"] and not x["late"] and x["due"] > now), None)
            L += ["", "Приказов нет, стоишь смирно." + (f" Следующий через ~{int(nxt['due'] - now)} сек." if nxt else " Ждёшь дембель.")]
            rows.append([B("🔄 Проверить", "army:chk")])
        L.append("Служба идёт в реальном времени. Пока не отслужил, всё остальное закрыто. Пропустишь приказ: наряд и срок дольше.")
        return "\n".join(L), rows
    L = ["🪖 Военкомат"]
    if m["st"] == "done":
        L.append("Военный билет: " + ("не подлежишь призыву." if m.get("ex") else
                                      f"отслужил. приказов {m['okc']}/{kArmyOrders}, нарядов {m['pen']}."))
    elif a < 18:
        L += [f"Тебе {a}. В 18 призыв: служба {kArmySec // 60} минут реального времени, выполняешь все приказы.",
              f"Отсрочка: поступи в институт (с 17 лет) и учись. Бросил или закончил, и тебя призовут (до {kDraftMaxAge} лет)."]
    elif _deferred(p):
        L.append("Отсрочка действует, пока ты учишься в институте. Закончишь или бросишь: повестка.")
    return "\n".join(L), [back("army")]


# ───────── будильник ─────────
def _alarm_ok(p):
    ph, al = p.get("ph"), p.get("al")
    if not ph or not al or not al.get("al_on"):
        return False
    ph_refresh(p)
    return ph["bat"] > 0


def _skip_time(p):
    """ночной сон будит по будильнику; без него можно проспать до обеда. дневной сон как раньше"""
    h = _hour()
    s = _gts() % 86400
    if h >= 20 or h < 6:
        al = p.get("al")
        if _alarm_ok(p):
            wh, wm = al["h"], al["m"]
            al["last"] = _gday(p)
            p["_wk"] = f"⏰ будильник поднял в {wh:02d}:{wm:02d}"
        elif random.random() < kOversleepChance:
            wh, wm = random.randint(12, 15), random.randint(0, 59)
            p["_wk"] = "😴 проспал до обеда. без будильника так и бывает"
        else:
            wh, wm = kWakeHour, random.randint(0, 50)
        delta = ((wh * 3600 + wm * 60) - s) % 86400 or 86400
    else:
        delta = kNapHours * 3600
    p["toff"] = p.get("toff", 0) + delta
    _CTX["off"] = p["toff"]
    p["hunger"] += delta / 3600 * 1.5
    return int(round(delta / 3600))


def _wake_note(fn):
    def w(p, a, arg):
        p.pop("_wk", None)
        msg = fn(p, a, arg)
        wk = p.pop("_wk", None)
        return msg + ("\n" + wk if wk and msg else "")
    return w


def act_alarm(p, a, arg):
    if not p.get("ph"):
        return "нужен телефон"
    if a == "set":
        h, _, m = arg.partition("_")
        p["al"] = {"h": int(h), "m": int(m), "al_on": True, "last": -1}
        return f"будильник на {int(h):02d}:{int(m):02d}"
    al = p.get("al")
    if al and a in ("on", "off"):
        al["al_on"] = a == "on"
        return "будильник " + ("включён" if al["al_on"] else "выключен")
    return ""


def r_alarm(p, page=0):
    ph, al = p.get("ph"), p.get("al")
    if not ph:
        return "⏰ Нужен телефон.", [[B("🛒 Салон связи", "pshop")], back("alarm")]
    L = ["⏰ Будильник", f"🕒 сейчас {_clock()} · 🔋 {int(ph['bat'])}%"]
    if al:
        L.append(f"Стоит на {al['h']:02d}:{al['m']:02d}: " + ("включён" if al["al_on"] else "выключен"))
    else:
        L.append("Не заведён. Без него ночью можно проспать до обеда и школу.")
    L.append("Ночной сон просыпается по нему, плюс звонок падает в чат. Сядет батарея: не прозвонит.")
    times = [(5, 30), (6, 0), (6, 30), (7, 0), (7, 30), (8, 0)]
    rows = [[B(f"{h:02d}:{m:02d}", f"alarm:set:{h}_{m}") for h, m in times[i:i + 3]] for i in (0, 3)]
    if al:
        rows.append([B("🔕 Выключить", "alarm:off") if al["al_on"] else B("🔔 Включить", "alarm:on")])
    rows.append(back("alarm"))
    return "\n".join(L), rows


# ───────── институт и отсрочка ─────────
_edu_a0, _edu_r0 = ACT["edu"], RENDER["edu"]


def act_edu_p9(p, a, arg):
    if a == "start" and arg in ("inst", "instb"):
        s = _sch(p)
        if age(p) < 17:
            return "поступать можно с 17 лет"
        if s["exp"]:
            return "исключённых из школы в институт не берут"
        if arg == "instb" and p["skill"]["int"] < kBudgetInt:
            return f"не хватило баллов на бюджет: нужен интеллект {kBudgetInt}, у тебя {p['skill']['int']:.0f}"
    before = _mil(p)["st"]
    r = _edu_a0(p, a, arg)
    if a == "start" and arg in INST and p["study"] and p["study"]["c"] == arg:
        r += "\n🪖 отсрочка от армии: пока учишься"
    mil_tick(p)
    if before != "serving" and _mil(p)["st"] == "serving":
        r += "\n🪖 отсрочка кончилась: пришла повестка"
    return r


def r_edu_p9(p, page=0):
    text, rows = _edu_r0(p, page)
    out = []
    for r in rows:
        r2 = []
        for t, d in r:
            if d in ("edu:start:inst", "edu:start:instb") and (age(p) < 17 or _sch(p)["exp"]):
                t = "🔒" + t[1:]
            r2.append((t, d))
        out.append(r2)
    if _deferred(p):
        text += "\n🪖 Отсрочка от армии действует, пока учишься."
    elif _mil(p)["st"] == "none":
        text += (f"\n🪖 Институт даёт отсрочку от армии. Поступать с 17 лет. Бюджет бесплатный, нужен интеллект {kBudgetInt}"
                 f" (у тебя {p['skill']['int']:.0f}).")
    return text, out


# ───────── бесплатные учреждения ─────────
POLY_CURE = {"cold", "flu", "bronch", "foodp", "allerg", "migr", "conc", "insom", "tooth"}


def _gov_hours(a=9, b=18):
    return a <= _hour() < b


def act_gov(p, a, arg):
    now = time.time()
    if a == "poly":
        if not _gov_hours():
            return "поликлиника с 9 до 18"
        if cdleft(p, "poly") > 0:
            return "тебя только что принимали, приходи позже"
        if p["energy"] < kPolyEnergy:
            return "нет сил стоять в очереди"
        p["energy"] -= kPolyEnergy
        p["hunger"] += 4
        p["cd"]["poly"] = now + 600
        p["toff"] = p.get("toff", 0) + 3 * 3600
        _CTX["off"] = p["toff"]
        p["rx"] = max(p["rx"], now + DAY / 2)
        found, cured = [], []
        for k, d in p["dis"].items():
            d["dx"] = True
            found.append(DIS[k][0])
        for k in list(p["dis"]):
            if k in POLY_CURE and random.random() < 0.4:
                p["dis"].pop(k)
                cured.append(DIS[k][0])
        msg = "отсидел очередь ~3 часа, принял терапевт. рецепт на аптеку выдан."
        if found:
            msg += " Диагнозы: " + ", ".join(found) + "."
        if cured:
            msg += " Вылечили: " + ", ".join(cured) + "."
        return msg
    if a == "kitchen":
        if p["cash"] > R(2000):
            return f"столовая для тех, у кого на руках меньше {fmt(R(2000))}$"
        if cdleft(p, "kit") > 0:
            return "уже кормили, приходи позже"
        p["cd"]["kit"] = now + 900
        p["hunger"] = max(0, p["hunger"] - 35)
        p["mood"] -= 1
        p["energy"] -= 2
        return "бесплатный обед: суп и хлеб. неловко, зато сытно"
    if a == "shelter":
        if p["home"] != "street":
            return "приют для тех, у кого нет жилья"
        if cdleft(p, "shel") > 0:
            return "мест нет, приходи позже"
        p["cd"]["shel"] = now + 900
        p["energy"] = min(100, p["energy"] + 50)
        p["hp"] += 5
        p["mood"] -= 2
        h = _skip_time(p)
        return f"переночевал в приюте: тесно, зато тепло (прошло ~{h} ч)" + ("\n" + p.pop("_wk") if p.get("_wk") else "")
    if a == "library":
        if not _gov_hours(10, 20):
            return "библиотека с 10 до 20"
        if p["energy"] < 4:
            return "нет сил"
        p["energy"] -= 4
        p["hunger"] += 1
        p["mood"] += 2
        p["skill"]["int"] += 0.5
        return "посидел в библиотеке: +0.5 к интеллекту, бесплатно"
    if a == "jobc":
        if not _gov_hours():
            return "центр занятости с 9 до 18"
        if cdleft(p, "jobc") > 0:
            return "курс только что был, приходи позже"
        if p["energy"] < 6:
            return "нет сил"
        p["energy"] -= 6
        p["cd"]["jobc"] = now + 900
        p["xp"] += 40
        return "бесплатный курс в центре занятости: +40 опыта"
    if a == "passport":
        if p.get("pass"):
            return "загранпаспорт уже есть"
        if not _gov_hours():
            return "МФЦ с 9 до 18"
        if p["cash"] < kPassCost:
            return f"нужно {fmt(kPassCost)}$"
        p["cash"] -= kPassCost
        p["pass"] = True
        return "загранпаспорт готов: можно за границу"
    if a == "mfc":
        if cdleft(p, "mfc") > 0:
            return "в МФЦ можно обращаться раз в сутки"
        p["cd"]["mfc"] = now + 86400
        tax_refund = 1200
        p["cash"] += tax_refund
        p["mood"] += 5
        return f"🏛️ Ты подал заявление в МФЦ: оформлен налоговый вычет +{tax_refund}$!"
    if a == "donor":
        if cdleft(p, "donor") > 0:
            return "донорство разрешено раз в 3 дня"
        if p["hp"] < 30 or p["energy"] < 20:
            return "гемоглобин низкий, организм истощен"
        p["cd"]["donor"] = now + 86400 * 3
        p["hp"] -= 10
        p["energy"] -= 20
        donor_pay = 800
        p["cash"] += donor_pay
        p["mood"] += 15
        return f"🩸 Ты сдал кровь на станции переливания: компенсация +{donor_pay}$ и горячий чай!"
    if a == "nii":
        if p["energy"] < 25:
            return "нет сил для участия в испытаниях"
        p["energy"] -= 25
        if random.random() < 0.25:
            p["dis"]["flu"] = now
            p["hp"] = max(10, p["hp"] - 25)
            p["cash"] += 3000
            return "🔬 Испытания в НИИ: получено 3 000$, но проявился побочный эффект (грипп)"
        else:
            p["cash"] += 2500
            p["mood"] += 10
            return "🔬 Успешное участие в испытаниях НИИ: начислено 2 500$!"
    if a == "mil_dept":
        if p["edu"] < 2:
            return "военная кафедра доступна только студентам института (высшее образование)"
        m = _mil(p)
        if m["st"] == "done":
            return "ты уже отслужил / в запасе"
        m["st"] = "done"
        m["ex"] = False
        p["skill"]["str"] += 5
        return "🎖️ Ты окончил военную кафедру! Присвоено офицерское звание, выдан военный билет (армия не грозит)!"
    if a == "court":
        if cdleft(p, "court") > 0:
            return "обращаться в суд можно раз в сутки"
        p["cd"]["court"] = now + 86400
        if p.get("heat", 0) > 0:
            p["heat"] = max(0.0, p["heat"] - 30.0)
            return "⚖️ Мировой суд удовлетворил апелляцию: списано 30 единиц розыска/штрафов!"
        return "⚖️ У тебя нет открытых штрафов и уголовных дел."
    return ""


def r_gov(p, page=0):
    L = [f"🏛 Государственные и бесплатные учреждения · {_clock()}",
         "Поликлиника, МФЦ, суд и центр занятости с 9 до 18, библиотека с 10 до 20.",
         "Бесплатная столовая и ночной приют открыты для малоимущих."]
    rows = [
        [B("🏥 Поликлиника (бесплатно)", "gov:poly"), B("🥣 Бесплатная столовая", "gov:kitchen")],
        [B("🛏 Приют на ночь", "gov:shelter"), B("📚 Библиотека (+интеллект)", "gov:library")],
        [B("🏛 МФЦ (вычет 1 200$)", "gov:mfc"), B("💼 Центр занятости (курс)", "gov:jobc")],
        [B("🩸 Сдать кровь (донор +800$)", "gov:donor"), B("🔬 Эксперименты в НИИ (+2 500$)", "gov:nii")],
        [B("🎖️ Военная кафедра (билет)", "gov:mil_dept"), B("⚖️ Суд (списание розыска)", "gov:court")],
        [B(("✅ " if p.get("pass") else "🛂 ") + f"Загранпаспорт · {fmt(kPassCost)}$", "gov:passport")],
        [B("🎓 Бюджетные места в институте", "edu")],
        back("gov")
    ]
    return "\n".join(L), rows


