def army_sweep_all():
    now = time.time()
    for (uid,) in db.execute("SELECT uid FROM players WHERE data LIKE ?", ('%"st": "serving"%',)).fetchall():
        p = load_raw(uid)
        if not p or (p.get("mil") or {}).get("st") != "serving":
            continue
        m = p["mil"]
        _army_sweep(p, now, True)
        if m["st"] == "serving":
            for o in m["ord"]:
                if not o["ok"] and not o["late"] and o["due"] <= now and not o.get("push"):
                    o["push"] = True
                    _note(uid, f"🪖 Приказ! Зайди в бота, у тебя {kOrderWindow} сек")
        save(p)


def alarm_sweep_all():
    off0 = _CTX["off"]
    try:
        for (uid,) in db.execute("SELECT uid FROM players WHERE data LIKE ?", ('%"al_on": true%',)).fetchall():
            p = load_raw(uid)
            al = (p or {}).get("al")
            if not al or not al.get("al_on") or (p.get("mil") or {}).get("st") == "serving":
                continue
            _CTX["off"] = p.get("toff", 0)
            day = int(_gts() // 86400)
            if (_gts() % 86400 - (al["h"] * 3600 + al["m"] * 60)) % 86400 < kAlarmWindow and al.get("last") != day:
                al["last"] = day
                if (p.get("ph") or {}).get("bat", 0) > 0:
                    _note(uid, f"⏰ Будильник {al['h']:02d}:{al['m']:02d}. Подъём")
                save(p)
    finally:
        _CTX["off"] = off0


_osw_p9 = orders_sweep


def orders_sweep(live=None):
    _osw_p9(live)
    try:
        army_sweep_all()
        alarm_sweep_all()
    except Exception:
        logging.getLogger("reallife").exception("pack9 sweep")


