def _lock_act(fn):
    def w(p, a, arg):
        if _mil(p)["st"] == "serving":
            return "🪖 ты в армии: выполняй приказы"
        return fn(p, a, arg)
    return w


def _lock_render(fn):
    def w(p, page=0):
        if _mil(p)["st"] == "serving":
            return r_army(p, 0)
        return fn(p, page)
    return w


