def p10_init_db(db_conn):
    cur = db_conn.cursor()
    cur.execute("""
    CREATE TABLE IF NOT EXISTS p10_gangs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT UNIQUE,
        leader_id INTEGER,
        balance REAL DEFAULT 0,
        respect INTEGER DEFAULT 0,
        turf TEXT DEFAULT ''
    )
    """)
    cur.execute("""
    CREATE TABLE IF NOT EXISTS p10_gang_members (
        uid INTEGER PRIMARY KEY,
        gang_id INTEGER,
        role TEXT DEFAULT 'member'
    )
    """)
    cur.execute("""
    CREATE TABLE IF NOT EXISTS p10_auctions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT,
        item_code TEXT,
        min_bid REAL,
        cur_bid REAL,
        leader_uid INTEGER,
        leader_name TEXT,
        ends_at REAL
    )
    """)
    cur.execute("""
    CREATE TABLE IF NOT EXISTS p10_marriages (
        uid1 INTEGER,
        uid2 INTEGER,
        married_at REAL,
        shared_rent INTEGER DEFAULT 1,
        PRIMARY KEY (uid1, uid2)
    )
    """)
    cur.execute("""
    CREATE TABLE IF NOT EXISTS p10_debts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        lender_uid INTEGER,
        borrower_uid INTEGER,
        amount REAL,
        due_at REAL
    )
    """)
    cur.execute("""
    CREATE TABLE IF NOT EXISTS p10_trades (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        sender_uid INTEGER,
        target_uid INTEGER,
        offer_text TEXT,
        item_key TEXT,
        item_count INTEGER,
        price REAL,
        status TEXT DEFAULT 'pending'
    )
    """)
    cur.execute("""
    CREATE TABLE IF NOT EXISTS p10_duels (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        challenger_id INTEGER,
        target_id INTEGER,
        bet REAL,
        status TEXT DEFAULT 'open'
    )
    """)
    db_conn.commit()

