def p10_tick(p):
    p10 = p10_init_player(p)
    if random.random() < 0.05:
        p10["weather"] = random.choice(P10_WEATHER_TYPES)
        if "мороз" in p10["weather"] or "жара" in p10["weather"]:
            p["energy"] = max(0, p["energy"] - 2)
    if p10["mining_rigs"] > 0:
        daily_btc = p10["mining_rigs"] * 0.0008
        p10["crypto_btc"] += daily_btc
        p["cash"] = max(0, p["cash"] - p10["mining_rigs"] * 25)
    if p10["sublet_active"] > 0:
        p["cash"] += p10["sublet_active"] * 120
    if p10["franchises"] > 0:
        p["cash"] += p10["franchises"] * 450
    if p10["loan_debt"] > 0:
        interest = p10["loan_debt"] * 0.03
        p10["loan_debt"] += interest

