def act_p10_pvp(p, a, arg):
    p10 = p10_init_player(p)
    if a == "fight":
        tier_cfg = {
            "amateur": (200, 400, 3, 2),
            "pro": (1000, 2200, 7, 5),
            "champ": (5000, 12000, 15, 10),
        }
        cost, win_pay, req_str, rep_gain = tier_cfg.get(arg, (200, 400, 2, 2))
        if p["cash"] < cost:
            return f"❌ Не хватает кэша на взнос ({cost}$)"
        p["cash"] -= cost
        power = p["skill"]["str"] + p10["martial_lvl"] * 2 + random.randint(1, 10)
        enemy_power = req_str + random.randint(1, 12)
        if power >= enemy_power:
            p["cash"] += win_pay
            p10["rep"] = min(100, p10["rep"] + rep_gain)
            p["mood"] = min(100, p["mood"] + 15)
            return f"🏆 ПОБЕДА в октагоне! Ты вырубил соперника и забрал {win_pay}$ (+{rep_gain} к уважению)"
        else:
            p["hp"] = max(10, p["hp"] - 25)
            p["mood"] = max(0, p["mood"] - 10)
            return f"💥 Поражение нокаутом. Ты потерял ставку {cost}$ и получил травмы (-25 HP)"
    elif a == "streetfight":
        if p["energy"] < 15:
            return "❌ Нет сил для уличной потасовки"
        p["energy"] -= 15
        if random.random() < 0.6:
            loot = random.randint(50, 300)
            p["cash"] += loot
            p10["rep"] = min(100, p10["rep"] + 1)
            return f"👊 Ты размазал гопника на районе, отжав {loot}$ (+1 к уважению)"
        else:
            p["hp"] = max(10, p["hp"] - 15)
            return "💥 Тебя зажали в переулке и набили морду (-15 HP)"
    return "Ок"

def act_p10_gangs(p, a, arg):
    p10 = p10_init_player(p)
    if a == "turf":
        turf_name, inc, min_rep = P10_TURFS.get(arg, ("Район", 1000, 20))
        if p10["rep"] < min_rep:
            return f"❌ Слишком малый авторитет для наезда на {turf_name} (нужно {min_rep})"
        if p["energy"] < 25:
            return "❌ Не хватает энергии на зачистку района"
        p["energy"] -= 25
        if random.random() < 0.55:
            p10["racket_income"] += inc // 3
            p10["rep"] = min(100, p10["rep"] + 5)
            return f"🏴 Ты отжал точки в «{turf_name}»! Доход с рэкета вырос на +{inc//3}$/день"
        else:
            p["heat"] = p.get("heat", 0) + 15
            p["hp"] = max(10, p["hp"] - 20)
            return "🚔 На район приехал ОМОН! Облава, получен урон и +15 к розыску"
    elif a == "collect_racket":
        if p10["racket_income"] <= 0:
            return "❌ У тебя пока нет крышуемых точек. Захвати районы!"
        sum_got = p10["racket_income"]
        p["cash"] += sum_got
        return f"💰 Ты собрал дань с коммерсов: +{sum_got}$"
    elif a == "donate":
        if p["cash"] < 5000:
            return "❌ Нужно 5 000$"
        p["cash"] -= 5000
        p10["rep"] = min(100, p10["rep"] + 12)
        return "🤝 Ты закинул 5 000$ в общак синдиката! Авторитет вырос на +12"
    return "Ок"

def act_p10_prison(p, a, arg):
    p10 = p10_init_player(p)
    if a == "sew":
        if p["energy"] < 10:
            return "❌ Слишком устал"
        p["energy"] -= 10
        p["jail"] = max(0, p.get("jail", 0) - 30)
        p["cash"] += 20
        return "🧵 Ты отпахал смену на тюремной швейке: -30 сек от срока, заработал 20$"
    elif a == "craft_shank":
        if p["energy"] < 15:
            return "❌ Нет энергии"
        p["energy"] -= 15
        p10["shanks"] += 1
        return f"🔪 Ты заточил ложку об бетон. Заточка готова! (Всего: {p10['shanks']})"
    elif a == "dig":
        p["energy"] = max(0, p["energy"] - 20)
        p10["escape_prep"] = min(100, p10["escape_prep"] + 15)
        return f"🥄 Ты продолбил часть кирпичной кладки. План побега: {p10['escape_prep']}%"
    elif a == "escape":
        if p10["escape_prep"] < 60:
            return "❌ План не готов! Нужно хотя бы 60% готовности подкопа"
        if random.random() < (p10["escape_prep"] / 100.0):
            p["jail"] = 0
            p10["escape_prep"] = 0
            p["heat"] = p.get("heat", 0) + 50
            return "🏃 ПОБЕГ УДАЛСЯ! Ты прополз через коллектор на свободу! Розыск повышен!"
        else:
            p["jail"] = p.get("jail", 0) + 300
            p10["escape_prep"] = 0
            return "🚨 ВЕРТУХАИ ЗАМЕТИЛИ ТЕБЯ! Побег сорван, карцер и +300 сек к сроку"
    elif a == "hire_lawyer":
        if p["cash"] < 3000:
            return "❌ Адвокат просит 3 000$"
        p["cash"] -= 3000
        p10["lawyer_retained"] = True
        return "⚖️ Адвокат нанят! При аресте срок будет снижен на 70%"
    elif a == "send_parcel":
        if p["cash"] < 1000:
            return "❌ Нужно 1 000$"
        p["cash"] -= 1000
        p10["rep"] = min(100, p10["rep"] + 8)
        return "📦 Ты передал чай, сигареты и сало на зону. Братки оценили (+8 к авторитету)"
    return "Ок"

def act_p10_zags(p, a, arg):
    p10 = p10_init_player(p)
