def act_p10_cars(p, a, arg):
    p10 = p10_init_player(p)
    if a == "carshare":
        if p["cash"] < 30:
            return "❌ Каршеринг стоит 30$"
        p["cash"] -= 30
        p["energy"] = min(100, p["energy"] + 5)
        return "🚗 Поездка на каршеринге совершена с комфортом (-30$)"
    elif a == "buy_insurance":
        if p10["car_ins"]:
            return "❌ КАСКО уже оформлено!"
        if p["cash"] < 1200:
            return "❌ Страховка стоит 1 200$"
        p["cash"] -= 1200
        p10["car_ins"] = True
        return "🛡️ Полис КАСКО активирован на твой автомобиль!"
    elif a == "mod":
        if arg == "turbo":
            if p["cash"] < 3500:
                return "❌ Турбина стоит 3 500$"
            p["cash"] -= 3500
            p10["car_tune"]["turbo"] = "Stage 1"
            return "💨 Турбина установлена! Мощность и скорость выросли!"
        elif arg == "tint":
            if p["cash"] < 400:
                return "❌ Тонировка стоит 400$"
            p["cash"] -= 400
            p10["car_tune"]["tint"] = "5% в круг"
            return "🕶️ Тонировка наклеена! Гаишники не видят, кто за рулем."
    elif a == "dps_check":
        drunk = p.get("drunk", 0)
        if drunk > 20:
            if p["cash"] >= 2000:
                p["cash"] -= 2000
                return "🚔 Тебя остановил ДПС с перегаром! Пришлось отдать взятку 2 000$"
            else:
                p["jail"] = p.get("jail", 0) + 120
                return "🚔 ДПС зафиксировал опьянение! Лишение прав и 120 сек ареста"
        return "🚔 Инспектор проверил документы и отпустил. Всё чисто!"
    return "Ок"

def act_p10_bizplus(p, a, arg):
    p10 = p10_init_player(p)
    if a == "hire_guard":
        if p["cash"] < 500:
            return "❌ Охрана стоит 500$"
        p["cash"] -= 500
        p10["biz_guards"] += 1
        return f"👮 Охранник нанят! Теперь бизнесы защищены от налетов. (Штат: {p10['biz_guards']})"
    elif a == "hire_mgr":
        if p["cash"] < 1200:
            return "❌ Менеджер стоит 1 200$"
        p["cash"] -= 1200
        p10["biz_mgrs"] += 1
        return f"👔 Управляющий нанят! Выручка точек оптимизирована. (Штат: {p10['biz_mgrs']})"
    elif a == "sell_franchise":
        if not p.get("biz"):
            return "❌ Чтобы продавать франшизу, нужен хотя бы один собственный бизнес!"
        p["cash"] += 25000
        p10["franchises"] += 1
        return f"🏷️ Ты продал франшизу! Получено разово 25 000$ + пассивный доход {p10['franchises']*450}$/день"
    elif a == "take_loan":
        if p10["loan_debt"] > 0:
            return "❌ Сначала закрой текущий кредит!"
        p["bank"] += 50000
        p10["loan_debt"] = 60000
        return "🏦 Кредит 50 000$ зачислен на банковский счет! К возврату с процентами: 60 000$"
    elif a == "pay_loan":
        if p10["loan_debt"] <= 0:
            return "❌ У тебя нет долгов по кредитам"
        amt = min(10000, p10["loan_debt"])
        if p["cash"] < amt:
            return f"❌ Нужно {amt}$ кэша"
        p["cash"] -= amt
        p10["loan_debt"] -= amt
        return f"💳 Внесено {amt}$ в счет погашения. Остаток долга: {int(p10['loan_debt'])}$"
    return "Ок"

def act_p10_casino(p, a, arg):
    if a == "bj":
        if p["cash"] < 500:
            return "❌ Ставка 500$"
        p["cash"] -= 500
        p_val = random.randint(15, 21)
        d_val = random.randint(14, 22)
        if d_val > 21 or p_val > d_val:
            p["cash"] += 1000
            p["mood"] = min(100, p["mood"] + 10)
            return f"🃏 БЛЭКДЖЕК! У тебя {p_val}, у дилера {d_val}. Ты выиграл 1 000$!"
        elif p_val == d_val:
            p["cash"] += 500
            return f"🃏 Ничья! У тебя {p_val}, у дилера {d_val}. Ставка 500$ возвращена"
        else:
            return f"🃏 Дилер победил: {d_val} против твоих {p_val}. Проигрыш 500$"
    elif a == "roulette":
        cost = 100 if arg == "zero" else 300
        if p["cash"] < cost:
            return f"❌ Нужно {cost}$"
        p["cash"] -= cost
        spin = random.randint(0, 36)
        if arg == "zero" and spin == 0:
            win = 3600
            p["cash"] += win
            return f"🟢 ЗЕРО! Шарик упал на 0! Невероятный выигрыш: +{win}$!"
        elif arg == "red" and (spin % 2 == 1 and spin != 0):
            p["cash"] += 600
            return f"🔴 Выпало Красное ({spin})! Выигрыш: +600$"
        elif arg == "black" and (spin % 2 == 0 and spin != 0):
            p["cash"] += 600
            return f"⚫ Выпало Чёрное ({spin})! Выигрыш: +600$"
        else:
            return f"💥 Шарик выпал на {spin}. Ставка сгорела."
    elif a == "scratch":
        if p["cash"] < 50:
            return "❌ Билет стоит 50$"
        p["cash"] -= 50
        roll = random.random()
        if roll < 0.05:
            win = 1000
            p["cash"] += win
            return f"🎉 ДЖЕКПОТ В СКРЕТЧ-КАРТЕ! Под защитным слоем три золотых слитка! Выигрыш: {win}$"
        elif roll < 0.35:
            win = 100
            p["cash"] += win
            return f"🎫 Скретч-билет принес {win}$!"
        else:
            return "🎫 Билет пустой. Попробуй ещё!"
    return "Ок"

def act_p10_outdoors(p, a, arg):
    if a == "fish":
        cfg = P10_FISH_LOCATIONS.get(arg, ("Река", 0, (10, 80)))
        cost, (pay_min, pay_max) = cfg[1], cfg[2]
        if p["cash"] < cost:
            return f"❌ Нужны снасти за {cost}$"
        p["cash"] -= cost
        catch_val = random.randint(pay_min, pay_max)
        p["cash"] += catch_val
        p["mood"] = min(100, p["mood"] + 12)
        return f"🎣 Отличный клёв на локации «{cfg[0]}»! Рыба продана в ресторан за {catch_val}$ (+12 настроения)"
    elif a == "hunt":
        if p["cash"] < 1500:
            return "❌ Лицензия на охоту стоит 1 500$"
        p["cash"] -= 1500
        trophy = random.randint(2000, 4500)
        p["cash"] += trophy
        p["mood"] = min(100, p["mood"] + 20)
        return f"🦌 Удачная охота в тайге! Трофеи и мясо сданы скупщикам за {trophy}$"
    return "Ок"

def act_p10_media(p, a, arg):
    p10 = p10_init_player(p)
    if a == "tinder":
        if arg == "swipe":
            p10["tinder_matches"] += 1
            return f"🔥 Взаимный мэтч в Tinder! Всего пар: {p10['tinder_matches']}"
        elif arg == "date":
            if p["cash"] < 250:
                return "❌ Ресторан стоит 250$"
            p["cash"] -= 250
            p["mood"] = min(100, p["mood"] + 25)
            return "🍷 Романтический вечер в ресторане удался! Настроение на максимуме!"
    elif a == "stream":
        if arg == "start":
            donations = random.randint(50, 400) + p10["stream_subs"] * 2
            p["cash"] += donations
            p10["stream_subs"] += random.randint(10, 50)
            return f"📹 Стрим завершен! Получено донатов: {donations}$. Новых подписчиков: +{p10['stream_subs']}"
        elif arg == "upgrade":
            if p["cash"] < 1500:
                return "❌ Нужно 1 500$"
            p["cash"] -= 1500
            p10["stream_gear"] += 1
            return f"🎙️ Сетап обновлен! Уровень аппаратуры: {p10['stream_gear']}"
    return "Ок"

def act_p10_property(p, a, arg):
    p10 = p10_init_player(p)
    if a == "buy_garage":
        if p10["garage"]:
            return "❌ Гараж уже куплен"
        if p["cash"] < 15000:
            return "❌ Гараж стоит 15 000$"
        p["cash"] -= 15000
        p10["garage"] = True
        return "🚪 Капитальный гараж оформлен в собственность! Теперь доступен распил авто и гроубокс."
    elif a == "sublet_add":
        if not p.get("home_own"):
            return "❌ Чтобы сдавать жилье в субаренду, нужно владеть хотя бы одной квартирой!"
        p10["sublet_active"] += 1
        return f"🔑 Комната сдана арендаторам! Ежедневный пассивный доход: +{p10['sublet_active']*120}$"
    elif a == "buy_wholesale":
        if p["cash"] < 2000:
            return "❌ Партия товара стоит 2 000$"
        p["cash"] -= 2000
        p10["wh_goods"] += 10
        return f"📦 Закуплено 10 ящиков товара на оптовом складе (Всего: {p10['wh_goods']})"
    elif a == "sell_wholesale":
        if p10["wh_goods"] <= 0:
            return "❌ Склад пуст"
        revenue = p10["wh_goods"] * 320
        p["cash"] += revenue
        p10["wh_goods"] = 0
        return f"💰 Все товары со склада распроданы в розницу за {revenue}$!"
    elif a == "furn":
        f = P10_FURNITURE.get(arg)
        if not f:
            return "❌ Предмет не найден"
        name, cost, _, _ = f
        if p["cash"] < cost:
            return f"❌ {name} стоит {cost}$"
        p["cash"] -= cost
        p10["furniture"].append(arg)
        return f"🛋️ {name} доставлена и установлена в твоем доме!"
    return "Ок"

def act_p10_wellness(p, a, arg):
    p10 = p10_init_player(p)
    if a == "rehab":
        if p["cash"] < 2500:
            return "❌ Курс детокса стоит 2 500$"
        p["cash"] -= 2500
        p["add"].clear()
        p["hp"] = 100
        return "🧪 Капельницы и детокс очистили кровь! Все зависимости сняты!"
    elif a == "therapist":
        if p["cash"] < 400:
            return "❌ Сеанс стоит 400$"
        p["cash"] -= 400
        p["mood"] = 100
        return "🧠 Сеанс психотерапии помог справиться с выгоранием и депрессией (+100 настроения)"
    elif a == "martial_train":
        if p["cash"] < 200:
            return "❌ Зал стоит 200$"
        p["cash"] -= 200
        p10["martial_lvl"] += 1
        p["skill"]["str"] = min(100, p["skill"]["str"] + 2)
        return f"🥊 Тренировка закончена! Навык бокса вырос до {p10['martial_lvl']}"
    elif a == "cook":
        r = P10_RECIPES.get(arg)
        if not r:
            return "❌ Рецепт не найден"
        name, cost, hunger_drop, mood_up, hp_up = r
        if p["cash"] < cost:
            return f"❌ Продукты стоят {cost}$"
        p["cash"] -= cost
        p["hunger"] = max(0, p["hunger"] - hunger_drop)
        p["mood"] = min(100, p["mood"] + mood_up)
        p["hp"] = min(100, p["hp"] + hp_up)
        p10["meals_prepped"] += 1
        return f"🍳 Ты приготовил вкуснейший {name}! Сытность, здоровье и настроение восстановлены!"
    elif a == "ems":
        if p["cash"] < 1500:
            return "❌ Реанимация стоит 1 500$"
        p["cash"] -= 1500
        p["hp"] = 100
        p["drunk"] = 0
        return "🚑 Бригада скорой помощи стабилизировала состояние: HP 100%!"
    return "Ок"

def act_p10_underground(p, a, arg):
    p10 = p10_init_player(p)
    if a == "dumpster":
        if p["energy"] < 8:
            return "❌ Слишком истощен"
        p["energy"] -= 8
        found_copper = random.randint(2, 8)
        p10["scraps"] += found_copper
        loot_cash = random.randint(10, 60)
        p["cash"] += loot_cash
        return f"🗑️ Ты нашел в баках {found_copper} кг медных трубок и мелочь на {loot_cash}$"
    elif a == "sell_scraps":
        if p10["scraps"] <= 0:
            return "❌ Нет меди для сдачи"
        money = p10["scraps"] * 35
        p["cash"] += money
        got = p10["scraps"]
        p10["scraps"] = 0
        return f"🔌 Сдано {got} кг цветмета в пункт приёма: +{money}$ чистыми"
    elif a == "setup_lab":
        if not p10["garage"]:
            return "❌ Для гроубокса нужен собственный гараж!"
        if p["cash"] < 5000:
            return "❌ Оборудование стоит 5 000$"
        p["cash"] -= 5000
        p10["lab_lvl"] += 1
        p10["lab_ready"] += 5
        return f"🌿 Гроубокс смонтирован в подвале гаража! Первая партия на подходе."
    elif a == "harvest":
        if p10["lab_ready"] <= 0:
            return "❌ Урожай ещё не созрел"
        pay = p10["lab_ready"] * 800
        p["cash"] += pay
        cnt = p10["lab_ready"]
        p10["lab_ready"] = 0
        return f"📦 Собрано и сбыто {cnt} партий через тайники: +{pay}$"
    elif a == "auction_bid":
        if p["cash"] < 10000:
            return "❌ На черном аукционе ставки начинаются от 10 000$"
        p["cash"] -= 10000
        p10["rep"] = min(100, p10["rep"] + 15)
        p["inv"]["good:gold_bar"] = p["inv"].get("good:gold_bar", 0) + 1
        return "🔨 Твоя ставка сыграла! Ты выкупил Золотой слиток (999 проба) на Чёрном аукционе!"
    return "Ок"

